quests[11345] = { id = 11345, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preise für Kugeln" }
quests[11346] = { id = 11346, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Buch der Runen", description = "Das Plateau der Riesen, das weite steinige Gebiet im Südosten, wurde von Eisenzwergen regelrecht überflutet. Späher haben von Zwergen berichtet, die Steinriesen aus dem Boden locken, um dann Runen in ihre Haut zu meißeln.\n\nWas sie dazu treibt ist mir unerklärlich, aber ich vermute, dass sie irgendwie versuchen, aus den Riesen Waffen zu machen. Die Eisenrunensteinrufer und -binder tragen große Folianten bei sich, in denen sich die Runen, die sie in die Haut der Riesen ritzen, befinden müssten.\n\nErbeutet die einzelnen Teile dieses Buches, fügt sie zusammen und bringt mir das Buch, {name}.", sourceObjective = "Ausgrabungsleiter Belvar in Fort Wildervar möchte, dass Ihr ihm das Buch der Runen bringt.", progress = "Habt Ihr das Buch bei Euch?", completion = "<Ausgrabungsleiter Belvar blättert durch das Buch der Runen.>\n\nHmm... hier steht so viel geschrieben. Ich werde eine Weile brauchen, um mich eingehend damit zu befassen - und wenn wir diese Runen verstehen wollen, dann werden wir versuchen müssen, unsere eigenen herzustellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11348] = { id = 11348, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rune des Befehls", description = "Könnt Ihr sie spüren, die Kraft, die von den Runen ausgeht, die ich in diese Tafel gemeißelt habe? Es sind dieselben Runen wie sie die Eisenzwerge verwenden, nur kleiner. Mit ihrer Hilfe werden wir ihre Operation zum Stoppen bringen.\n\nNehmt die Tafel, geht zum Plateau der Riesen und bezaubert mit ihrer Hilfe diejenigen der Steinriesen, die von den Zwergen noch nicht verändert wurden.\n\nDer Riese sollte Euch gehorchen - jedoch habe ich die Runen so gefertigt, dass sie den Bezauberten nach einer gewissen Zeit wieder in seinen ursprünglichen Zustand zurückversetzen. Der Riese mag sich als wertvoller Verbündeter gegen Binder Murdis, den Anführer der Eisenzwerge auf dem Plateau der Riesen, erweisen.", sourceObjective = "Ausgrabungsleiter Belvar in Fort Wildervar möchte, dass Ihr die Rune des Befehls austestet und Binder Murdis besiegt.", completion = "Binder Murdis zu besiegen, war gute Arbeit, aber die Eisenzwerge werden nicht so leicht aufgeben.\n\nUnser Wissen darüber, wie sie Runen handhaben, hat sich stark vergrößert. Womöglich werden wir bei der nächsten Begegnung mit den Zwergen daraus einen Vorteil ziehen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[11349] = { id = 11349, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Runen meistern", description = "Ich habe eine Reihe von Hacken, Hämmern und Meißeln bei mir, die jedoch nicht dazu geeignet sind, die Runen in den Stein zu hauen. Die Werkzeuge der Eisenzwerge werden während des Schmiedeprozesses mit Magie erfüllt.\n\nMeißelt man mit ihnen die Runen in den Stein, wird aus den Symbolen etwas, das über bloße Wörter hinausgeht. Diese Runen besitzen die Macht des Bindens, Zwingens und Umkehrens.\n\nIch meine zu wissen, wie es funktioniert, doch ohne diese Werkzeuge, bin ich mir nicht sicher, ob es klappen wird. Sucht in der Nähe der Eisenzwergzelte auf dem Plateau der Riesen nach Sets, die so aussehen wie meins hier, und bringt sie mir.", sourceObjective = "Bringt Ausgrabungsleiter Belvar in Fort Wildervar ein Set mit Eisenrunenwerkzeugen.", progress = "Seid Ihr mit den Werkzeugen zurückgekehrt?", completion = "<Belvar nimmt die Werkzeuge vorsichtig in die Hand.>\n\nIch werde sie einmal ausprobieren. Wenn wir die Motive der Eisenzwerge ergründen und sie besiegen wollen, dann muss ich mir über die Wirkung der Runen im Klaren sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[11350] = { id = 11350, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Buch der Runen", description = "Ich wurde von Häuptling Aschtotem zum Plateau der Riesen geschickt, einem breiten, felsigen Plateau im Südosten, auf der anderen Seite der Gefrorenen Lichtung.\n\nDie Gegend wurde von den Eisenzwergen erobert, die allem Anschein nach die Riesen umwandeln, die aus dem Boden brechen.\n\nDie Eisenrunensteinrufer und -binder tragen große Folianten bei sich, in denen sich die Runen, die sie in die Haut der Riesen ritzen, befinden müssten.\n\nErbeutet die einzelnen Teile dieses Buches, fügt sie zusammen und bringt mir das Buch. Es ist unsere einzige Möglichkeit, wie wir hinter ihre Pläne kommen können.", sourceObjective = "Fernläufer Pembe im Lager der Winterhufe möchte, dass Ihr ihm das Buch der Runen bringt.", progress = "Habt Ihr das Buch bei Euch?", completion = "<Der Fernläufer blättert durch das Buch der Runen.>\n\nIch bin zwar kein Geschichtskundiger, jedoch mit der Sprache der Eisenzwerge vertraut. Ich denke, dass die Runen, die sie in die Haut der Riesen ritzen, ihrer Sprache entstammen - nur gibt es da ein paar Unterschiede.", sourceObjectiveStatus = "unverified-source-field" }
quests[11351] = { id = 11351, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Runen meistern", description = "Ich denke, dass ich herausgefunden habe, was die Eisenzwerge dort machen: Ihre Werkzeuge werden während des Schmiedeprozesses mit Magie erfüllt.\n\nMeißelt man mit ihnen die Runen in den Stein, wird aus den Symbolen etwas, das mehr ist als nur bloße Wörter. Diese Runen besitzen die Macht des Bindens, Zwingens und Umkehrens.\n\nWenn ich ein Set mit solchen Werkzeugen hätte, könnte ich die Runen dieses Buchs nachmachen. Ich konnte zwar einen dieser Kästen in den Zelten auf dem Plateau der Riesen finden, doch er war leer. Haltet nach ähnlichen Kästen Ausschau, sucht nach einem Set dieser Werkzeuge und bringt es mir.", sourceObjective = "Bringt Fernläufer Pembe im Lager der Winterhufe ein Set mit Eisenrunenwerkzeugen.", progress = "Seid Ihr mit den Werkzeugen zurückgekehrt?", completion = "<Pembe sieht sich die Werkzeuge genauer an.>\n\nSie sind zerbrechlicher als ich dachte. Gebt mir einen Augenblick, damit ich sie ausprobieren kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[11352] = { id = 11352, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rune des Befehls", description = "Könnt Ihr sie spüren, die Kraft, die von den Runen ausgeht, die ich in diese Tafel gemeißelt habe? Es sind dieselben Runen wie sie die Eisenzwerge verwenden, nur kleiner. Mit ihrer Hilfe werden wir ihre Operation zum Stoppen bringen.\n\nNehmt die Tafel, geht zum Plateau der Riesen und bezaubert mit ihrer Hilfe diejenigen der Steinriesen, die von den Zwergen noch nicht verändert wurden.\n\nDer Riese sollte Euch gehorchen - jedoch habe ich die Runen so gefertigt, dass sie den Bezauberten nach einer gewissen Zeit wieder in seinen ursprünglichen Zustand zurückversetzen. Der Riese mag sich als wertvoller Verbündeter gegen Binder Murdis, den Anführer der Eisenzwerge auf dem Plateau der Riesen, erweisen.", sourceObjective = "Fernläufer Pembe im Lager der Winterhufe möchte, dass Ihr die Rune des Befehls ausprobiert und Binder Murdis besiegt.", progress = "Habt Ihr versucht, die Rune einzusetzen?", completion = "Binder Murdis zu besiegen, war gute Arbeit, aber die Eisenzwerge werden nicht so leicht aufgeben.\n\nMein Volk wird den Eisenzwergen auf seinem Zug gen Norden sicherlich noch einmal begegnen. Doch das nächste Mal werden wir bereit sein und ihre Pläne durchkreuzen, bevor sie richtig loslegen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[11354] = { id = 11354, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Nazans Reitgerte", description = "Der heutige Käufer interessiert sich für ein Stück, das sich momentan noch im Besitz des Reittiers von Illidans Herold befindet. Ich spreche natürlich von Vazruden dem Herold und seinem Drachenreittier Nazan.\n\nWenn Euch der Finderlohn angemessen erscheint, solltet Ihr Euch zum Bollwerk der Höllenfeuerzitadelle aufmachen und mir die Reitgerte des Drachen beschaffen.\n\nMeine Quellen versicherten mir, dass sich die Reitgerte im Besitz des Drachen höchstpersönlich befindet. Anscheinend verbot dieser seinem Herren die Benutzung der Gerte.", sourceObjective = "Windhändler Zhareem hat Euch darum gebeten, ihm Nazans Reitgerte zu beschaffen. Bringt sie zu ihm ins Untere Viertel in Shattrath, um Eure Belohnung zu erhalten.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "Die Reitgerte, bitte!", completion = "Wieder ein zufriedener Kunde. Der Gegenstand scheint in gutem Zustand zu sein, hervorragend. Ihr werdet entsprechend entlohnt werden.\n\nKommt morgen wieder und ich werde einen weiteren Auftrag für Euch bereithalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[11355] = { id = 11355, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marsch der Riesen", description = "Im Osten, auf dem Plateau der Riesen, haben mit Runen übersäte Riesen damit begonnen, gen Norden in Richtung Frostklingengipfel zu ziehen. Was genau ihr endgültiges Reiseziel ist, weiß ich nicht.\n\nDie leuchtenden Runen, die in das steinerne Fleisch der Riesen gemeißelt wurden, weisen ihnen auf ihrer Reise die Richtung.\n\nDeaktiviert mithilfe dieser Hacke die Runen auf den Leichen der Riesen und kehrt mit Euren Funden zu mir zurück.", sourceObjective = "Forscher Aderan in Fort Wildervar möchte, dass Ihr mithilfe der runensuchenden Hacke die Leichen von 4 runenbeschriebenen Steinriesen bearbeitet.", completion = "<Forscher Aderan lauscht Euren Worten, als Ihr von Euren Funden berichtet.>\n\nDie Runen für \"Norden\" und \"Westen\" tauchen mehrmals auf? Hier wird also nachdrücklich befohlen, in diese Richtung zu ziehen, doch die Runen sind mehr als nur Antrieb. Irgendetwas zieht sie an, nur was?", sourceObjectiveStatus = "unverified-source-field" }
quests[11356] = { id = 11356, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kostümierte Waisenmatrone", description = "Während der Schlotternächte werden von den Waisenhäusern der Menschen Ausflüge für die Waisenkinder organisiert. Die Kinder sollen Allianzdörfer auf dem Land besuchen. Die armen Kleinen würden so gerne einen wahren Helden wie Euch sehen!\n\nWarum stattet Ihr ihnen keinen Besuch ab? Ihr findet die Waisenkinder in Goldhain im Wald von Elwynn, in Kharanos in Dun Morogh und bei der Azurwacht auf der Azurmythosinsel. Sprecht mit der Aufsicht der Kinder, einer kostümierten Waisenmatrone, sie wird Euch den Kindern vorstellen.", sourceObjective = "Sprecht mit einer kostümierten Waisenmatrone in Goldhain, Kharanos oder bei der Azurwacht.", completion = "Ihr seid hier, um die Kinder zu besuchen! Wie wundervoll! In ihrem kurzen Leben ist ihnen so viel Kummer widerfahren. Es ist gut, dass sie einen wahren Helden wie Euch sehen. Es hellt ihr Gemüt wirklich auf!", sourceObjectiveStatus = "unverified-source-field" }
quests[11357] = { id = 11357, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maskierte Waisenmatrone", description = "Während der Schlotternächte werden mit den Orcwaisenkindern Ausflüge zu zahlreichen Dörfern der Horde unternommen. Die Waisenmatronen dachten, dass es vielleicht gut für die Kinder wäre, wenn sie wahren Helden einmal bei der Arbeit zusehen könnten.\n\nWarum besucht Ihr sie nicht? <Ein mutiger/Eine mutige:c> {class} wie Ihr könnte ihre Gemüter mit Geschichten Eurer Heldentaten aufhellen! Geht entweder nach Klingenhügel in Durotar, Brill in Tirisfal oder zum Falkenplatz im Immersangwald. Sprecht mit der maskierten Waisenmatrone und sie wird Euch den Kindern vorstellen.", sourceObjective = "Sprecht mit einer maskierten Waisenmatrone in Klingenhügel, Brill oder beim Falkenplatz.", completion = "Die Kinder lieben es, wenn sie Helden bei ihrer Arbeit zusehen können. Ich hoffe, dass ein jedes dieser Kinder einmal ein starkes Mitglied der Horde sein und letztendlich in einer glorreichen Schlacht sterben wird!\n\nAh, der Gedanke an ein solch ehrbares Schicksal rührt mich zu Tränen...", sourceObjectiveStatus = "unverified-source-field" }
quests[11358] = { id = 11358, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Leitstein", description = "Wenn wir ausfindig machen könnten, was die Riesen nach Nordwesten zieht, könnten wir sie vielleicht aufhalten, bevor sie ihr Ziel erreichen.\n\nIch konnte zwar viele der Runenprobestücke, die Ihr mir gebracht habt, entziffern, doch diejenigen, die ich nicht kenne, beunruhigen mich am meisten. Als ich das Plateau der Riesen besuchte, bemerkte ich eine große, zerbrochene Tafel, die an der Stelle aus dem Boden herausragte, wo der nordöstliche Teil der Gegend auf den Schnee am Fuße des Frostklingengipfels trifft. Nehmt dieses Probestück, vergleicht die Runen mit der Tafel und seht nach, was Ihr herausfinden könnt.", sourceObjective = "Forscher Aderan in Fort Wildervar möchte, dass Ihr das Probestück einer Rune mit der zerbrochenen Schrifttafel vergleicht.", completion = "<Aderan hört Euch aufmerksam zu, als Ihr Eure Entdeckung schildert.>\n\nNatürlich! Dieser Megalith muss der Schlüssel zu den Plänen der Eisenzwerge sein. Wir müssen ihn zerstören, bevor sie ihren Plan in die Tat umsetzen können!", sourceObjectiveStatus = "unverified-source-field" }
quests[11359] = { id = 11359, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Megalith zertrümmern", description = "Mit Megalith schuf Binder Murdis den Mächtigsten unter den mit Runen versehenen Riesen und somit den Leiter ihrer Mission. Besiegte man Megalith, wären sie verloren und orientierungslos. Nachdem die Expeditionskorps eingetroffen sind, werden unsere Soldaten die restlichen Riesen isolieren und besiegen können und auf diese Weise ihre eisenzwergischen Meister aus ihren Lagern vertreiben.\n\nSucht auf den Ausläufern des Frostklingengipfels nördlich des Plateaus der Riesen nach Megalith und bezwingt ihn!", sourceObjective = "Bezwingt Megalith und kehrt anschließend zu Forscher Aderan in Fort Wildervar zurück.", completion = "Megalith zu Fall zu bringen, war gute Arbeit, doch ich frage mich, was wohl seine letzten Worte zu bedeuten haben.\n\nSeid Ihr Euch sicher, dass er die Steinschmiede erwähnte?\n\nEin Ort, der diesen Namen trägt, ist mir zwar unbekannt, doch es klingt wie ein Wort titanischen Ursprungs. Was haben die Eisenzwerge mit solch einem Ding vor? Wir sollten die Sache im Auge behalten, {name}, denn wir müssen das Ding finden, bevor die Eisenzwerge ihren Plan in die Tat umsetzen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[11360] = { id = 11360, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Übung bei der Brandwache", description = "Solange der kopflose Reiter noch Angst und Schrecken verbreitet, sind alle Helden von Goldhain bereit für einen Einsatz der Brandwache. Wollt Ihr auch helfen?\n\nEinige Wachen haben nördlich von hier ein kleines Lager für Übungen der Brandwache errichtet. Geht dorthin und löscht Feuer mithilfe von Wassereimern. Ihr könnt Eure Eimer hier beim Wasserfass füllen oder das in der Nähe der Feuer stehende Fass verwenden.\n\nBis dann, {name}. Besucht uns bitte wieder, wenn Ihr genug geübt habt!", sourceObjective = "Löscht 5 Feuer mit Wassereimern und sprecht anschließend mit der kostümierten Waisenmatrone.", progress = "Hallo, {name}. Habt Ihr Euch im Feuerlöschen geübt? Vergesst das Übungslager im Norden nicht!", completion = "Ihr seid ja pitschnass und mit Ruß verschmiert! Beim Feuerlöschen gewesen, nicht wahr?\n\nGut gemacht! Als ehrenamtliches Mitglied der Brandwache bitte ich Euch, wieder hierher zurückzukommen, falls unser Dorf Euch brauchen sollte!", sourceObjectiveStatus = "unverified-source-field" }
quests[11361] = { id = 11361, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuerübung", description = "Die Grunzer haben ein Übungslager zum Feuerlöschen außerhalb des Dorfes aufgebaut. In letzter Zeit fangen die Gebäude in Klingenhügel rasch Feuer - Ihr solltet helfen und Euch im Feuerlöschen üben!\n\nVerlasst Klingenhügel in Richtung Westen und biegt rechts ab, wenn Ihr an der Stadtmauer vorbei seid. Haltet nach dem Übungslager Ausschau. Schnappt Euch Wassereimer und löscht damit die Übungsfeuer.", sourceObjective = "Löscht 5 Feuer mit Wassereimern und sprecht anschließend mit der maskierten Waisenmatrone in Klingenhügel.", completion = "Gut gemacht, {name}! Kinder, seht Euch diesen Helden gut an. Werdet alle so stark und mutig wie er, dann werdet auch Ihr eines Tages für die Horde kämpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11362] = { id = 11362, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Keli'dans gefiederter Stab", description = "Die Geschmäcker sind sehr verschieden, nehmt zum Beispiel meinen neuesten Käufer.\n\nIn der Höllenfeuerzitadelle residiert ein Blutorc namens Keli'dan der Zerstörer. Dieser Orc ist im Besitz eines recht gewöhnlichen Stabes; nichts, was einen zweiten Blick wert wäre. Und doch ist es genau dieser Stab, den mein Kunde wünscht.\n\nWer bin ich schon, dass ich diesen Auftrag ablehnen könnte?\n\nAlso, wenn Ihr von mir entlohnt werden wollt, solltet Ihr Euch in den Blutkessel begeben, dort werdet Ihr Keli'dan und seinen Stab finden.", sourceObjective = "Windhändler Zhareem hat Euch darum gebeten, ihm Keli'dans gefiederten Stab zu beschaffen. Bringt ihn zu ihm ins Untere Viertel in Shattrath, um Eure Belohnung zu erhalten.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "Ihr seid wieder hier... also müsst Ihr den Stab bei Euch tragen!", completion = "Möglicherweise werde ich noch einige frische Federn an den Stab anbringen lassen, bevor ich ihn seinem Käufer übergebe. Mit den ganzen Arakkoas in dieser Gegend sollte das jedoch kein großes Problem darstellen. Ein eher unwichtiges Detail und nichts, das mich davon abhalten könnte, Euch angemessen zu entlohnen.\n\nKommt morgen wieder und ich werde einen weiteren Auftrag für Euch bereithalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[11363] = { id = 11363, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Messerfausts Siegel", description = "Am heutigen Tage ist ein sehr reicher Sammler an mich herangetreten, dem es nach etwas besonders Einzigartigem verlangt.\n\nKriegshäuptling Kargath Messerfaust trägt sein persönliches Siegel, mit dem er alle offiziellen Dokumente abzeichnet, stehts bei sich. Ich möchte, dass Ihr es für mich beschafft.\n\nIhr findet ihn tief in den Zerschmetterten Hallen. Es besteht kein Zweifel, dass Ihr Euch zunächst durch eine recht beeindruckende Armee kämpfen müsst, bevor Ihr das Siegel in den Händen haltet. Aber ich glaube fest an Euren Erfolg!", sourceObjective = "Windhändler Zhareem hat Euch darum gebeten, ihm Messerfausts Siegel zu beschaffen. Bringt es zu ihm ins Untere Viertel in Shattrath, um Eure Belohnung zu erhalten.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "Ich hörte Gerüchte, nach denen der Kriegshäuptling seine Hände durch Waffen hat ersetzen lassen. Ist das wahr?", completion = "Wahrlich eine beeindruckende Akquisition; eine, die es wert ist, dass die Barden noch in Jahrzehnten darüber berichten. Hier, Ihr habt Euch diese Belohnung redlich verdient.\n\nKommt morgen wieder und ich werde einen weiteren Auftrag für Euch bereithalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[11364] = { id = 11364, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Zenturionen der Zerschmetterten Hand", description = "Zweifelt Ihr an Eurem Meister? Gut, dann verstehen wir uns, ja?\n\nEs ist das Blut der Zenturionen der Zerschmetterten Hand, nach dem es mich verlangt. Sucht sie in den Zerschmetterten Hallen der Höllenfeuerzitadelle.\n\nWenn Euch die Belohnung lieb ist, werdet Ihr erst zurückkehren, nachdem Ihr sie alle getötet habt.", sourceObjective = "Netherpirscher Mah'duun hat Euch damit beauftragt, 4 Zenturionen der Zerschmetterten Hand zu töten. Kehrt erst zu ihm in das Untere Viertel in Shattrath zurück, wenn sie alle dem Tod überantwortet wurden.", completion = "Ihr habt Euch Eure Belohnung in der Tat verdient.\n\nKehrt morgen zu mir zurück, wenn die Winde Mah'duun ihren Willen offenbart haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[11365] = { id = 11365, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marsch der Riesen", description = "Im Osten, auf dem Plateau der Riesen, haben mit Runen übersäte Riesen damit begonnen, gen Norden in Richtung Frostklingengipfel zu ziehen. Ich weiß nicht, was sie vorhaben, noch wohin sie wollen.\n\nDie leuchtenden Runen, die in das steinerne Fleisch der Riesen gemeißelt wurden, weisen ihnen auf ihrer Reise die Richtung. Streckt ein paar dieser Riesen nieder - dadurch werden die Runen aufhören zu leuchten, so dass man Proben aus dem Körper der Riesen brechen kann.\n\nNehmt diese Hacke mit Euch und bearbeitet mit ihrer Hilfe die runenbeschriebenen Steinriesen. Dadurch werden die Runen deaktiviert. Kehrt mit Euren Funden zu mir zurück, sobald Ihr Euch mit genug Riesen gemessen habt.", sourceObjective = "Weiser Edan im Lager der Winterhufe möchte, dass Ihr mithilfe der Hacke zum Runensuchen die Leichen von 4 runenbeschriebenen Steinriesen bearbeitet.", completion = "<Der Weise lauscht Euren Worten, als Ihr von Euren Funden berichtet.>\n\nDie Runen für \"Norden\" und \"Westen\" tauchen mehrmals auf? Ich bin zwar kein Experte, was diese Runen angeht, aber dass sie sich wiederholen deutet darauf hin, dass es ein ausdrücklicher Befehl ist.\n\nDiese Gravuren sind jedoch mehr als nur Wegweiser. Es scheint, als steuerten sie die Riesen auf etwas zu, nur was?", sourceObjectiveStatus = "unverified-source-field" }
quests[11366] = { id = 11366, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Leitstein", description = "Wir müssen herausfinden, was die Riesen nach Nordwesten zieht, damit wir sie aufhalten können, bevor sie ihr Ziel erreichen.\n\nDie Runenproben gaben uns zwar einige Anhaltspunkte, doch es sind die unbekannten Runen, über die ich mir Sorgen mache.\n\nAls ich das Plateau der Riesen besuchte, bemerkte ich eine große, zerbrochene Tafel, die an der Stelle aus dem Boden herausragte, wo der nordöstliche Teil der Gegend auf den Schnee am Fuße des Frostklingengipfels trifft. Nehmt diese Probe, vergleicht die Runen mit der Tafel und seht nach, was Ihr herausfinden könnt.", sourceObjective = "Weiser Edan im Lager der Winterhufe möchte, dass Ihr die Runenprobe mit der zerbrochenen Schrifttafel vergleicht.", completion = "<Edan hört Euch aufmerksam zu, als Ihr Eure Entdeckung schildert.>\n\nMegalith? Es ist Wort für Wort das, was auf der Schrifttafel steht! Dieser Megalith muss das Herzstück der rätselhaften Pläne der Eisenhaften darstellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11367] = { id = 11367, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Megalith zertrümmern", description = "Mit Megalith schuf Binder Murdis eine Art Schlussstein in der Hierarchie der mit Runen versehenen Riesen und somit den Leiter ihrer Mission. Besiegte man Megalith, wären sie verloren und orientierungslos. Ich werde Häuptling Aschtotem ersuchen, auf unserem Marsch gen Norden ein paar unserer Männer zur Beseitigung des letzten Rests dieser mit Runen versehenen Riesen einzusetzen.\n\nSucht auf den Ausläufern des Frostklingengipfels nördlich des Plateaus der Riesen nach Megalith und bezwingt ihn!", sourceObjective = "Bezwingt Megalith und kehrt anschließend zu Weiser Edan im Lager der Winterhufe zurück.", completion = "Megalith zu Fall zu bringen, war gute Arbeit, doch ich frage mich, was wohl seine letzten Worte zu bedeuten haben.\n\nSeid Ihr Euch sicher, dass er die Steinschmiede erwähnte?\n\nEin Ort mit diesem Namen ist meinem Volk unbekannt, doch es klingt, als wäre es von den \"Titanen\" geschaffen, von denen die Außenstehenden sprechen. Die Eisenzwerge waren schon immer ein gerissener und gefährlicher Feind, {name}. Wir müssen diese Riesen im Auge behalten und Steinschmiede finden, bevor sie ihre Pläne verwirklichen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[11368] = { id = 11368, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Das Herz von Quagmirran", description = "Ich habe einen recht ungewöhnlichen Auftrag für Euch. Eine bestimmte wohlhabende Persönlichkeit, mit der ich in außerweltlichem Kontakt stehe, interessiert sich für ein besonders makaberes Stück.\n\nGenau genommen verlangt sie das Herz von Quagmirran.\n\nWie ich hörte, verfügt dieses Biest gleich über drei Herzen, doch ich denke, eines dürfte für unsere Zwecke ausreichend sein. Soweit ich informiert bin, ruht Quagmirran in einem tiefen See in den Sklavenunterkünften des Echsenkessels.", sourceObjective = "Windhändler Zhareem hat Euch darum gebeten, ihm das Herz von Quagmirran zu beschaffen. Bringt es zu ihm ins Untere Viertel in Shattrath, um Eure Belohnung zu erhalten.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "Ich vertraue darauf, dass Ihr eine Möglichkeit findet, das Herz sicher hierher zu bringen!", completion = "Wenn ich es mir recht überlege, dann ist es eigentlich eine Schande, dass ich Euch nicht darum gebeten habe, mir alle Herzen zu bringen. Vielleicht beim nächsten Mal. Wie auch immer, Ihr habt Euch Euren Anteil redlich verdient.\n\nKommt morgen wieder und ich werde einen weiteren Auftrag für Euch bereithalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[11369] = { id = 11369, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Ei der Schattenmutter", description = "Unter den Marschenläufern in den Zangarmarschen gibt es stets nur eine oberste Mutter. Man nennt sie die Schattenmutter und wenn sie stirbt, schlüpft ihre Nachfolgerin aus einem der hinterbliebenen Eier.\n\nEiner meiner Käufer interessiert sich für eben diese Eier. Beiläufig erwähnte er etwas davon, dass das geschlüpfte Wesen eine hervorragende Ergänzung für seinen Zoo wäre.\n\nWenn Euch meine Bezahlung angemessen erscheint, solltet Ihr in den Tiefensumpf aufbrechen und die Schattenmutter töten, um an das Ei zu gelangen.", sourceObjective = "Windhändler Zhareem hat Euch darum gebeten, ihm ein Ei der Schattenmutter zu beschaffen. Bringt es zu ihm ins Untere Viertel in Shattrath, um Eure Belohnung zu erhalten.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "Sprechen wir uns wieder, weil Ihr das Ei habt? Fantastisch, lasst es mich sehen!", completion = "Ist es nicht fantastisch, wie sehr man das Leben in diesem Ei spüren kann? Ich werde mich beeilen und es rechtzeitig zu seinem Käufer bringen müssen. Wir wollen doch nicht, dass es hier bei uns schlüpft, nicht wahr?\n\nEure Bezahlung steht bereit.\n\nKommt morgen wieder und ich werde einen weiteren Auftrag für Euch bereithalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[11370] = { id = 11370, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Die Aufzeichnungen des Kriegsherren", description = "Vielen ist bekannt, dass Kriegsherr Kalithresh ein hervorragender Stratege ist, doch nur wenige wissen, dass er sein gesamtes Wissen auch niedergeschrieben hat.\n\nEiner meiner Kunden hat davon erfahren und nun wünscht er diese Aufzeichnungen in seinen Besitz zu bringen.\n\nDaher möchte ich Euch bitten, in die Dampfkammer des Echsenkessels einzudringen, um das Buch für mich zu beschaffen.", sourceObjective = "Windhändler Zhareem hat Euch darum gebeten, ihm die Aufzeichnungen des Kriegsherren zu beschaffen. Bringt sie zu ihm ins Untere Viertel in Shattrath, um Eure Belohnung zu erhalten.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "Mein Kunde wird langsam ungeduldig. Ich nehme an, er möchte das strategische Wissen des Kriegsherren zur Lösung eines seiner laufenden Konflikte einsetzen.", completion = "Tatsächlich glaube ich, dass mein Kunde nicht genügend Zeit aufbringen kann, um das Buch in seiner Gesamtheit zu studieren. Nun gut, überlassen wir das ihm. Hier ist Eure Bezahlung.\n\nKommt morgen wieder und ich werde einen weiteren Auftrag für Euch bereithalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[11371] = { id = 11371, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Myrmidonen des Echsenkessels", description = "Mah'duun hat gehört und verstanden. Jetzt sollt Ihr sein Werkzeug sein.\n\nMir wurde offenbart, dass die Myrmidonen des Echsenkessels vernichtet werden müssen. Sucht in den klammen Räumen der Dampfkammer unter dem Echsenkessel nach ihnen.\n\nIch erwarte nichts Geringeres als ihre vollständige Vernichtung.", sourceObjective = "Netherpirscher Mah'duun hat Euch damit beauftragt, 14 Myrmidonen des Echsenkessels zu töten. Kehrt erst zu ihm in das Untere Viertel in Shattrath zurück, wenn sie alle dem Tod überantwortet wurden.", completion = "Ich nehme an, es war ein Kampf ganz nach Eurem Geschmack? Die Belohnung wird Euch ebenfalls zusagen.\n\nKehrt morgen zu mir zurück, wenn die Winde Mah'duun ihren Willen offenbart haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[11372] = { id = 11372, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Die Kopfschmuckfedern von Ikiss", description = "Kürzlich ist eine Taurenfrau an mich herangetreten, deren Ehemann schon bald in den Stand eines Häuptlings erhoben wird. Sie würde ihn gerne mit einer besonderen Verzierung für seinen Federkopfschmuck überraschen.\n\nGenau genommen hätte sie gerne die Kopfschmuckfedern des niederträchtigen Klauenkönigs Ikiss.\n\nWenn Euch meine ausgesetzte Belohnung angemessen erscheint, solltet Ihr zu den Sethekkhallen von Auchindoun aufbrechen und Ikiss einen Besuch abstatten.", sourceObjective = "Windhändler Zhareem hat Euch darum gebeten, ihm die Kopfschmuckfedern von Ikiss zu beschaffen. Bringt sie zu ihm ins Untere Viertel in Shattrath, um Eure Belohnung zu erhalten.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "Die Häuptlingszeremonie findet bald statt, beeilt Euch.", completion = "Diese Federn werden dem Kopfschmuck des Häuptlings den letzten Schliff geben. Ihr habt Euch Eure Bezahlung redlich verdient, {class}.\n\nKommt morgen wieder und ich werde einen weiteren Auftrag für Euch bereithalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[11373] = { id = 11373, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Shaffars wundersames Amulett", description = "Heute möchte ich Euch mit einer persönlichen Angelegenheit beauftragen. Aber keine Sorge, die Belohnung macht die Gefahr wieder mehr als wett.\n\nMeine Familie hat noch eine Rechnung mit Nexusprinz Shaffar und seinen Anhängern offen. Sollte mir sein Amulett in die Hände fallen, wäre dies ein sicheres Zeichen dafür, dass sich jemand seiner angenommen hat.\n\nWenn Euch meine Belohnung angemessen erscheint, solltet Ihr zu seinen Gemächern in der Managruft von Auchindoun aufbrechen.", sourceObjective = "Windhändler Zhareem hat Euch darum gebeten, ihm Shaffars wundersames Amulett zu beschaffen. Bringt es zu ihm ins Untere Viertel in Shattrath, um Eure Belohnung zu erhalten.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "Nur wenige wissen, dass Shaffar seine magische Macht ausschließlich aus diesem Amulett bezieht. Ohne es ist er machtlos.\n\nWenn es sich also in Eurem Besitz befindet, lässt dies nur den Schluss zu, dass er tot ist.", completion = "<Eine Woge der Zufriedenheit scheint von dem Windhändler auszugehen.>\n\nGut, es freut mich, von seinem Ende zu hören. Wer weiß, vielleicht gelingt es mir sogar, die Geheimnisse des Amuletts für mich zu nutzen und wenn nicht, werde ich es zu einem angemessenen Preis verkaufen.\n\nIch schätze diese Belohnung ist mehr als ausreichend.\n\nKommt morgen wieder und ich werde einen weiteren Auftrag für Euch bereithalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[11374] = { id = 11374, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Der Seelenedelstein des Exarchen", description = "In dem Bestreben, die nekromantischen Künste besser zu verstehen, werden in der Auchenaikrypta von Auchindoun eine Unzahl von abscheulichen Experimenten durchgeführt. Zahlreich sind die Geister derer, die in den finsteren Hallen gefoltert und ermordet wurden.\n\nEiner meiner Kunden wünscht die Befreiung eines dieser gequälten Geister. Nach meinen Informationen ist dieser Geist in einem Seelenedelstein gefangen, der sich im Besitz von Exarch Maladaar befindet.\n\nSucht ihn mit gebotener Schnelligkeit in der Krypta auf und bringt mir seinen Edelstein.", sourceObjective = "Windhändler Zhareem hat Euch darum gebeten, ihm den Seelenedelstein des Exarchen zu beschaffen. Bringt diesen zu ihm ins Untere Viertel in Shattrath, um Eure Belohnung zu erhalten.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "Könnt Ihr Euch vorstellen, für alle Ewigkeit in einem Edelstein gefangen zu sein?", completion = "Ihr seid wahrlich ein Held, {name}. Ich bin mir sicher, dass mein Kunde einen Weg finden wird, um den Geist seiner Geliebten aus dem Edelstein zu befreien. Eure Belohnung für diese hervorragende Arbeit wartet bereits auf Euch.\n\nKommt morgen wieder und ich werde einen weiteren Auftrag für Euch bereithalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[11375] = { id = 11375, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Murmurs Flüstern", description = "Wenn ich Euch eingeweiht habe, werdet Ihr diesen Auftrag mit Sicherheit nicht mehr annehmen wollen.\n\nEiner meiner besonders exzentrischen Kunden befasst sich mit der Erforschung toter Existenzen. Wenn man diversen Gerüchten Glauben schenkt, zerstörte das als Murmur bekannte Wesen die letzte Welt von der es beschworen wurde vollständig. Der Professor würde gerne das so genannte 'Flüstern' dieser Kreatur analysieren, um zu verstehen, wie Murmur so eine Zerstörung verursachen konnte.\n\nWürdet Ihr für mich in das Schattenlabyrinth in Auchindoun eindringen und das 'Flüstern' für mich beschaffen?", sourceObjective = "Windhändler Zhareem hat Euch darum gebeten, ihm Murmurs Flüstern zu beschaffen. Bringt es zu ihm ins Untere Viertel in Shattrath, um Eure Belohnung zu erhalten.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "Ich bin mir nicht einmal sicher, welche Form ein Flüstern in der körperlichen Welt annimmt, aber der Professor versicherte mir, dass Ihr es erkennen werdet, wenn Ihr es seht.\n\nVielleicht ist es so etwas wie der Kehlkopf des Wesens?", completion = "Ich fürchtete schon, Ihr würdet nicht mehr zurückkehren. Ich hoffe doch, der Kampf gegen Murmur hat Euch nicht taub werden lassen?\n\nHier ist Eure Belohnung. Der Professor wird zweifellos sehr zufrieden sein. Ich fürchte mich nur davor, was er mit diesem Gegenstand anfangen wird.\n\nKommt morgen wieder und ich werde einen weiteren Auftrag für Euch bereithalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[11376] = { id = 11376, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Bösartige Ausbilderinnen", description = "Mah'duun hat vernommen, dass die Grausamkeit der sechsarmigen Dämonen im Schattenlabyrinth beispiellos ist.\n\nBegebt Euch nach Auchindoun, sucht und tötet sie alle.\n\nBemüht Euch nicht, mich ein zweites Mal aufzusuchen, wenn Ihr scheitert.", sourceObjective = "Netherpirscher Mah'duun hat Euch damit beauftragt, 3 bösartige Ausbilderinnen zu töten. Kehrt erst zu ihm in das Untere Viertel in Shattrath zurück, wenn sie alle dem Tod überantwortet wurden.", progress = "Habt Ihr die Ausbilderinnen alle getötet? Nein?\n\nHabe ich Euch nicht aufgetragen, erst zurückzukehren, wenn alle tot sind?", completion = "Ich bin sehr zufrieden. Auch der, der über den Nether zu mir spricht, ist hoch erfreut. Mah'duun hat Eure Belohnung bereits vorbereitet.\n\nKehrt morgen zu mir zurück, wenn die Winde Mah'duun ihren Willen offenbart haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[11377] = { id = 11377, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rache ist süß", description = "Heute Abend koche ich für eine ganz besondere Festgemeinschaft. Einer der Gäste flog vor Kurzem in Skettis herum, als er plötzlich von einem riesigen Kaliri erfasst wurde und zu Boden fiel. Er brach sich dabei sein Bein.\n\nFür seine 'Gute Besserungs'-Feier soll nun etwas ganz Besonderes auf dem Speiseplan stehen: Kalirieintopf.\n\nIch werde Euch meinen Topf zur Verfügung stellen und es wird Eure Aufgabe sein, den Eintopf zu kochen. Das Rezept ist an sich recht einfach, Ihr benötigt nur einen riesigen Kaliriflügel und einige Doppelwarper.", sourceObjective = "Der Rokk im Unteren Viertel von Shattrath hat Euch darum gebeten, mithilfe seines Kochtopfs einen Kalirieintopf zu kochen. Kehrt anschließend zu ihm zurück.", progress = "Rieche ich da etwas zu essen?", completion = "Oh, das riecht aber lecker! Ich hoffe, Ihr habt dem Vogel einen guten Kampf geliefert.\n\nBitte, nehmt Euch ruhig etwas von meinen speziellen Vorräten. Jemand mit Eurem Talent sollte damit etwas anfangen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[11378] = { id = 11378, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Der Kopf des Epochenjägers", description = "Die Geschmäcker meiner Kunden variieren von banal zu sehr exotisch. Und manchmal wollen sie mit den exotischen Gegenständen, die ich ihnen beschaffe, sehr banale Dinge anstellen.\n\nMein momentaner Kunde gehört zu dieser Sorte. Er, dessen Name hier unerwähnt bleiben soll, wünscht sich nichts sehnlicher, als den Kopf des Epochenjägers an seiner Wand aufzuhängen.\n\n{class}, Ihr müsst einen Weg finden, um zurück durch die Zeit ins Alte Hügelland zu reisen und besagten Kopf für unseren Trophäen sammelnden Kunden beschaffen.", sourceObjective = "Windhändler Zhareem hat Euch darum gebeten, ihm den Kopf des Epochenjägers zu beschaffen. Bringt diesen zu ihm ins Untere Viertel in Shattrath, um Eure Belohnung zu erhalten.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "Der Kopf des Epochenjägers... wie kommt jemand bloß auf die Idee, sich diesen an die Wand hängen zu wollen?\n\nSelbst wenn, dann geht man doch selbst auf die Jagd. Was soll man denn den eigenen Freunden erzählen, wenn sie einem Fragen über den Kampfverlauf stellen?\n\nBleibt höchstens eine Notlüge.", completion = "Wie ich sehe, seid Ihr wieder gesund und munter im Hier und Jetzt angekommen.\n\n<Der Windhändler sieht sich um.>\n\nMir scheint, dass sich nichts verändert hat. Auf der anderen Seite, würde ich es wahrscheinlich gar nicht merken.\n\nEin sauberer Schnitt, mein Kunde wird zufrieden sein. Hier ist Eure Belohnung.\n\nKommt morgen wieder und ich werde einen weiteren Auftrag für Euch bereithalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[11379] = { id = 11379, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Superheißes Ragout", description = "Ich versuche gerade, etwas ganz Besonderes zu kreieren. Aber um ehrlich zu sein, bin ich mittlerweile eher ein Theoretiker geworden. Irgendwie ist mir mein Sinn für Abenteuer abhandengekommen.\n\nIhr aber... Ihr erinnert mich irgendwie an mich selbst in jungen Jahren. Bereit, sich der Welt mit Schwert und Bratpfanne zu stellen.\n\nIch möchte, dass Ihr meinen Lieblingskochtopf nehmt und Euch zum Schergrat aufmacht. Füllt ihn mit ein paar Rippchen und Knusperschlangen - natürlich gekocht, für die Extraportion Würze. Zum Schluss erhitzt Ihr das Ganze über einem abyssischen Leichnam. Dies ist die einzige Wärmequelle, die heiß genug ist, um dieses Gericht perfekt zu garen.", sourceObjective = "Der Rokk im Unteren Viertel von Shattrath hat Euch darum gebeten, mithilfe seines Kochtopfs ein Dämonenragout Surprise, zwei Rippchen der Mok'Nathal und eine Knusperschlange zu kochen. Kehrt anschließend zu ihm zurück.", progress = "Verlief mein kleines Experiment erfolgreich?", completion = "Nun sieh mal einer an...\n\n<Als der Rokk ein wenig von Eurem Gericht probiert, zeichnet sich auf seinem Gesicht eine Mischung aus Entzücken und abnormen Schmerzen ab.>\n\nHeiliger A'dal ist das lecker! Ein Koch mit Eurem Talent braucht stets die richtigen Zutaten! Hier, bedient Euch aus meinen Vorräten und macht mich stolz!", sourceObjectiveStatus = "unverified-source-field" }
quests[11380] = { id = 11380, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Manaziös", description = "War ja klar! Ich denke meine Vorräte sind lückenlos und sofort kommt jemand um die Ecke, der etwas Ausgefallenes haben möchte: Manabeere Surprise.\n\nUnglücklichweise findet man Manabeeren nur in den Biokuppeln des Nethersturms. Aber macht Euch nicht die Mühe, auf der Sturmsäule zu suchen - dort ist alles abgeerntet.\n\nEs bedarf eines wahren Meisters der Kochkunst, um nur die besten Beeren zu pflücken, also enttäuscht mich nicht!", sourceObjective = "Der Rokk im Unteren Viertel von Shattrath möchte, dass Ihr 15 Manabeeren in den Biokuppeln im Nethersturm sammelt.", progress = "Hattet Ihr Erfolg?", completion = "Noch nie sah ich so saftige Beeren! Ich fühle mich schon vom bloßen Hingucken geistig gestärkt.\n\nWarum nehmt Ihr nicht etwas von meinen Fisch- und Fleischvorräten? Anscheinend habe ich eh keine Verwendung mehr dafür. Sicherlich werdet Ihr daraus etwas ganz Besonderes kochen!", sourceObjectiveStatus = "unverified-source-field" }
quests[11381] = { id = 11381, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suppe für die Seele", description = "Irgendetwas liegt in der Luft. Noch nie hatte ich so viele Bestellungen für meine berühmte Suppe - sie weckt die inneren Geister und streichelt die Seele.\n\nIch erkenne einen Koch, wenn ich einen sehe! Würdet Ihr mir im Austausch gegen eine kleine Gewinnbeteiligung ein wenig aushelfen?\n\nHier, nehmt meinen Kochtopf, sammelt etwas Grollhuffleisch und ich verrate Euch ein kleines Geheimnis. Was glaubt Ihr, macht meine Suppe so angenehm für die Seele? Es hat nichts mit Hühnchen zu tun! Es liegt daran, dass ich sie beim Ahnengrund in Nagrand koche, um alles Geisterhafte, das in der Luft schwebt, einzufangen.", sourceObjective = "Der Rokk im Unteren Viertel von Shattrath hat Euch darum gebeten, mithilfe seines Kochtopfs eine spirituelle Suppe zu kochen. Kehrt anschließend zu ihm zurück.", progress = "Was riecht hier so gut?", completion = "Das ist eine feine Ladung spirituelle Suppe. Es fehlt nur noch etwas Pfeffer für den richtigen Geschmack!\n\nHier, wie versprochen, Euer Anteil. Und weil Ihr so gute Arbeit geleistet habt, dürft Ihr Euch noch an meinen Vorräten bedienen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11382] = { id = 11382, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Aeonus' Stundenglas", description = "Einige meiner Kunden sind wirklich verrückt. Es gibt Dinge, denen man nachjagt und andere, über die man nicht einmal nachdenken sollte!\n\nMein heutiger Kunde ist der Inbegriff von Größenwahn! Er verlangt nichts Geringeres als Aeonus' Stundenglas.\n\nJa, Ihr habt richtig gehört, das Stundenglas von Aeonus, seines Zeichens Angehöriger des ewigen Drachenschwarms!\n\nAber wer bin ich schon, dass ich widersprechen könnte? Insbesondere bei der Menge Gold, die er mir geboten hat. Also, seid Ihr bereit, die Höhlen der Zeit aufzusuchen und in den Schwarzen Morast zu reisen, um das Stundenglas zu beschaffen?", sourceObjective = "Windhändler Zhareem hat Euch darum gebeten, ihm Aeonus' Stundenglas zu beschaffen. Bringt es zu ihm ins Untere Viertel in Shattrath, um Eure Belohnung zu erhalten.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "An Eurer Stelle wäre ich mit Zeitreisen sehr vorsichtig. Schließlich wollt Ihr ja nicht versehentlich einen Eurer eigenen Vorfahren töten und so Eure eigene Existenz in der Gegenwart auslöschen!", completion = "Seltsam, dass der Sand in diesem Ding noch immer aufwärts fließt. Ich schlage vor, wir schaffen es lieber schnellstmöglich zu seinem neuen Besitzer.\n\nIch muss Euch für diese gute Arbeit danken, {class}. Ihr habt Euch Eure Belohnung redlich verdient.\n\nKommt morgen wieder und ich werde einen weiteren Auftrag für Euch bereithalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[11383] = { id = 11383, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Fürsten der Zeitenrisse", description = "Mah'duun weiß, was zu tun ist. Mah'duun weiß, dass Ihr Fürsten der Zeitenrisse töten müsst. Doch Mah'duun ist sich des Zeitpunkts nicht sicher.\n\nDas klingt alles sicherlich sehr seltsam für Euch, doch die Stimme im Wind sagte mir auch nicht viel mehr.\n\nBegebt Euch in die Höhlen der Zeit und reist in den Schwarzen Morast. Dort wird sich Euch alles offenbaren.", sourceObjective = "Netherpirscher Mah'duun hat Euch damit beauftragt, 4 Fürsten der Zeitenrisse zu töten. Kehrt erst zu ihm in das Untere Viertel in Shattrath zurück, wenn sie alle dem Tod überantwortet wurden.", completion = "Anscheinend habt Ihr Euren Weg in die Vergangenheit und wieder zurück gefunden. Eure Fähigkeiten als {class} sind bemerkenswert. Die Belohnung gehört Euch.\n\nKehrt morgen zu mir zurück, wenn die Winde Mah'duun ihren Willen offenbart haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[11384] = { id = 11384, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Warpzweigsplitter", description = "Vor Kurzem trat eine Druidin der Kaldorei mit einer herzzerreißenden Bitte an mich heran. Gut, sie hatte auch eine ganze Menge Gold bei sich...\n\nEs scheint, als versuchten die Streitkräfte von Darnassus ein arkanes Urtum namens Warpzweig neu zu erschaffen. Dieses gigantische Baumwesen hat sich wohl verirrt oder wurde von der Verderbnis durchdrungen, naja, jedenfalls hält es sich zurzeit in der Botanika der Festung der Stürme auf.", sourceObjective = "Windhändler Zhareem hat Euch darum gebeten, ihm einen Warpzweigsplitter zu beschaffen. Bringt diesen zu ihm ins Untere Viertel in Shattrath, um Eure Belohnung zu erhalten.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "Schwierigkeiten die Botanika zu finden? Ihr könnt sie gar nicht verfehlen, sie ist ein Teil der Festung der Stürme am östlichen Rand des Nethersturms.", completion = "Oh, Ihr habt es tatsächlich geschafft! Er ist so klein. Unglaublich, das Warpzweig aus diesem kleinen Ding neu erstehen soll und wie man mir sagte, ist es ein ziemlich langwieriger Prozess, den die Druiden da vor sich haben.\n\nEgal, wie versprochen, habe ich hier Eure Belohnung.\n\nKommt morgen wieder und ich werde einen weiteren Auftrag für Euch bereithalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[11385] = { id = 11385, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Kanalisierer der Sonnensucher", description = "Mah'duun wurde offenbart, dass die Kanalisierer der als Sonnensucher bekannten Kampfeinheit heute getötet werden müssen.\n\nIhr findet sie in der Botanika der Festung der Stürme.\n\nIhr wollt das Kopfgeld? Also tötet sie!", sourceObjective = "Netherpirscher Mah'duun hat Euch damit beauftragt, 6 Kanalisierer der Sonnensucher zu töten. Kehrt erst zu ihm in das Untere Viertel in Shattrath zurück, wenn sie alle dem Tod überantwortet wurden.", completion = "Mit den Kanalisierern ist es aus. Der, der aus dem Nether zu mir spricht ist zufrieden und Ihr habt Euch Eure Belohnung redlich verdient.\n\nKehrt morgen zu mir zurück, wenn die Winde Mah'duun ihren Willen offenbart haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[11386] = { id = 11386, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Pathaleons Projektionsgerät", description = "Ich habe stets angenommen, Pathaleon könnte sein Abbild nur mithilfe von Magie an die verschiedensten Orte in der Scherbenwelt projizieren. Offensichtlich lag ich damit falsch.\n\nMein neuester Kunde verriet mir, dass der Blutelf stattdessen ein mechanisches Gerät verwendet, um mit den diversen Offizieren von Kael'thas zu kommunizieren. Wenn ich es richtig verstanden habe, stahl er es von einigen Zaxxisrebellen im Nethersturm.\n\nMein Kunde wünscht, dieses Projektionsgerät zu besitzen. Also, warum stattet Ihr Pathaleon nicht einen Besuch ab? Ihr findet ihn in der Mechanar der Festung der Stürme.", sourceObjective = "Windhändler Zhareem hat Euch darum gebeten, ihm Pathaleons Projektionsgerät zu beschaffen. Bringt es zu ihm ins Untere Viertel in Shattrath, um Eure Belohnung zu erhalten.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "Es ist ja nicht so, dass die Projektionstechnologie alleine schon etwas Besonderes wäre, aber die Reichweite dieses Modells ist enorm und bisher unerreicht!", completion = "Ich bin versucht, es für mich zu behalten und meinem Kunden sein Geld zurückzuzahlen. Mit diesem Gerät könnte ich meine Geschäfte über noch größere Entfernungen abwickeln.\n\n<Der Windhändler seufzt.>\n\nAber ich kann meinen guten Ruf nicht so leichtfertig aufs Spiel setzen.\n\nWo wir schon von meiner Reputation reden, vielen Dank, dass Ihr mir dabei geholfen habt, sie zu wahren. Hier ist Eure Bezahlung.\n\nKommt morgen wieder und ich werde einen weiteren Auftrag für Euch bereithalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[11387] = { id = 11387, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Zerstörer der Sturmschmiede", description = "Im Inneren der Mechanar gibt es eine Vielzahl mechanischer Konstrukte und man hat Mah'duun mit ihrer Vernichtung beauftragt.\n\nBetretet die Festung der Stürme, sucht die Zerstörer der Sturmschmiede und vernichtet sie.\n\nKehrt anschließend zurück, um Eure Belohnung zu erhalten.", sourceObjective = "Netherpirscher Mah'duun hat Euch damit beauftragt, 5 Zerstörer der Sturmschmiede zu töten. Kehrt erst zu ihm in das Untere Viertel in Shattrath zurück, wenn sie alle vernichtet wurden.", progress = "<Der Netherpirscher scheint sich über Eure Anwesenheit zu wundern.>\n\nDie Zerstörer sind noch längst nicht alle vernichtet.", completion = "Mah'duun liebt es, gegen Konstrukte zu kämpfen! Sie sind nicht so fehlerbehaftet wie organische Lebewesen.\n\nIhr habt Euch die Belohnung verdient.\n\nKehrt morgen zu mir zurück, wenn die Winde Mah'duun ihren Willen offenbart haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[11388] = { id = 11388, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Horizontiss' Schriftrolle", description = "Meinem heutigen Kunden verlangt es nach etwas besonders Ausgefallenem.\n\nMan erzählt sich, dass Herold Horizontiss ein Jünger der Alten Götter sei. Des Weiteren soll er stets eine Schriftrolle bei sich tragen, die die Anweisungen der Götter für ihn enthalten, alles Leben im Universum in ihrem Namen zu unterwerfen.\n\nObwohl er die Schriftsprache der Rolle nicht entziffern können wird, wünscht mein Kunde dennoch, diese zu besitzen.\n\nDringt in die Arkatraz der Festung der Stürme ein und beschafft sie für mich, {class}!", sourceObjective = "Windhändler Zhareem hat Euch darum gebeten, ihm Horizontiss' Schriftrolle zu beschaffen. Bringt sie zu ihm ins Untere Viertel in Shattrath, um Eure Belohnung zu erhalten.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "Es muss ganz schön gefährlich sein, sich in die Angelegenheiten der Alten Götter einzumischen.\n\nNaja, besser Ihr als ich!", completion = "Bevor ich den Zorn der Alten Götter auf mich ziehe, hüte ich mich lieber davor, die Schriftrolle überhaupt zu berühren. Ich werde einen meiner Assistenten mit der Zustellung beauftragen.\n\nIhr habt Eure Belohnung mehr als verdient, {class}, und ich wünsche Euch für die Zukunft alles Glück der bekannten Welt!\n\nKommt morgen wieder und ich werde einen weiteren Auftrag für Euch bereithalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[11389] = { id = 11389, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Schildwachen der Arkatraz", description = "Die Schildwachen der Arkatraz sind wahnsinnig geworden. Die Gefangenen laufen Amok und die Wachen greifen all jene an, die helfen wollen.\n\nMah'duun vernimmt im Raunen des Netherwindes die Stimme des Sprechers. Der Sprecher befiehlt die Vernichtung der Schildwachen.\n\nBringt diese Aufgabe zu Ende und die heutige Belohnung gehört Euch!", sourceObjective = "Netherpirscher Mah'duun hat Euch damit beauftragt, 5 Schildwachen der Arkatraz zu töten. Kehrt erst zu ihm in das Untere Viertel in Shattrath zurück, wenn sie alle dem Tod überantwortet wurden.", completion = "Vielleicht wenden die Naaru sich nach der Vernichtung der Schildwachen an das Konsortium, um Ersatz anzufordern? Mah'duun weiß es nicht und es interessiert ihn auch nicht.\n\nIhr habt Euch Eure Belohnung redlich verdient.\n\nKehrt morgen zu mir zurück, wenn die Winde Mah'duun ihren Willen offenbart haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[11390] = { id = 11390, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich kann fliegen!", description = "Tja, auf was wartet Ihr denn noch, es gibt viel zu tun!\n\nHier sind die Schlüssel zu unserer Flugmaschine. Schnappt Euch drei Säcke voller Relikte und befördert sie auf die Kranplattformen auf der Nord- und Südseite des Stählernen Tores. Ich werd' sie für Euch markieren.\n\nMacht schnell! Wir haben nicht den ganzen Tag Zeit!", sourceObjective = "Der Chefarchäologe des Stählernen Tores möchte, dass Ihr 3 Säcke voller Relikte vom Grund der Ausgrabungsstätte zu einer der Plattformen auf der Nord- oder Südseite des Stählernen Tores befördert.\n\nBenutzt den Enterhaken der Flugmaschine für diese Aufgabe.\n\nMeldet Euch bei ihm zurück, sobald Ihr damit fertig seid.", completion = "Gute Arbeit - ich mein' jedoch, dass Ihr über einen Auffrischungskurs in Sachen grundlegende Fliegerei nachdenken solltet.\n\nNun ja, macht nichts, einer ist so gut wie der andere. Hier ist Eure heutige Ausbeute.", sourceObjectiveStatus = "unverified-source-field" }
quests[11391] = { id = 11391, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Patrouille am Stählernen Tor", description = "Äh? Heute wieder da zum Arbeiten?\n\nNun gut, hier sind die Schlüssel. Heute muss nichts mehr befördert werden, also haltet nur nach Dingen Ausschau, die verdächtig aussehen, okay?\n\nHab' ein paar Raketen und 'n Maschinengewehr auf sie draufgepackt - für den Fall der Fälle.", sourceObjective = "Für die Leute am Stählernen Tor seid Ihr jetzt ein Fliegerass, also will der Chefarchäologe des Stählernen Tores, dass Ihr über der Ausgrabungsstätte patrouilliert und alle Angreifer bekämpft.\n\nMeldet Euch wieder bei ihm zurück, wenn Ihr Eure Patrouille geflogen habt.", completion = "Gut geschossen, Ass.\n\nHier ist Euer Lohn. Kommt morgen wieder und dreht noch 'ne Runde, hört Ihr?", sourceObjectiveStatus = "unverified-source-field" }
quests[11392] = { id = 11392, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruft den kopflosen Reiter", description = "Zahlreiche düstere Kerzen schmücken den Kürbisschrein.", sourceObjective = "Bringt eine düstere Kerze zur leicht aufgewühlten Erde.", progress = "Die Erde scheint erst vor kurzem aufgewühlt worden zu sein. Auf der obersten Schicht liegen Regenwürmer, die sich winden, um der finsteren Tiefe zu entkommen.", completion = "Werdet Ihr die Kerze niederlegen und den kopflosen Reiter aus seiner unseligen Ruhe erwecken?", sourceObjectiveStatus = "unverified-source-field" }
quests[11393] = { id = 11393, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo ist Forscher Jaren?", description = "{name}, mein Verlobter Jaren ging mit einer kleinen Gruppe Forscher nach Westen, um Gerüchten über Artefakte entlang der Küste des Frostmaares nachzugehen. Dort unten gibt es jedoch Murlocs und ich befürchte, dass ihnen das Schlimmste zugestoßen sein könnte.\n\nIhr hättet sicherlich Zeit um nachzusehen, ob es ihnen gut geht, oder? Gleich hier in der Nähe, im Südwesten, gibt es einen Weg hinunter zum Strand - hütet Euch jedoch vor den Worgs und anderen Dingen, die im Wald herumstreunen.", sourceObjective = "Vorarbeiterin Irena Zasterstein hat Euch gebeten, nach ihrem Verlobten Forscher Jaren zu suchen.", completion = "<Der Forscher wirf Euch ein Lächeln zu, als Ihr ihm erzählt, wer Euch geschickt hat. Mit gedämpfter Stimme fährt er fort.>\n\nIrena hat sich um mich Sorgen gemacht? Das hat sie von ihrem Vater, müsst Ihr wissen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11394] = { id = 11394, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Und Ihr dachtet, Murlocs würden schlecht riechen!", description = "Ich bin ursprünglich hierhergekommen, um ein paar Gerüchten über auszugrabende Artefakte nachzugehen. Ich hab' zwar gewusst, dass es entlang dieser Küste Murlocs gibt, doch ich hätte nie und nimmer gedacht, dass ich so etwas sehen würde.\n\n<Der Forscher reckt seinen Hals und späht hinter dem Baum hervor.>\n\nDie Diener der Geißel sind dort draußen und sie verwandeln Murlocs und überhaupt alles, was ihnen in die Finger gerät, in wandelnde Tote!\n\n{class}, ich denke, dass es unsere Pflicht ist, etwas dagegen zu unternehmen. Wäre es denkbar für Euch, einen guten Teil dieser Geißel zu beseitigen?", sourceObjective = "Forscher Jaren hat Euch gebeten, entlang der Küste des Frostmaares wahllos 15 Diener der Geißel zu töten. Kehrt zu ihm zurück, sobald Ihr Eure Aufgabe erledigt habt.", completion = "<Jaren wirkt sehr erfreut über Euren Erfolg, macht jedoch Zeichen, dass Ihr flüstern sollt.>\n\nGute Arbeit, {name}! Eure Kleidung hat jedoch eine Menge von diesem klebrigem Geißelzeugs abbekommen. Vielleicht solltet Ihr Euch über ein kurzes Bad Gedanken machen. Das Wasser ist zwar kalt, wird Euch jedoch im Nu von dem Dreck befreien.", sourceObjectiveStatus = "unverified-source-field" }
quests[11395] = { id = 11395, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es ist eine Vorrichtung der Geißel", description = "Der Diener der Geißel, den Ihr soeben erlegt habt, hielt in seinen Klauen dieses Gerät. In ihm eingefasst, befindet sich ein Juwel, ähnlich den Juwelen, welche die Spitze geißelnder Kristalle bilden.\n\nForscher Jaren würde sicherlich gerne einen Blick darauf werfen.", sourceObjective = "Liefert die Vorrichtung der Geißel bei Forscher Jaren an der Küste des Frostmaares ab.", progress = "Was für ein seltsam anzusehendes Gerät Ihr da habt, {class}. Lasst mich einmal einen besseren Blick drauf werfen.", completion = "Ich weiß, was das ist! {name}, es ist eine Steuerung für diese geißelnden Kristalle!\n\nIch würde alles darauf verwetten, dass man mit ihrer Hilfe die Kraftfelder abschalten kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[11396] = { id = 11396, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schilde abschalten", description = "Seht Euch den Knopf an der Seite der Steuerung an - hier. Ich könnte wetten, dass man mithilfe der Steuerung dessen Schild abschalten könnte, wenn man nur nahe genug an einen der geißelnden Kristalle herankäme. Danach müsste das Ding nur rechtzeitig zerstört werden, bevor es seinen Schild wieder aktiviert.\n\nWas sagt Ihr dazu, {name}? Lust? Ich kann Euch versprechen, dass eine nette Belohnung winken würde, brächtet Ihr es zustande, die Schilde abzuschalten und die Kristalle zu zerstören.\n\nEs ist das Mindeste, was wir tun können, um die Geißel daran zu hindern, noch mehr Ihresgleichen zu erschaffen.", sourceObjective = "Forscher Jaren an der Küste des Frostmaares hat Euch gebeten, 3 geißelnde Kristalle zu zerstören.", completion = "Sehr schön!\n\n<Jaren wendet seinen Blick hastig in alle Richtungen, um nachzusehen, ob auch niemand seinen Ausbruch bemerkt hat.>\n\nGut, Ihr habt es Euch redlich verdient, hiervon eines auszusuchen - ich fand sie, als ich dort unten war.\n\nUnd {name}, sagt Irena, dass ich sie liebe und dass es mir gut geht, falls Ihr wieder beim Stählernen Tor vorbeischauen solltet.", sourceObjectiveStatus = "unverified-source-field" }
quests[11397] = { id = 11397, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Und Ihr dachtet, Murlocs würden schlecht riechen!", description = "Ich bin hierhergekommen, um ein Gerücht zu untersuchen, nach dem die Geißel hier in der Nähe präsent sei. Ich hatte zwar erwartet, entlang der Küste dort unten Murlocs vorzufinden, doch ich hätte nie und nimmer gedacht, dass ich so etwas sehen würde!\n\nDie Diener der Geißel sind dort unten und sie verwandeln Murlocs und überhaupt alles, was sie in die Finger bekommen, in wandelnde Tote!\n\n{class}, wir werden es nicht hinnehmen, dass sie noch mehr Ihresgleichen erschaffen - ganz besonders nicht aus Murlocs! Nicht weit weg vom Lager, im Nordwesten, befindet sich eine Rampe, die hinunter zum Strand führt. Seht zu, dass Ihr Euch rechtzeitig um die Geißel kümmert!", sourceObjective = "Apothekerin Anastasia möchte, dass Ihr entlang der Küste des Frostmaares wahllos 15 Diener der Geißel vernichtet. Kehrt zu ihr zurück, sobald Ihr Eure Aufgabe erledigt habt. Sie befindet sich im Apothekerlager.", completion = "<Anastasia scheint sich eine Zeit lang Gedanken über Euren Erfolg zu machen.>\n\nIhr habt Eure Aufgabe sicherlich zufriedenstellend erledigt, doch irgendwie habe ich das Gefühl, als müssten wir etwas anderes tun, um der Geißel auf diesem Strand Einhalt zu gebieten.", sourceObjectiveStatus = "unverified-source-field" }
quests[11398] = { id = 11398, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es ist eine Vorrichtung der Geißel", description = "Der Diener der Geißel, den Ihr soeben erlegt habt, hielt in seinen Klauen dieses Gerät. In ihm eingefasst, befindet sich ein Juwel, ähnlich den Juwelen, welche die Spitze geißelnder Kristalle bilden.\n\nApothekerin Anastasia würde sicherlich gerne einen Blick darauf werfen.", sourceObjective = "Liefert die Vorrichtung der Geißel bei Apothekerin Anastasia im Apothekerlager ab.", progress = "Was habt Ihr denn da, {class}? Lasst mich einmal einen besseren Blick darauf werfen!", completion = "Ich kann Euch sagen, was das hier ist, {name}. Es ist ein Steuergerät für die geißelnden Kristalle dort unten!\n\nIch würde alles darauf verwetten, dass man mit ihrer Hilfe die Kraftfelder abschalten kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[11399] = { id = 11399, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schilde abschalten", description = "Seht Euch den Knopf an der Seite der Steuerung an - hier. Ich könnte wetten, dass, käme man nahe genug an einen der geißelnden Kristalle heran, man mithilfe der Steuerung dessen Schild abschalten könnte. Danach müsste man das Ding nur rechtzeitig zerstören, bevor es seinen Schild wieder aktiviert.\n\nMutig genug, einen weiteren Abstecher dort hinunter zu wagen, {name}? Ich kann Euch versprechen, dass eine nette Belohnung winken würde, brächtet Ihr es zustande, die Schilde abzuschalten und die Kristalle zu zerstören.\n\nEs würde weniger Diener der Geißel bedeuten und dazu noch aus Murlocs geschaffene: Wie könntet Ihr es dann auch ablehnen?", sourceObjective = "Apothekerin Anastasia im Apothekerlager hat Euch gebeten, 3 geißelnde Kristalle zu zerstören.", completion = "<Anastasia dreht sich um und wirft ihrer Sukkubus ein Lächeln zu.>\n\nAlso gut, {name}, ich gestehe, dass Ihr gewiss verdient habt, Euch hiervon eins auszusuchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11400] = { id = 11400, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Braufestwidder", description = "Wenn Ihr Pol Bernruh, dem Widderrennlehrling, diesen Stempel auf Eurer Hand zeigt, dann wird er Euch gestatten, einen Braufestwidder zu erwerben.", sourceObjective = "Bringt den Handstempel \"Ehrenbrauer\" zu Pol Bernruh in der Nähe des Eingangs zum Braufestplatz in Dun Morogh.", sourceObjectiveStatus = "unverified-source-field" }
quests[11401] = { id = 11401, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruft den kopflosen Reiter", description = "Zahlreiche düstere Kerzen schmücken den Kürbisschrein, der höhnisch grinst...", sourceObjective = "Bringt eine düstere Kerze zur leicht aufgewühlten Erde.", progress = "Die Erde scheint erst vor kurzem aufgewühlt worden zu sein. Auf der obersten Schicht liegen Regenwürmer, die sich winden, um der finsteren Tiefe zu entkommen.", completion = "Werdet Ihr die Kerze niederlegen und den kopflosen Reiter aus seiner unseligen Ruhe erwecken?", sourceObjectiveStatus = "unverified-source-field" }
quests[11402] = { id = 11402, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clayton's Quest: Extreme!" }
quests[11403] = { id = 11403, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Endlich frei!", description = "Zorn hielt mich gefangen, {name}, Ihr habt mich befreit. Obgleich meine Taten mir nicht unrecht erschienen, so krümmt sich meine Seele jetzt bei dem Gedanken an all das Leid und den Tod, den ich den Bewohnern Azeroths gebracht habe, vor Schmerz.\n\nDanke, dass Ihr mich zurück zum Licht geführt habt. Möge ich nie mehr vom rechten Pfad abkommen.\n\nBringt dieses zerfetzte Gebetsbuch zu einer Waisenmatrone, damit die Kinder erfahren, dass ich sie nicht länger heimsuchen werde.", sourceObjective = "Bringt den Folianten von Thomas Thomson zu einer maskierten Waisenmatrone in Durotar, Brill oder beim Falkenplatz.", progress = "Schön, Euch wiederzusehen, {name}. Ich bin sicher, die Kinder freuen sich schon auf die Geschichten über Eure Heldentaten.", completion = "Was sagt Ihr? Dieser heilige Foliant gehörte einst einem gefallenen Paladin der Allianz. War er der kopflose Reiter? Also wurde er endlich besiegt?\n\nWas für ein glorreicher Tag, {name}! Eure Legende wird wachsen! Möge man noch von Euch berichten, wenn die Schreckensherrschaft des kopflosen Reiters längst vergessen ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[11404] = { id = 11404, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruft den kopflosen Reiter", description = "Zahlreiche düstere Kerzen schmücken den Kürbisschrein, der höhnisch grinst...", sourceObjective = "Bringt eine düstere Kerze zur leicht aufgewühlten Erde.", progress = "Die Erde scheint erst vor kurzem aufgewühlt worden zu sein. Auf der obersten Schicht liegen Regenwürmer, die sich winden, um der finsteren Tiefe zu entkommen.", completion = "Werdet Ihr die Kerze niederlegen und den kopflosen Reiter aus seiner unseligen Ruhe erwecken?", sourceObjectiveStatus = "unverified-source-field" }
quests[11405] = { id = 11405, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruft den kopflosen Reiter", description = "Zahlreiche düstere Kerzen schmücken den Kürbisschrein, der höhnisch grinst...", sourceObjective = "Bringt eine düstere Kerze zur leicht aufgewühlten Erde.", progress = "Die Erde scheint erst vor kurzem aufgewühlt worden zu sein. Auf der obersten Schicht liegen Regenwürmer, die sich winden, um der finsteren Tiefe zu entkommen.", completion = "Werdet Ihr die Kerze niederlegen und den kopflosen Reiter aus seiner unseligen Ruhe erwecken?", sourceObjectiveStatus = "unverified-source-field" }
quests[11406] = { id = 11406, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alles muss bereit sein", description = "Hauptmann Adams erwartet, dass alle Vorbereitungen in Fort Wildervar getroffen sind, sobald das Expeditionskorps gen Norden zieht. Die dortigen Späher und Handwerker wurden damit beauftragt, die Ausrüstungen und Rationen unserer Männer für den Aufstieg in die Hügel bereitzustellen.\n\nDer Hauptmann ist für sein hitziges Temperament berüchtigt, also möchte ich jemanden vorausschicken, um nach den Vorbereitungen zu sehen. Fort Wildervar befindet sich weit im Nordosten, jenseits von Skorn, in dem schneebedeckten Gebiet, das an die Grizzlyhügel grenzt. Sucht dort nach Gil Grisert und sorgt dafür, dass er bereit ist.", sourceObjective = "Sprecht mit Gil Grisert in Fort Wildervar.", completion = "Der Rüstmeister hat Euch also geschickt?\n\n<Gil wirkt erleichtert.>\n\nUm ehrlich zu sein, hinken wir hier ein bisschen hinterher und bräuchten etwas Hilfe, wenn wir unsere Ziele erfüllen wollen.\n\n<Gil läuft es kalt den Rücken hinunter.>\n\nKeiner meiner Männer hat Lust, Hauptmann Adams' Zorn die Stirn bieten zu müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11407] = { id = 11407, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marktschreier für die Brauerei Drohn!", description = "Ihr wollt dem Braufest also zu Stärke und Ehre verhelfen. Verbreitet die Kunde bei den Flaggen außerhalb des Auktionshauses im Tal der Stärke, im Tal der Ehre, im Tal der Weisheit und im Tal der Geister. Ruft, was das Zeug hält!\n\nWir werden Euch einen Rennwidder für 4 Minuten borgen.\n\nSeid aber vorsichtig. Diese geizigen Goblins haben entlang der Strecke keine Apfelkisten aufgestellt.", sourceObjective = "Verbreitet die Kunde vom Braufest bei den Flaggen außerhalb des Auktionshauses im Tal der Stärke, im Tal der Ehre, im Tal der Weisheit und im Tal der Geister.", completion = "Ihr habt Euer Wort gehalten und die Kunde von unseren Braumeistern verbreitet. Vielen Dank. Wir haben Euch diese Lose versprochen, hier habt Ihr sie. Ich kann mir gut vorstellen, dass die Trolle ihre Lose nicht so einfach rausrücken...\n\nIhr könnt uns gerne noch einmal helfen, kommt einfach an einem anderen Tag wieder.", sourceObjectiveStatus = "unverified-source-field" }
quests[11408] = { id = 11408, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marktschreier für T'chalis Voodoobrauerei!", description = "Wir müssen alle wissen lassen, dass die Trolle auf dem Braufest sind. Verbreitet die Kunde bei den Flaggen außerhalb des Auktionshauses im Tal der Stärke, im Tal der Ehre, im Tal der Weisheit und im Tal der Geister. Ruft, was das Zeug hält!\n\nIch werde Euch das Ganze etwas erleichtern, indem ich Euch meinen Rennwidder für 4 Minuten borge.\n\nSeid aber vorsichtig. Die Goblins haben entlang der Strecke keine Apfelkisten aufgestellt... so was von geizig.", sourceObjective = "Verbreitet die Kunde vom Braufest bei den Flaggen außerhalb des Auktionshauses im Tal der Stärke, im Tal der Ehre, im Tal der Weisheit und im Tal der Geister.", completion = "Ihr habt's wirklich gemacht! Wir müssen uns gleich auf den Ansturm der Besucher vorbereiten, die sicher schon auf dem Weg sind! Danke!\n\nOh, richtig, wir hatten Euch eine Belohnung versprochen. Das dürfen wir natürlich nicht vergessen...\n\nIhr könnt uns gerne noch einmal helfen, kommt einfach an einem anderen Tag wieder.", sourceObjectiveStatus = "unverified-source-field" }
quests[11409] = { id = 11409, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das ist Widderrennen... zumindest fast", description = "Ihr wollt also die Rennwidder testen? Die Zwerge bilden sich ein, dass sie's besonders drauf hätten; aber seien wir mal ehrlich, die meiste Zeit sind sie ja sowieso betrunken, so schwer kann's also gar nicht sein!\n\nSo, bevor Ihr Euch ins Abenteuer stürzt, müsst Ihr mir zeigen, dass Ihr mit diesen feinen, auf legale Weise erworbenen Widdern umgehen könnt.\n\nJetzt zur Abmachung. Ich lasse Euch dafür auf einem Widder reiten. Mal sehen, was Ihr drauf habt.\n\nLasst den Widder traben, dann leicht galoppieren und schließlich richtig galoppieren. Ihr müsst jede Geschwindigkeit 8 Sekunden lang halten.", sourceObjective = "Ihr habt 4 Minuten, um den Widder zu reiten und dabei 3 verschiedene Geschwindigkeitsstufen für jeweils 8 Sekunden zu halten.", progress = "Kommt Ihr mit dem Reitwidder zurecht?", completion = "Hey, das war gar nicht schlecht... seid Ihr sicher, dass Ihr kein Zwerg seid?\n\nEs gibt noch viel mehr Rennen, nicht nur von meiner Seite. Ihr werdet auf dem gesamten Braufestplatz Leute finden, die nach einem ordentlichen Widderrennmeister suchen. Also dann, macht Euch selbst mal nützlich.\n\nOh! Nicht, dass Ihr's vergesst, diese Widder wurden auf legale Weise erworben. Nur damit wir uns verstehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11410] = { id = 11410, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Eine, der entkam", description = "Die Barbe, die Ihr gebracht habt, sollte zwar ein guter Köder für die meisten Fische sein, doch ich befürchte, dass sie die Aufmerksamkeit eines Monsters erregen wird!\n\nAls ich das erste Mal hier war, brachte ich ein wenig von Nat Pagles Lieblingsköder an meinem Haken an und warf ihn ins Wasser aus. Allerdings klammerte sich ein riesiges Monster mit mächtigen Zähnen und Eiszapfen, die von seinen Flossen hingen, daran fest!\n\nEs hätte mich ins eisige Wasser gezogen, hätte ich die Leine nicht durchschnitten! Ich kann den neuen Köder nicht benutzen, solang' sich niemand um die alte Frostflosse kümmert. Nehmt diesen Köder und werft ihn in der Nähe des versunkenen Bootes in der Mitte des Sees aus. Frostflosse wird nicht widerstehen können!", sourceObjective = "Christopher Sloan in Fort Wildervar möchte, dass Ihr Frostflosse besiegt.", completion = "Endlich können wir in Ruhe fischen gehen! Aber es wird sowieso darauf hinauslaufen, dass sobald wir etwas fangen, das Expeditionskorps eintreffen und alles für sich beanspruchen wird.\n\nHabt unseren Dank, {name}. Fühlt Euch hier bei uns wie Zuhause.", sourceObjectiveStatus = "unverified-source-field" }
quests[11411] = { id = 11411, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lager der Winterhufe", description = "Auf meinen Reisen als Kurier habe ich schon viele seltsame Bewohner des Heulenden Fjords gesehen, doch eine Gruppe stach mir besonders ins Auge. Aus der Ferne sehen sie aus wie Tauren, doch bei näherer Betrachtung kann man erkennen, dass sie völlig verschieden sind - stämmiger und zotteliger.\n\nIch fand eine ihrer Siedlungen weit im Norden, jenseits von Halgrind, Skorn und den nördlichen Wäldern. Das Lager der Winterhufe, so wird es genannt. Es liegt inmitten der Ausläufer des Gjalerhorn, nahe der Grenze zu den Grizzlyhügeln. Nehmt Kontakt mit ihnen auf und seht nach, ob sie für uns von Nutzen sein könnten.", sourceObjective = "Sprecht mit Häuptling Aschtotem im Lager der Winterhufe.", sourceObjectiveStatus = "unverified-source-field" }
quests[11412] = { id = 11412, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hin und zurück", description = "Ich bin froh, dass Ihr hier seid. Wir haben einiges um die Ohren! Der Goblin, der uns mehr Gebräu bringen sollte, hatte auf seinem Weg von der Messerbucht hierher einen Unfall. Ihr müsst uns das Gebräu zustellen!\n\nIch werde Euch auf einen meiner Rennwidder setzen und Ihr folgt einfach der Straße zur Messerbucht.\n\nSobald Ihr nahe genug seid, wird man Euch ein Fässchen zuwerfen. Dann eilt Ihr wieder hierher zurück und werft es einem meiner fähigen Assistenten zu. Wir brauchen drei Fässchen. Erledigt Eure Sache gut, dann haben wir eventuell weitere Aufträge für Euch.", sourceObjective = "Holt bei dem Goblin, der auf der Straße zur Messerbucht festsitzt, ein Fässchen ab und bringt es zu Widdermeister Rays Assistenten. Wenn Ihr Euren Widder verliert, könnt Ihr Widdermeister Ray nach Ersatz fragen.", completion = "Vielen Dank für Eure Hilfe! Solange das Braufest noch im Gange ist, die Dunkeleisenzwerge immer wieder angreifen und unser Lieferant irgendwo feststeckt, brauche ich Hilfe bei der Auslieferung der Fässchen. Wenn Ihr Euch noch mehr Marken verdienen wollt, dann kommt jeden Tag wieder zu mir.\n\nHier sind die Marken, die wir Euch versprochen haben. Viel Spaß damit!", sourceObjectiveStatus = "unverified-source-field" }
quests[11413] = { id = 11413, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sagte da jemand \"Souvenir\"?", description = "Wir versorgen nicht nur jedermann mit Gebräu, sondern wir haben auch Krüge zu vergeben! Wunderschöne Andenken, die auf die legalste Weise überhaupt erworben wurden! Hier habt Ihr einen Gutschein.\n\nSprecht mit Blix, er hält sich irgendwo hinten beim Braufestlager auf. Er ist ziemlich seltsam, vor allem weil er jetzt immer diese Brille trägt. Er wird Euren Gutschein entgegennehmen und kümmert sich auch sonst um alle Braufestgeschäfte.", sourceObjective = "Löst Euren Gutschein für einen Braufestkrug bei Blix Fixtand im hinteren Teil des Braufestlagers ein.", sourceObjectiveStatus = "unverified-source-field" }
quests[11414] = { id = 11414, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verrat unter den Brüdern", description = "Behüterin Mondblatt ist in meinen Träumen erschienen! Ein Freund von ihr, ist ein Freund von mir.\n\nBis zum letzten Vollmond war ich der Alphaworg meines Rudels, doch dann kam der weiße Worg Garwal aus dem Norden und mithilfe meiner einstigen Brüder stieg er sehr schnell zum Alphaworg auf. Er hat irgendetwas Unnatürliches an sich.\n\nUm mir zu helfen, musst du zuerst diejenigen töten, die mich verraten haben.\n\nBjomolf jagt nordwestlich eines Ortes, den man das Stählerne Tor nennt. Und such' nach Varg: Er befindet sich im Südosten, in der Nähe des Westspeerturms.\n\nDein Aussehen wird sie nicht täuschen.", sourceObjective = "Ulfang im Bruchwald möchte, dass Ihr die verräterischen Worgs Bjomolf und Varg tötet. Kehrt zu ihm verkleidet zurück, sobald Ihr Eure Aufgabe erfüllt habt.\n\nFalls Ihr aus irgendeinem Grund die Worgverkleidung verlieren und nach Ersatz suchen solltet, müsstet Ihr zu Behüterin Mondblatt zurückkehren.", completion = "Der Geruch von Blut auf deiner Schnauze gefällt mir. Brüder sollten sich nicht gegenseitig bekämpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11415] = { id = 11415, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verrat unter den Brüdern", description = "Weiser Nebelläufer ist in meinen Träumen erschienen! Ein Freund von ihm ist ein Freund von mir.\n\nBis zum letzten Vollmond war ich der Alphaworg meines Rudels, doch dann kam der weiße Worg Garwal aus dem Norden und mithilfe meiner einstigen Brüder stieg er sehr schnell zum Alphaworg auf. Er hat irgendetwas Unnatürliches an sich.\n\nUm mir zu helfen, musst du zuerst diejenigen töten, die mich verraten haben.\n\nBjomolf jagt nordwestlich eines Ortes, den man das Stählerne Tor nennt. Und suche nach Varg: Er befindet sich im Südosten, in der Nähe des Westspeerturms.\n\nDein Aussehen wird sie nicht täuschen.", sourceObjective = "Ulfang im Bruchwald möchte, dass Ihr die verräterischen Worgs Bjomolf und Varg tötet. Kehrt zu ihm verkleidet zurück, sobald Ihr Eure Aufgabe erfüllt habt.\n\nFalls Ihr aus irgendeinem Grund die Worgverkleidung verlieren und nach Ersatz suchen solltet, müsstet Ihr zu Weiser Nebelläufer zurückkehren.", progress = "<Ein leises Knurren entweicht Ulfangs Kehle.>\n\nBjomolf und Varg sind nicht tot!", completion = "Der Geruch von Blut auf deiner Schnauze gefällt mir. Brüder sollten sich nicht gegenseitig bekämpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11416] = { id = 11416, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Augen des Adlers", description = "Garwal verbirgt sich hinter einem Schleier unnatürlicher Magie. Niemand kann ihn sehen oder riechen, außer er wünscht es. Eine Möglichkeit haben wir jedoch.\n\nMein Feind, der große Adler Klauenwürger, besitzt Augen, so sagt man, denen nichts entgeht. Nähmest du also seine Augen, würdest du Garwal sicherlich sehen können.\n\nKlauenwürgers Nest befindet sich am Ende des Wasserfalls, gleich südwestlich des Vrykuldorfs namens Skorn. Berührst du die Eier in seinem Nest, wird er vom Himmel kommen, um dich zu töten.\n\nHol' dir seine Augen.", sourceObjective = "Ulfang im Bruchwald möchte, dass Ihr die Augen des Adlers beschafft. Kehrt zu ihm verkleidet zurück, sobald Ihr Eure Aufgabe erfüllt habt.\n\nFalls Ihr aus irgendeinem Grund die Worgverkleidung verlieren und nach Ersatz suchen solltet, müsstet Ihr zu Behüterin Mondblatt zurückkehren.", progress = "Hast du die Augen des Adlers dabei?", completion = "<Ulfang heult lauthals, als er von Eurem Sieg über seinen Feind, den großen Adler, erfährt.>\n\nDass du ihn erlegt hast, macht dir alle Ehre. Ich wünschte, es wäre mein Maul gewesen, dessen Biss sein Ende herbeiführte.\n\nDas Opfer, welches er für uns erbrachte, soll nicht vergebens gewesen sein. Hier, friss!", sourceObjectiveStatus = "unverified-source-field" }
quests[11417] = { id = 11417, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Augen des Adlers", description = "Garwal verbirgt sich hinter einem Schleier unnatürlicher Magie. Niemand kann ihn sehen, außer er wünscht es. Eine Möglichkeit haben wir jedoch.\n\nMein Feind, der große Adler Klauenwürger, besitzt Augen, so sagt man, denen nichts entgeht. Nähmest du also seine Augen, würdest du Garwal sicherlich sehen können.\n\nKlauenwürgers Nest befindet sich am Ende des Wasserfalls, gleich südwestlich des Vrykuldorfs namens Skorn. Berührst du die Eier in seinem Nest, wird er vom Himmel kommen, um dich zu töten.\n\nHol' dir seine Augen.", sourceObjective = "Ulfang im Bruchwald möchte, dass Ihr die Augen des Adlers beschafft. Kehrt zu ihm verkleidet zurück, sobald Ihr Eure Aufgabe erfüllt habt.\n\nFalls Ihr aus irgendeinem Grund die Worgverkleidung verlieren und nach Ersatz suchen solltet, müsstet Ihr zu Weiser Nebelläufer zurückkehren.", progress = "Hast du die Augen des Adlers dabei?", completion = "<Ulfang heult lauthals, als er von Eurem Sieg über seinen Feind, den großen Adler, erfährt.>\n\nDass du ihn erlegt hast, macht dir alle Ehre. Ich wünschte, es wäre mein Maul gewesen, dessen Biss sein Ende herbeiführte.\n\nDas Opfer, welches er für uns erbrachte, soll nicht vergebens gewesen sein. Hier, friss!", sourceObjectiveStatus = "unverified-source-field" }
quests[11418] = { id = 11418, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir nennen ihn Stahlfeder", description = "Wir konnten beobachten, wie ein mutiger Hippogryph über dem Fort kreist, schließlich im Sturzflug nach unten schnellt und Beute macht. Jethan dort drüben hat schon ein paar Schüsse auf ihn abgegeben, aber seine Pfeile prallten einfach ab!\n\nWir haben uns daran gewöhnt, diese bemerkenswerte Kreatur Stahlfeder zu nennen, doch weshalb es die Gegend um Fort Wildervar herum bevorzugt, wissen wir nicht. Die meisten Hippogryphen nehmen sich vor Menschen in Acht.\n\nForscher Aderan hat uns dabei geholfen, aus einer der Federn der Kreatur einen Glücksbringer herzustellen. Er behauptet, dass es dem Benutzer erlaubt, die Welt durch Stahlfeders Augen zu sehen.", sourceObjective = "Spürt Stahlfeder auf, der über Fort Wildervar kreist, und benutzt den gefiederten Glücksbringer, um hinter sein Geheimnis zu kommen. Berichtet Gil Grisert anschließend von dem, was Ihr herausgefunden habt.", progress = "Hat Aderans Glücksbringer funktioniert?", completion = "Ihr habt ein Nest mit Jungen gesehen? Hmm, also ist unser \"er\" eigentlich eine \"sie\", oder?\n\nIch denke, dass sich damit die Sache erledigt hat. Ich würde es auch nicht wollen, dass man ein Nest voller Jungen nur deswegen an einen anderen Ort bringt, weil es einen neuen Nachbarn gibt.\n\n<Gil wirft Fallensteller Jethan einen spöttischen Blick zu.>\n\nBin mir sicher, dass wir gut miteinander auskämen, wenn der gute Jethan nicht versuchen würde, aus ihr eine Trophäe zu machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11419] = { id = 11419, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Braufestwidder", description = "Wenn Ihr Driz Purzelfix, dem Widderrennlehrling, diesen Stempel auf Eurer Hand zeigt, dann wird er Euch gestatten, einen Braufestwidder zu erwerben.", sourceObjective = "Bringt den Handstempel \"Ehrenbrauer\" zu Driz Purzelfix in der Nähe des Eingangs zum Braufestplatz in Durotar.", sourceObjectiveStatus = "unverified-source-field" }
quests[11420] = { id = 11420, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Weg zur Vergeltung", description = "Vor zwei Wochen hat unser Chefingenieur eine Harpunenkanone der Vrykul in die Finger bekommen - dieselbe Art Kanone, die diese Vrykul benutzen, um unsere Schiffe auszuschalten. Durch die Studien dieser Waffe konnte er eine umfangreiche Betriebsanleitung zusammenstellen.\n\nLeider wurde er gefangen und in das Dorf Wyrmskol nördlich von hier verschleppt. Wir haben ihn dann letztendlich gefunden, doch da lag er im Sterben und hatte die Anleitung nicht mehr bei sich. Seine letzten Worte deuten darauf hin, dass die Anleitung in den Katakomben von Utgarde verloren gegangen ist - jenem Ort, der sich im nordwestlichen Teil von Wyrmskol befindet. Besorgt mir diese Anleitung!", sourceObjective = "Wachoffizier Zorek bei Valgarde am Heulenden Fjord möchte, dass Ihr die Harpunenbetriebsanleitung zurückholt.", progress = "Habt Ihr die Anleitung gefunden?", completion = "<Zorek blättert die Anleitung durch.>\n\nDer Anleitung nach haben die Vrykul ein Spezialwerkzeug, welches ihnen erlaubt, die Harpunen mit tödlicher Präzision zu bedienen. Es sieht ein bisschen wie das Rad eines unserer Schiffe aus. Zudem ist es tragbar und scheint wie ein Schlüssel in die Harpunen zu passen. Wir müssen eines davon in die Finger bekommen!", sourceObjectiveStatus = "unverified-source-field" }
quests[11421] = { id = 11421, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jetzt drehen wir mal richtig auf...", description = "Wir müssen zuschlagen, solange die Verwirrung unter den Truppen der Vrykul anhält! Nehmt den Harpunenkontrollmeachanismus an Euch und sucht entlang der Klippen das am nördlichsten gelegene Harpunengebäude des Dorfes.\n\nNehmt eine der vrykulschen Harpunenkanonen auf dem Dach des Gebäudes in Euren Besitz, sobald Ihr dort seid, und macht Wyrmskol die Hölle heiß! Zerstört das Lang- und Dockhaus, das Lager und sämtliche Verteidiger, die die Vrykul auf Euch hetzen könnten!\n\nSolltet Ihr dies vollbringen, wird die Dolchbucht ein viel sicherer Hafen sein!", sourceObjective = "Leutnant Eishammer im Heulenden Fjord möchte, dass Ihr das Langhaus der Drachenschinder, das Dockhaus der Drachenschinder, das Lager der Drachenschinder und 8 Verteidiger der Drachenschinder vernichtet.\n\nBringt den Harpunenkontrollmechanismus zu ihm zurück, sobald Ihr Eure Aufgabe erledigt habt.", progress = "Steht Wyrmskol in Flammen?", completion = "Ausgezeichnete Arbeit, {name}! Ihr habt einen guten Teil dieser Drachenreiter ausgeschaltet und ihre Führung richtig sauer gemacht.\n\nSeid Ihr bereit, nach Valgarde zurückzukehren und Zorek die guten Neuigkeiten zu überbringen? Falls dem so ist, dann hätte ich da eine verrückte Idee!", sourceObjectiveStatus = "unverified-source-field" }
quests[11422] = { id = 11422, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dreizack des Sohnes", description = "<Die Kratzer, die er in den Felsen ritzt, stellen mehrere Symbole dar: einen Dreizack, einen Mur'ghul, die Sonne, ein Schiffswrack und ein grobes Strichmännchen, welches Euch darstellt.>\n\n<Es braucht einige Zeit dahinterzukommen, was Euch der Murloc mitteilen möchte. Offensichtlich will er, dass Ihr ihm einen Dreizack von der Küste des Frostmaares besorgt, doch was das Bild der Sonne bedeuten soll, ist Euch ein Rätsel - zumindest bis Ihr erkennt, dass er damit seinen Sohn meint.>\n\n<Sein Sohn wurde in einen Mur'ghul verwandelt! Er möchte, dass Ihr nach Süden geht, in der Nähe des Schiffswracks nach ihm sucht und seinen Dreizack zurückbringt.>", sourceObjective = "Alte Eisflosse möchte, dass Ihr Rottkiems Dreizack zurückholt. Er wohnt auf der kleinen Insel an der Küste des Frostmaares.", progress = "<Alte Eisflosse beäugt Euch mit einem seiner toten Augen und sucht nach Zeichen des Dreizacks seines Sohnes.>", completion = "<Als er seine Hand ausstreckt, um den Dreizack von Euch in Empfang zu nehmen, zittert diese ein wenig. Könnte es sein, dass der gealterte Murloc trauert?>\n\n<Was sammelt sich da für eine Flüssigkeit in seinem Auge?>", sourceObjectiveStatus = "unverified-source-field" }
quests[11423] = { id = 11423, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Vermächtnis des Feindes", description = "Während unsere Armeen durch Nordend marschieren, werden unsere Feinde nicht nur Niederlage um Niederlage erleiden müssen. Ihre Häuser werden in Flammen stehen, unsere Seuchen werden ihre Leichen zerfressen, jede Spur ihrer Existenz wird vom Erdboden getilgt sein.\n\nFür jemanden wie mich, den es nach Wissen dürstet, ist das beunruhigend. Niffelvar, die Stadt im Osten, wird bald von unseren Streitkräften aus dem Hafen der Vergeltung ausgelöscht werden. Helgus, der Barde der Vrykul, lebte dort und schrieb drei Sagen: die Sage der Zwillinge, die Sage des Winterfluchs und die Sage der Val'kyr. Besorgt diese, bevor Niffelvar dem Erdboden gleichgemacht wird.", sourceObjective = "Reist nach Niffelvar nördlich des Geisterklingenpostens und sucht die Sage des Winterfluchs, die Sage der Val'kyr und die Sage der Zwillinge.", progress = "Die Schriftrollen, {name}? Habt Ihr sie?", completion = "Dies ist von enormem Wert, {name}. Ich muss meine Anstrengungen erneut aufnehmen, Texte der Vrykul zu übersetzen.\n\nVersteht mich nicht falsch. Unsere Feinde müssen vernichtet werden... nicht so ihr uraltes Wissen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11424] = { id = 11424, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schildhügel", description = "Meine Arbeit sollte in Kriegszeiten eigentlich ziemlich leicht sein - es müsste überall brauchbare Körperteile geben.\n\nDoch so einfach ist es nicht. Wenn diese Eierköpfe alles Mögliche an tödlichen Plagen in den feindlichen Dörfern freisetzen, werden dabei die meisten Materialien verunreinigt.\n\nEs gibt jedoch einen Ort, an dem sich brauchbare Exemplare finden lassen. Der Schildhügel südlich von hier ist ein alter Friedhof der Vrykul. Dort laufen die Toten noch herum, sind aber frei von irgendwelchen Seuchen - sowohl von unseren als auch denen des Lichkönigs. Besorgt mir ein paar Knochen und ich werd' Euch gut bezahlen.", sourceObjective = "\"Eisensäge\" Jenny möchte, dass Ihr 5 alte Knochen der Vrykul von den wiederauferstandenen Vrykul beim Schildhügel südlich von Neu-Agamand besorgt.", progress = "Habt Ihr nun meine Knochen?", completion = "Hmpf... die werden erstmal reichen. Irgendwas scheint mit ihnen nicht zu stimmen.\n\nIch sag's Euch, ich hantiere schon seit Jahren mit Körperteilen herum, aber ich hatte noch nie so'n komisches Gefühl im Bauch. Wie dem auch sei, Geschäft ist Geschäft. Hier ist Eure Bezahlung.", sourceObjectiveStatus = "unverified-source-field" }
quests[11426] = { id = 11426, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Mechanismus ausfindig machen", description = "Macht Euch keine Sorgen, {name}; all dies wird zu etwas Großem führen! Etwas RIESIGEM! Ihr müsst mir nur erst einmal vertrauen und tun, wie ich es Euch sage.\n\nFür die nächste Stufe des Planes, müssen wir einen in der Anleitung erwähnten Mechanismus besorgen. Ich habe den starken Verdacht, dass Ihr einen bei einem dieser Vrykuls finden werdet, welche die Harpunenkanonen in Wyrmskol bedienen. Ihr werdet sie auf der Ostseite des Dorfes an den Docks bei den Langhäusern finden.", sourceObjective = "Wachoffizier Zorek bei Valgarde am Heulenden Fjord möchte, dass Ihr ihm einen Harpunenkontrollmechanismus bringt.", progress = "Habt Ihr den Mechanismus gefunden?", completion = "Überragend! Diese zu groß geratenen Affen werden bald merken, was es heißt, sich mit der Allianz anzulegen!", sourceObjectiveStatus = "unverified-source-field" }
quests[11427] = { id = 11427, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trefft Leutnant Eishammer", description = "Seht Ihr diese Gebäude der Vrykul auf den Klippen im Nordosten? Die Vrykul nennen diesen Ort Niffelvar. Von dort aus kommen die meisten Ihrer Harpunenangriffe auf unsere Fregatten.\n\nDoch wisst Ihr was? Es ist Zeit es ihnen heimzuzahlen, {name}. Nehmt diesen Harpunenkontrollmechanismus und trefft Euch mit Leutnant Eishammer, der sich in einem Gebäude der Vrykul im Nordwesten von Niffelvar versteckt hält.\n\nWenn Ihr bereit seid, könnt Ihr Euch auf einen meiner Greifen schwingen und Ihr werdet schnurstracks zu ihm gebracht!", sourceObjective = "Wachoffizier Zorek möchte, dass Ihr den Harpunenkontrollmechanismus zu Leutnant Eishammer außerhalb von Niffelvar bringt.", progress = "Was ist das denn? Sehe ich aus wie ein Kindermädchen?", completion = "<Leutnant Eishammer nimmt Euch den Harpunenkontrollmechanismus ab.>\n\nAh, Ihr bringt Geschenke!", sourceObjectiveStatus = "unverified-source-field" }
quests[11428] = { id = 11428, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hüter Welkblatt", description = "Eure Freundschaft und Unterstützung haben uns schon viel geholfen, {name}. Es gibt jedoch noch eine Sache, um die ich Euch bitten muss.\n\nIhr habt sie gesehen, die Verderbnis, welcher die Siechende Lichtung und die dort lebenden Biester anheim gefallen sind. Die schwarzbeseelten Bewahrer werden diese Monstrositäten weiterhin aus den Wassern und der Erde unserer Lichtung auferstehen lassen, wenn wir nichts gegen sie unternehmen.\n\nDer mächtigste unter den schwarz beseelten Bewahrern wird Hüter Welkblatt genannt. Tötet ihn, {name}, und Ihr werdet damit den Weg zur Errettung der Lichtung ebnen, so wie Ihr einst den Weg zur Errettung meiner Schwestern ebnetet.", sourceObjective = "Lurielle auf der Gefrorenen Lichtung möchte, dass Ihr Hüter Welkblatt tötet.", completion = "Als ich hörte, dass die Bewahrer sich gegen uns gewendet hatten, brach mir das Herz. Einst betrachteten wir sie als unsere Brüder und engsten Freunde.\n\nMeine Trauer gilt unseren verlorenen Brüdern und Schwestern, doch ohne Eure Hilfe gäbe es für uns keine Hoffnung auf die Zukunft. Ihr werdet hier unter uns immer willkommen sein, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[11429] = { id = 11429, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufstellen und abrocken!", description = "Ich habe nicht die Absicht, das Schicksal dieser Mission in die Hände irgendeines Möchtegerns zu legen, der noch nicht auf die Probe gestellt wurde.\n\nWenn Ihr mir also beweisen wollt, dass Ihr das Zeug dazu habt, diese Mission auszuführen, werdet Ihr das machen müssen, was ich Euch sage.\n\nNehmt diese Schlachtstandarte und macht Euch auf den Weg nach Quälheim, gleich nördlich von hier. Begebt Euch zur Ortsmitte und stellt unsere Flagge auf, sobald Ihr dort angelangt seid. Wehrt sämtliche Vrykuldrecksäcke, die versuchen sollten, unsere geliebte Flagge zu beseitigen, ab und kehrt zu mir zurück, sobald Ihr die Vorherrschaft der Allianz gesichert habt.", sourceObjective = "Leutnant Eishammer im Heulenden Fjord möchte, dass Ihr das Banner der Allianz in Quälheim aufstellt und dieses gegen Angreifer verteidigt.\n\nKehrt gemeinsam mit dem Banner zu Leutnant Eishammer zurück, falls Ihr überleben solltet.", progress = "Noch immer am Leben, wie ich sehe. Offensichtlich strengt Ihr Euch nicht richtig an.", completion = "Für die Allianz! Ihr beweist Stärke, {name} - genug, um einigen Vrykul in Niffelvar die Schädel einzuschlagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11430] = { id = 11430, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Harpunenmeister Yavus", description = "Das war eine ziemlich eindrucksvolle Vorstellung, die Ihr da geliefert habt, {name}. Doch bevor Ihr Euch selbst auf die Schulter klopft: In Niffelvar gibt es noch Arbeit zu erledigen.\n\nWir haben den Vrykul, der für die meisten Harpunenangriffe auf unsere Fregatten verantwortlich ist, ausfindig gemacht - nennt sich Yavus. Ihr findet ihn in der Hauptharpunenanlage an den Klippen von Niffelvar, südlich von hier.\n\nSpürt ihn auf und richtet ihn für seine Verbrechen gegen die Allianz!\n\nMacht mich stolz, {name}!", sourceObjective = "Leutnant Eishammer im Heulenden Fjord möchte, dass Ihr Harpunenmeister Yavus in Niffelvar tötet.", completion = "Sie werden einige Zeit brauchen, um Yavus zu ersetzen. Jetzt ist der perfekte Zeitpunkt, um Zoreks Plan in die Tat umzusetzen! Während sie sich eiligst darum kümmern, Niffelvar wieder unter ihre Kontrolle zu bringen, werdet Ihr ihre eigenen Harpunenkanonen in Besitz nehmen und gegen sie verwenden!", sourceObjectiveStatus = "unverified-source-field" }
quests[11431] = { id = 11431, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fangt die wilden Wolpertinger!", description = "Hey, Ihr da. Ich bin ein verrückter Zwerg! Wir Zwerge glauben, dass man unsichtbare Kreaturen sehen kann, wenn man nur mit ausreichend Gebräu versorgt ist. Wahrscheinlich wandern einige sogar gerade jetzt auf dem Braufestplatz umher! Ihr könnt sie aber nur sehen, wenn Ihr eine Synthebräubrille tragt.\n\nVielleicht gäbe es auch einen anderen Weg, aber er ist mir nicht bekannt.\n\nAlso, bringt mir mithilfe dieses Netzes, das ich von einem wirklich betrunkenen Zwerg habe, fünf Wolpertinger.\n\nWenn Ihr sie nicht sehen könnt, sagt es mir und ich gebe Euch eine Synthebräubrille.", sourceObjective = "Der \"Zwerg\" Glodrak Jägerspatz möchte, dass Ihr 5 betäubte Wolpertinger mit dem Wolpertingernetz einfangt. Er hat auch erwähnt, dass Ihr eine Synthebräubrille tragen müsst, um die Biester sehen zu können.", progress = "Habt Ihr etwas für mich oder sucht Ihr nur wieder nach einem Grund, um Euch zu betrinken?", completion = "Was! Es gibt sie wirklich? Jetzt tut es mir richtig leid, dass ich diesem Zwerg gegen das Knie getreten habe...\n\nIch brauche eine Minute... und einen Schluck...\n\n<Er trinkt aus seinem Krug.>\n\nIch denke, ich überlasse Euch einen... als Beweis dafür, dass betrunkene Zwerge - gibt es überhaupt andere? - wirklich die Wahrheit sagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11432] = { id = 11432, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlafende Riesen", description = "Ich habe zufällig mit anhören können, über was Ihr mit Vater Levariol gesprochen habt. Erlaubt mir, Euch darauf hinzuweisen, dass der Auftrag, den er Euch erteilt hat, nicht weit genug geht.\n\nIhr müsst Euch auch um die Vrykul kümmern, die in den Hallen des Erwachens tief im Fels unter Gjalerbron im Schlaf liegen!\n\nIch hege keine Zweifel daran, dass die Rituale, mit deren Hilfe man sie erweckt, der Schlüssel zu ihrem Untergang sind. Die Nekrolords verfügen höchstwahrscheinlich über irgendeine Vorrichtung, mit der Ihr die Vrykul vorzeitig aus ihrem Schlaf reißen könnt.\n\nSolch eine Behelligung wird sich für die Vrykul als fatal erweisen.", sourceObjective = "Magierleutnant Malister hat Euch damit beauftragt, 5 schlafende Vrykul zu töten. Kehrt zu ihm zurück, sobald Ihr Eure Aufgabe erledigt habt. Er befindet sich in Westwacht.", completion = "Ihr habt getan, was getan werden musste. Es mag vielleicht sein, dass gewisse Leute das Töten Wehrloser als unehrenhafte Tat betrachten, doch in diesem Fall wäre es töricht gewesen, nicht so zu handeln.\n\nUnd wir hätten sie doch nicht einfach so dort herumstehen lassen können, nur damit sie später durch ein Ritual erweckt werden, oder?\n\nEs war eine mutige Sache, die Ihr dort unten in den Katakomben für uns alle hier oben geleistet habt, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[11433] = { id = 11433, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlafende Riesen", description = "Ich habe zufällig mit anhören können, über was Ihr mit Großmutter Ankha gesprochen habt. Bei allem Respekt, aber ich meine, dass der Auftrag, den sie Euch erteilt hat, nicht weit genug geht.\n\nIhr müsst Euch auch um die Vrykul kümmern, die in den Hallen des Erwachens tief im Fels unter Gjalerbron im Schlaf liegen!\n\nIch hege keine Zweifel daran, dass die Rituale, mit deren Hilfe man sie erweckt, der Schlüssel zu ihrem Untergang sind. Die Nekrolords verfügen höchstwahrscheinlich über irgendeine Vorrichtung, mit der Ihr die Vrykul vorzeitig aus ihrem Schlaf reißen könnt.\n\nSolch eine Behelligung wird sich für die Vrykul als fatal erweisen.", sourceObjective = "Ahota Weißfrost hat Euch damit beauftragt, 5 schlafende Vrykul zu töten. Kehrt zu ihm zurück, sobald Ihr Eure Aufgabe erledigt habt. Er befindet sich im Lager der Winterhufe.", completion = "Ihr habt getan, was getan werden musste. Es mag vielleicht sein, dass die Unklugen das Töten Hilfloser während sie aufwachen als unehrenhafte Tat betrachten, doch in diesem Fall wäre es töricht gewesen, nicht so zu handeln.\n\nUnd wir hätten sie doch nicht einfach so dort herumstehen lassen können, nur damit sie später durch ein Ritual erweckt werden, oder?\n\nEs war eine mutige Sache, die Ihr dort unten in den Katakomben für uns alle hier oben geleistet habt, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[11434] = { id = 11434, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vergessene Schätze", description = "Ich hab' ein Vermögen gemacht, weil ich mich auf Schätze spezialisiert hab', auf die gewöhnliche Piraten keinen Wert legen: Kunst, Antiquitäten, Sammlerstücke.\n\nSüdlich von hier ist die Stelle, an der die Flotte vom schwarzen Konrad vor Jahren einmal sank. Doch Taucher haben alles an Gold und Juwelen weggeschafft - nichts ist übrig geblieben, bis auf zwei uralte Artefakte. Eins davon ist eine Amanivase in Museumsqualität, das andere ist eine Adlerfigurine.\n\nGeht, beschafft mir die Dinger und ich werd' ein gutes Wörtchen für Euch bei den anderen Piraten einlegen. Ich würd' sogar was beisteuern, damit sich Euer Unterwasserabenteuer etwas leichter bewältigen lässt.", sourceObjective = "Der hübsche Terry im Halunkeneck möchte, dass Ihr ihm 1 Amanivase und 1 Adlerfigurine aus dem Schiffswrack gen Süden holt.", progress = "Habt Ihr meine Relikte beschaffen können, {name}? Mit Schönheit alleine kommt man im Leben auch nicht über die Runden... selbst ich nicht!", completion = "Gemeinsam werden wir's zu was bringen, {name}. Mit meinem guten Aussehen und Eurem... unerschütterlichen Optimismus werden wir sicherlich ein dickes Geschäft machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11436] = { id = 11436, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gehen wir Harpunenreiten!", description = "An den steilen Klippen des Heulenden Fjords vorbeizunavigieren, kann ein nervenaufreibendes Unterfangen sein! Ich hab' jedoch herausgefunden, wie man mithilfe von Vrykultechnologie und zwergischer Raffinesse etwas herstellen kann, das die Sache einfacher gestalten wird. Es hat nur ein paar Einstellungen und Feinabstimmungen gebraucht und Eishammers Harpunensteuerung war fertig! Natürlich wurde sie noch nicht getestet, aber deswegen seid Ihr ja hier!\n\nNehmt die Steuerung, geht zur großen Kanone in Niffelvar und katapultiert Euch mit ihrer Hilfe nach Valgarde. Erstattet Zorek Bericht, falls Ihr Erfolg haben solltet. Oh ja, da fällt mir ein: Ihr könnt die Steuerung behalten.", sourceObjective = "Katapultiert Euch mithilfe der großen Harpunenkanone der Vrykul nach Valgarde. Erstattet Wachoffizier Zorek Bericht, falls Ihr Erfolg haben solltet.", progress = "<Zorek blickt Euch an und hebt eine Braue.>", completion = "Ihr seid verrückt, {name}! Jetzt mal ehrlich: Welcher Trottel würde eine Harpunenkanone als Beförderungsmittel verwenden?\n\nIch denke jedoch, dass man ein wenig verrückt sein muss, um das abzuziehen, was Ihr dort oben an den Klippen abgezogen habt! Fantastische Arbeit! Wir haben Nachricht erhalten, dass Ingvar, der Anführer der Drachenschinder, vor Wut nur so tobt! Vielleicht werdet Ihr ihn eines Tages in den Boden stampfen können - im Namen unserer geliebten Allianz.", sourceObjectiveStatus = "unverified-source-field" }
quests[11439] = { id = 11439, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Übung bei der Brandwache", description = "Jetzt, da der kopflose Reiter in der Gegend ist, sind die mutigen Zwerge von Kharanos jederzeit für einen Einsatz der Brandwache bereit. Wollt auch Ihr helfen?\n\nDie Gebirgsjäger haben südlich von hier ein kleines Lager für Übungen der Brandwache aufgestellt. Geht dorthin und löscht Feuer mithilfe von Wassereimern. Ihr könnt Eure Eimer hier beim Wasserfass füllen.\n\nBis dann, {name}. Besucht uns bitte wieder, wenn Ihr genug geübt habt!", sourceObjective = "Löscht 5 Feuer mit Wassereimern und sprecht anschließend mit der kostümierten Waisenmatrone.", completion = "Ihr seid ja pitschnass und mit Ruß verschmiert! Beim Feuerlöschen gewesen, nicht wahr?\n\nGut gemacht! Als ehrenamtliches Mitglied der Brandwache bitte ich Euch, wieder hierher zurückzukommen, falls unser Dorf Euch brauchen sollte!", sourceObjectiveStatus = "unverified-source-field" }
quests[11440] = { id = 11440, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Übung bei der Brandwache", description = "Solange der kopflose Reiter noch Angst und Schrecken verbreitet, sind die Friedensbewahrer jederzeit bereit für einen Einsatz der Brandwache. Wollt Ihr auch helfen?\n\nDie Friedensbewahrer haben westlich von hier, in Richtung der Exodar, ein kleines Lager für Übungen der Brandwache aufgestellt. Geht dorthin und löscht Feuer mithilfe von Wassereimern. Ihr könnt Eure Eimer hier beim Wasserfass füllen.\n\nBis dann, {name}. Besucht uns bitte wieder, wenn Ihr genug geübt habt!", sourceObjective = "Löscht 5 Feuer mit Wassereimern und sprecht anschließend mit der kostümierten Waisenmatrone.", sourceObjectiveStatus = "unverified-source-field" }
quests[11441] = { id = 11441, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Braufest!", description = "Sprecht mit dem Organisator des Braufests beim Braufestplatz außerhalb von Eisenschmiede, um ein kostenloses Bier zu erhalten.", sourceObjective = "Sprecht mit dem Organisator des Braufests.", completion = "Ho ho! Seid Ihr wegen des Freibiers hier?", sourceObjectiveStatus = "unverified-source-field" }
quests[11442] = { id = 11442, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Willkommen auf dem Braufest!", completion = "Ho ho! Seid Ihr wegen des Freibiers hier?" }
quests[11443] = { id = 11443, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tauchgang in der Dolchbucht", description = "Hä... ähm... Was ist los? Was macht Ihr dort unten?\n\nIch? Oh... nun ja, seht Ihr... ich bin... ähm... Ich versuche hier ein wenig aufzuräumen! Befehl von Keller höchstpersönlich! \"Harry,\" hat er zu mir gesagt, \"ich will, dass du dir 'ne Tauchglocke aufsetzt und in den Schiffswracks in der Dolchbucht nach UNSEREM Zeugs suchst...\"\n\nHe, wenn Ihr schon mal hier unten seid, vielleicht könntet Ihr mir dann helfen. In der ganzen Bucht liegen allerhand Schmuckstü... ähh, ich meine Vorratskisten herum. Geht und bringt mir alles, was Ihr finden könnt. Setzt Euch den Taucherhelm auf, damit Euch die Luft nicht ausgeht.", sourceObjective = "Harold Lagras auf dem Grund der Dolchbucht möchte, dass Ihr ihm 10 Vorratskisten von Valgarde bringt.", progress = "Habt Ihr die Vorratskisten gefunden?", completion = "Super! Ihr seid mit Sicherheit sehr effizient. So ist's... Ach was, gebt mir einfach die Kisten. Ich muss sie in meinem Büchlein verzeichnen, Inventur machen und ein paar andere Sachen, die Ihr nicht versteht und für die Ihr nicht ausgebildet seid, an mich nehmen. Macht Euch keine Sorgen, ich werde Keller auf jeden Fall sagen, was für tolle Arbeit Ihr hier unten geleistet habt! - genau. M-hm, Ihr könnt jetzt gehen. Husch, husch!", sourceObjectiveStatus = "unverified-source-field" }
quests[11446] = { id = 11446, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Braufest!", description = "Sprecht mit dem Organisator des Braufests beim Braufestplatz außerhalb von Orgrimmar, um ein kostenloses Bier zu erhalten.", sourceObjective = "Sprecht mit dem Organisator des Braufests.", completion = "Was?! Freibier? Ja, schon gut. Ich schätze, so etwas in der Art haben wir für dieses Jahr versprochen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11447] = { id = 11447, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Willkommen auf dem Braufest!", completion = "Was?! Freibier? Ja, schon gut. Ich schätze, so etwas in der Art haben wir für dieses Jahr versprochen." }
quests[11448] = { id = 11448, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Außenposten der Forscherliga", description = "Das ist alles ein Haufen kryptischer Unsinn! Trotz dieser Glyphe werde ich aus den Tafeln einfach nicht schlau. Zugegeben, Kryptografie ist nicht eine meiner Stärken.\n\nIhr werdet die Glyphe und Tafeln zu unserem Kryptografen Stanwad bringen müssen. Unglücklicherweise habe ich seit zwei Wochen nichts mehr von Stanwad gehört. Er nahm ein Team aus zwanzig Wissenschaftlern mit zur Ausgrabungsstätte an den südöstlichen Klippen des Fjords und seitdem hat man nichts mehr von ihm gehört. Das Beste, was ich machen kann, ist es, McGoyver da drüben zu sagen, dass er Euch auf seiner Flugmaschine mitnehmen soll.", sourceObjective = "Liefert McSorfs Bündel bei Stanwad im Außenposten der Forscherliga im Heulenden Fjord ab.", progress = "<Stanwad gibt seiner Unzufriedenheit mit einem Brummen Ausdruck.>", completion = "<Stanwad nimmt Euch das Bündel ab und fängt an, die Daten zu sortieren.>\n\nUnglaublich. Wie viele Leute meint Ihr, haben für diese Informationen ihr Leben gelassen?\n\n<Stanwad schüttelt seinen Kopf.>\n\nIhr werdet Euch wahrscheinlich darüber freuen, dass das, was McSorf und sein Trupp an ausgemachten Idioten herausgefunden haben, ein uraltes Rezept für einen Tundraeintopf ist. Hat er nicht bemerkt, dass die Symbole gewöhnliche Gemüsesorten darstellen und das Piktogramm einen Humanoiden zeigt, der besagtes Gemüse mampft? Man braucht keine verdammte Glyphe, um diesen Code zu knacken!", sourceObjectiveStatus = "unverified-source-field" }
quests[11449] = { id = 11449, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuerübung", description = "Die Todespirscher haben ein Übungslager zum Feuerlöschen außerhalb der Stadt aufgebaut. Weitere Schäden an den Gebäuden von Brill können wir uns nicht leisten - also erfüllt Eure Pflicht und übt Euch im Feuerlöschen!\n\nGeht Richtung Westen am Friedhof vorbei und folgt dem Straßenverlauf, bis Ihr das Übungslager erreicht.", sourceObjective = "Löscht 5 Feuer mit Wassereimern und sprecht anschließend mit der maskierten Waisenmatrone in Brill.", progress = "Habt Ihr ein paar Feuer gelöscht, {name}? Das Übungslager liegt westlich von Brill.", completion = "Gut gemacht, {name}! Kinder, seht Euch diesen Helden gut an. Nehmt Euch ein Beispiel an ihm.", sourceObjectiveStatus = "unverified-source-field" }
quests[11450] = { id = 11450, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuerübung", description = "Die Wachen haben ein Übungslager zum Feuerlöschen außerhalb der Stadt aufgebaut. Wir können nicht zulassen, dass der kopflose Reiter alles zunichtemacht, was wir in harter Arbeit wieder aufgebaut haben – also erfüllt Eure Pflicht und übt Euch im Feuerlöschen!\n\nVerlasst die Stadt durch das südliche Tor in Richtung der Kreuzung. Dort werdet Ihr das Übungslager finden.", sourceObjective = "Löscht 5 Feuer mit Wassereimern und sprecht anschließend mit der maskierten Waisenmatrone beim Falkenplatz.", completion = "Gut gemacht, {name}! Kinder, seht Euch diesen Helden gut an. Nehmt Euch ein Beispiel an ihm.", sourceObjectiveStatus = "unverified-source-field" }
quests[11451] = { id = 11451, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alicias Gedicht", description = "Hi! Ich habe für meine Freundin Caylee ein Gedicht verfasst. Sie verbringt Ihre Zeit gerne bei den Aldor in Shattrath. Ihr wisst schon, in der Scherbenwelt!\n\nWärt Ihr so freundlich und würdet ihr das Gedicht bringen? Meine Mutter sagt, ich sei noch zu jung, um selbst nach Shattrath zu reisen!", sourceObjective = "Man hat Euch gebeten, Alicias Gedicht zu Caylee Dak in Shattrath in der Scherbenwelt zu bringen.", progress = "Oh, ein Gedicht?", completion = "Was für ein anrührendes Gedicht. Habt vielen Dank!", sourceObjectiveStatus = "unverified-source-field" }
quests[11452] = { id = 11452, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der schlummernde König", description = "Ein Bündel Pergament fällt aus der regungslosen Hand des Oberanführers. Auf ihm könnt Ihr die Umrisse der Rituale erkennen, die in den Katakomben unter Euch vonstattengehen.\n\nEs scheint jedoch, als hätte die Königin der Vrykul Angerboda Schwierigkeiten, König Ymiron zu erwecken. Das Ritual findet auf der Terrasse des Winters, einer großen Kammer am nördlichen Ende von Gjalerbron, statt.\n\nWenn Ihr Euch beeilt, könnt Ihr sie vielleicht aufhalten, bevor es zu spät ist.", sourceObjective = "Besiegt Königin Angerboda und haltet das Ritual, mit dem König Ymiron beschwört werden soll, auf. Kehrt nach Westwacht zurück, falls Euch dies gelingen sollte, und setzt Hauptmann Adams über Euren Erfolg in Kenntnis.", completion = "Ich bin mir nicht sicher, aber der eine Teil hört sich gar nicht gut an! Dass sich der Lichkönig mit Ymiron davonmacht, kann nur Schwierigkeiten bedeuten. Bedauerlich nur, dass Ihr nicht imstande wart, ihn gemeinsam mit seiner Königin zu töten.\n\nNichtsdestotrotz, Ihr habt ihnen einen großen Strich durch die Rechnung gemacht und uns die nötige Zeit verschafft.\n\nUnd wer weiß, so viel wie Ihr herumkommt, ist es gut möglich, dass Euch König Ymiron noch einmal über den Weg laufen wird. Ich bin mir sicher, dass es ihm bei Eurer nächsten Begegnung nicht so gut ergehen wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[11453] = { id = 11453, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der schlummernde König", description = "Ein Bündel Pergament fällt aus der regungslosen Hand des Oberanführers. Auf ihm könnt Ihr die Umrisse der Rituale erkennen, die in den Katakomben unter Euch vonstattengehen.\n\nEs scheint jedoch, als hätte die Königin der Vrykul Angerboda Schwierigkeiten, König Ymiron zu erwecken. Das Ritual findet auf der Terrasse des Winters, einer großen Kammer am nördlichen Ende von Gjalerbron, statt.\n\nWenn Ihr Euch beeilt, könnt Ihr sie vielleicht aufhalten, bevor es zu spät ist.", sourceObjective = "Besiegt Königin Angerboda und haltet das Ritual, mit dem König Ymiron beschwört werden soll, auf. Kehrt zum Lager der Winterhufe zurück, falls Euch dies gelingen sollte, und berichtet Häuptling Aschtotem über Euren Erfolg.", completion = "Ich bin mir nicht sicher, aber der eine Teil hört sich gar nicht gut an! Dass sich der Lichkönig mit Ymiron davonmacht, kann nur Schwierigkeiten bedeuten. Bedauerlich nur, dass Ihr nicht imstande wart, ihn gemeinsam mit seiner Königin zu töten.\n\nNichtsdestotrotz, Ihr habt ihnen einen großen Strich durch die Rechnung gemacht und uns die nötige Zeit verschafft.\n\nUnd wer weiß, so viel wie Ihr herumkommt, ist es gut möglich, dass Euch König Ymiron noch einmal über den Weg laufen wird. Ich bin mir sicher, dass es ihm bei Eurer nächsten Begegnung nicht so gut ergehen wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[11454] = { id = 11454, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Findet die Saboteure", description = "Die Angreifer der Dunkeleisenzwerge scheinen diesen Papierfetzen versehentlich zurückgelassen zu haben.\n\nObwohl die Pläne in einem verfremdeten zwergischen Dialekt verfasst worden sind, ist die Unterschrift \"Coren Düsterbräu\" eindeutig genug, genauso wie die Erwähnung der Taverne 'Zum Grimmigen Säufer', tief in den Schwarzfelstiefen. Ihr solltet den Überfällen ein Ende bereiten und den Organisator der Überfälle aufsuchen.", sourceObjective = "Sucht nach Coren Düsterbräu im Grimmigen Säufer in den Schwarzfelstiefen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11455] = { id = 11455, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Duft des Goldes", description = "Wir Piraten sind zwar für allerhand Dinge bekannt, doch Hygiene gehört nicht dazu. Auf den meisten Piratenschiffen befinden sich fünf oder sechs Mal so viele Ratten wie Leute.\n\nFührt man sich das vor Augen, ist es kein Wunder, dass gleich nachdem wir hierher gezogen sind, die Bären auf dieser Insel an Tollwut erkrankten. Lange Rede, kurzer Sinn: Der Boss will sie alle tot sehen.\n\nZufälligerweise hab' ich ein Rezept für ein Bärenmoschusparfüm, das unter Sturmwinds Edelleuten beliebt ist. Wir töten die Bären und verkaufen den Moschus: Das ist DIE Geschäftsmöglichkeit für uns. Was meint Ihr dazu?", sourceObjective = "Der hübsche Terry im Halunkeneck im Heulenden Fjord möchte, dass Ihr 4 Einheiten Bärenmoschus von den tollwütigen Braunbären in der Gegend besorgt.", progress = "Habt Ihr mir den Bärenmoschus gebracht, Kumpel?", completion = "Ausgezeichnete Arbeit! Es mag vielleicht nicht ganz so waghalsig sein wie das Beutemachen auf hoher See, doch ich soll verdammt sein, mir diese Gelegenheit entgehen zu lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11456] = { id = 11456, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Überlebenden zu essen geben", description = "In Sachen Nahrung sind wir Tuskarr größtenteils auf den Fischfang angewiesen. In Zeiten großer Not werden wir jedoch gelegentlich auch auf Landtiere Jagd machen.\n\nDas in der Nähe gelegene Iskaal wurde erst kürzlich von Piraten angegriffen und es kommen ständig neue Überlebende aus dem Dorf zu uns herüber.\n\nWir haben diese Woche keinen großen Fang gemacht - es gibt jedoch genug fleischbepackte Schaufelhauer auf der Insel.\n\nHelft meinem Volk bei der Jagd auf diese großen Biester und bringt uns deren Fleisch.", sourceObjective = "Urahn Atuik in Kamagua im Heulenden Fjord möchte, dass Ihr zur Insel der Speere geht und ihm 6 Stück Fleisch eines Inselschaufelhauers beschafft.", progress = "Habt Ihr das benötigte Fleisch bekommen können?", completion = "Ich danke Euch, {name}. Mein Volk erlebt Zeiten großer Not.", sourceObjectiveStatus = "unverified-source-field" }
quests[11457] = { id = 11457, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kamagua bewaffnen", description = "Issliruk, der Geist des Krieges, wird von meinem Volk als silberner Adler dargestellt. Unsere Geschichten über ihn berichten davon, wie er gegen einhundert Worgs kämpfte, um seine Jungen zu beschützen.\n\nAuch für uns ist nun die Zeit gekommen, dem Feind im Kampfe zu begegnen und unsere Brüder zu beschützen. Die Hörner der Frostflügelschimären, die sich in den verschneiten Teilen der Insel eingenistet haben, sind scharf und können mühelos zu Speerspitzen weiterverarbeitet werden. Bringt mir die besten Hörner, die Ihr finden könnt.", sourceObjective = "Urahn Atuik möchte, dass Ihr ihm 3 Schimärenhörner beschafft.", progress = "Schön, Euch wiederzusehen, {race}.", completion = "Ihr erweist Euch weiterhin als wertvoller Verbündeter, {name}. Wir werden nicht vergessen, was Ihr für uns getan habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[11458] = { id = 11458, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rache für Iskaal", description = "Das Totem von Issliruk ist bereit, {name} - wofür ich Euch danken möchte. Fürs Erste müssen wir unsere friedlichen Sitten ablegen und einen Schlag gegen jene ausführen, die sich auf unser Land und unsere Sippe gestürzt haben.\n\nDie freibeuterischen Sklavenhändler, die für den Überfall auf Iskaal verantwortlich sind, haben ihren Verstand verloren und all ihre Gefangenen abgeschlachtet. Geht in Richtung Osten nach Iskaal und erledigt, was erledigt werden muss. Nehmt dieses Horn und ruft nach meinen Brüdern, solltet Ihr Unterstützung benötigen.", sourceObjective = "Urahn Atuik möchte, dass Ihr nach Iskaal geht und 8 Sklavenhändler des Nordmeeres niederstreckt. Macht von dem Horn von Kamagua Gebrauch, solltet Ihr Unterstützung benötigen.", completion = "Ihr seid ein großartiger Verbündeter, {name}. Mein Volk steht für immer in Eurer Schuld.", sourceObjectiveStatus = "unverified-source-field" }
quests[11459] = { id = 11459, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeh'gehn sachd", description = "Na lucks mal so än, Mann. Bis' du schaäf drouf, unsr'oins unnä di Floss'n zu graifn un' de olle Mackreilä ans Däch zu spül'n, di moi Crew sai Gut begrapscht hät?\n\nDu wiäst mia ne Kröide aus'm Wassä zieh'n müssn, Kamerad. Jo, un' dänn wüäd mainerainer dia zaichn, wer de Radde is, Mann. Nei, nei, de Kröide wiäd's dia zaichn. Du wiäst's woul mit di eich'nen Glupschä säin müss'n.\n\nSchaff ouch mol'n richdich's Mässä rübbä, baim Klabaudamann. Nu lous, Freundschen.", sourceObjective = "Kehrt zum hübschen Terry zurück, um herauszufinden, was Zeh'gehn von Euch will.", completion = "Ihr habt kein Wort von dem verstanden, was Zeh'gehn gesagt hat? Tja, das war klar.\n\nDann lasst uns doch mal sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11460] = { id = 11460, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vertrauen will verdient sein", description = "Der erste und wichtigste Aspekt der Falknerei ist die Bindung zwischen <dem Falkner/der Falknerin> und <seinem/ihrem> Vogel. Doch Vertrauen will <vom Herren/von der Herrin> verdient werden!\n\n<Hidalgo deutet auf die Falken im Käfig zu seinen Füßen.>\n\nUm ihr Vertrauen zu gewinnen, werdet Ihr zuerst ihre Bäuche füllen müssen.\n\nAuf dem Speiseplan der Fjordfelsenfalken, wie man diese Vögel nennt, befinden sich hauptsächlich Larven. Diese Insekten nisten unter losen Steinen, die im gesamten Fjord verstreut liegen. Findet eine Larve, kehrt hierher zurück und verfüttert sie an die Falken im Käfig.", sourceObjective = "Hidalgo im Außenposten der Forscherliga im Heulenden Fjord möchte, dass Ihr nach einer Fjordlarve sucht und sie an einen der Falken im Käfig zu seinen Füßen verfüttert.", progress = "Das ist eine wichtige Übung, {name}. Wenn Ihr ein Falkner werden wollt, müsst Ihr lernen, wie man einen Vogel ernährt.", completion = "Gut, {name}. Wie ich sehe, seid Ihr schon im Begriff, Freunde zu werden - er hat Euch als Herr akzeptiert.", sourceObjectiveStatus = "unverified-source-field" }
quests[11464] = { id = 11464, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spielschulden", description = "Ich habe gehört, Ihr habt für Terry ein paar Sachen geregelt. Ich habe darauf gehofft, dass hier mal jemand Verlässliches auftauchen würde.\n\nWisst Ihr, Piraten lieben das Glücksspiel. Jedoch bezahlen sie nicht gern ihre Spielschulden.\n\nWenn Ihr daran interessiert seid, für mich ein paar Münzen einzukassieren, wär' ich gewillt, Euch einen Anteil abzugeben.\n\nArbeiten wir Euch mit etwas Einfachem ein. \"Silbermond\" Harry ist ein kleiner Exzentriker, bewahrt in seinem Zelt allerlei teuren Blutelfenschnickschnack auf - aber wenn ich ihn treffe, tut er immer so, als wäre er pleite. Holt mein Gold.", sourceObjective = "Taruk im Halunkeneck möchte, dass Ihr die Schulden von \"Silbermond\" Harry eintreibt.", progress = "Ihr seid zurück. Habt Ihr, was mir gehört?", completion = "Eine gut gemachte Arbeit. Hier ist Euer Anteil, {name}. Wo der herkommt, gibt es noch mehr.\n\nAuf dieser Insel gibt es keinen Mangel an herumgammelnden Piraten.", sourceObjectiveStatus = "unverified-source-field" }
quests[11465] = { id = 11465, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die geplünderte Karawane", description = "Ich führte eine Karawane von Valgarde hierher, doch sie wurde von Drachenschindern angegriffen. Ich bin der einzige Überlebende dieses Hinterhalts. Zu allem Unglück habe ich es nicht geschafft, die Ladung Fjordtruthahn mit mir zu nehmen. Das ist die perfekte Gelegenheit für Euch, gemeinsam mit Eurem Falken den Sprung ins kalte Wasser zu wagen.\n\n<Hidalgo reicht Euch einen Käfig.>\n\nNehmt diesen Falkenkäfig und begebt Euch gen Westen die Straße entlang, die aus diesem Lager herausführt. Fangt mithilfe des Falkens die freilaufenden Truthähne ein und kehrt anschließend hierher zurück, sobald Ihr genug habt.\n\nVergesst nicht, die Falken zu füttern!", sourceObjective = "Hidalgo im Außenposten der Forscherliga im Heulenden Fjord möchte, dass Ihr mithilfe des dressierten Steinfalkens 5 Fjordtruthähne einfangt.\n\nKehrt zu Hidalgo zurück, sobald Ihr Eure Aufgabe erfüllt habt, und bringt den Käfig mit.", progress = "Euer Falke muss ständig gefüttert werden, sonst wird er die Jagdbeute, die er für Euch fangen soll, auffressen.", completion = "Die Dreckskerle sind gewieft - und geduldig! Wir dürfen unseren Feind nicht länger unterschätzen. Diese Vrykul sind tödliche Jäger!\n\nTrotzdem: Mission abgeschlossen. Vielleicht ist die Zeit reif für Euch, auf etwas Jagd zu machen, das schwieriger zu fangen ist, als ein fetter Truthahn, hm?", sourceObjectiveStatus = "unverified-source-field" }
quests[11466] = { id = 11466, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jack hebt gern' mal einen", description = "Unser nächster Kunde, Jack Adams, wird nicht so leicht zu besiegen sein wie Harry. Er verbringt den ganzen Tag damit, gemeinsam mit seinen Freunden, die allesamt harte Piratenjungs sind, einen zu heben. Lasst uns diesmal keine Gewalt anwenden - könnte sonst schlimm ausgehen.\n\nVersucht, seine Trinkgewohnheiten zu Eurem Vorteil zu nutzen - denn ab 'ner bestimmten Menge Alkohol kippt jeder um.\n\nVielleicht könnte ja eine der Schankmaiden behilflich sein. Sobald er weggetreten ist, könntet Ihr ja Eure Hand in seine Tasche gleiten lassen und an das herankommen, was eigentlich mir gehört.", sourceObjective = "Taruk im Halunkeneck im Heulenden Fjord möchte, dass Ihr Jack Adams' Schulden eintreibt.", progress = "Habt Ihr bekommen können, was mir gehört, {name}?", completion = "Ich bin beeindruckt, {name}. Und ich gehör' nicht gerade zu der Sorte, die sich leicht beeindrucken lässt.", sourceObjectiveStatus = "unverified-source-field" }
quests[11467] = { id = 11467, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Des toten Mannes Schulden", description = "Ihr habt vielleicht vom Schwarzen Konrad gehört, er ist ein berühmter Pirat in dieser Gegend.\n\nEr hat sehr gern auf meine Kämpfe gewettet. Er hat allerdings auch sehr gern nicht gezahlt.\n\nIch würde mein Geld gern haben, aber das Problem ist... er ist tot.\n\nIch war schon drauf und dran, die ganze Sache abzuschreiben, als ich das hier gefunden habe...\n\n<Taruk faltet eine Karte von der Insel der Speere auf, das nordöstliche Plateau ist mit einem roten X markiert.>\n\nEr hat seinen Schatz im Land der Tuskarr versteckt. Ich möchte, dass Ihr ihn holt. Ich will verdammt sein, wenn ich diesen Brackschlürfer ohne zu bezahlen davonkommen lasse.", sourceObjective = "Taruk im Halunkeneck will, dass Ihr auf dem Plateau am nordöstlichen Ende der Insel der Speere gleich nördlich von Iskaal auf die Suche nach dem Schatz des Schwarzen Konrad geht.", progress = "Habt Ihr den Schatz gefunden, {name}?", completion = "Ich werde das Gold nehmen. Es ist, was Konrad mir geschuldet hat. Den Rest könnt Ihr behalten.\n\nWenn Ihr mal eine Festanstellung braucht, bin ich mir sicher, ich könnte da etwas arrangieren. Möget Ihr in der Zwischenzeit stets Wind in den Segeln haben, mein Freund.", sourceObjectiveStatus = "unverified-source-field" }
quests[11468] = { id = 11468, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Falke gegen Habicht", description = "Spürt Ihr die Nähe, {name}? Ihr fühlt sicherlich bereits, wie sich eine echte Bande zwischen Euch und Eurem Falken entwickelt. Würdet Ihr mir glauben, wenn ich Euch sage, dass es Zeit ist, durch die Augen Eures Vogels zu sehen? Ja, das ist der Meistergrad der Falknerei.\n\nDoch zuerst müsst Ihr mehr jagen! Der Vogel muss seine Reflexe verbessern und beschleunigen. Lasst es ihn mit einem anspruchsvolleren Gegner aufnehmen! Die Fjordhabichte der Region haben die Baumkronen über uns zu ihrer Heimat gemacht. Sie sind Euer nächstes Ziel!", sourceObjective = "Hidalgo am Außenposten der Forscherliga im Heulenden Fjord möchte, dass Ihr Euren dressierten Steinfalken nutzt, um 10 Fjordhabichte zu erbeuten.\n\nKehrt mit dem Käfig zu Hidalgo zurück, wenn Ihr die Aufgabe Abgeschlossen habt.", progress = "Euer Falke muss stetig gefüttert werden, sonst wird er auch die Beute fressen, die er lediglich töten soll.", completion = "Ja, die Habichte weisen ein starkes territoriales Verhalten auf und fliegen oft im Schwarm. Ich schätze, das hätte ich Euch auch erzählen können, bevor ich Euch rausgeschickt habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[11469] = { id = 11469, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schrubbseife", description = "Jo, ich muss das Deck blitzeblank geschrubbt haben, bevor der verrückte Jonah wiederkommt. Un' ich werd das nicht auf meinen Knien machen!\n\nProblem: Wir ham keine Seife mehr. Das is' aber mehr Euer Problem als meins. Ihr seid <der Neue/die Neue> un' ich hab 'nen Spezialauftrag für Euch.\n\nOben an der Nordwestküste der Insel gibt's nen ganzen Haufen Seelöwen. Auf den Eisschollen in der Nähe findet Ihr den Alphabullen, den fetten Roy. Ihr bringt mir seinen Tran und ich zauber die beste Seife, die Ihr je geseh'n habt!", sourceObjective = "Lukchen Frostbug will, dass Ihr Tran vom fetten Roy besorgt, als Hauptbestandteil ihrer magischen Schrubbseife. Kehrt zu ihr auf das östliche Piratenschiff beim Halunkeneck zurück, wenn Ihr ihn habt.", progress = "Wo is' der Tran? Un' versucht nich' mir zu sagen, dass er keinen hat.\n\nDer fette Roy is' so verdammt fett, is'n Wunder, dass er überhaupt noch rumflanier'n kann!", completion = "Iiäh, das is' mal 'n Gestank!\n\nMacht schon, legt ihn dort hin. Ich wirk' meinen Zauber und dann wird mit Sicherheit Schrubbseife draus!", sourceObjectiveStatus = "unverified-source-field" }
quests[11470] = { id = 11470, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unter dem Vogelvieh gibt es keine Ehre", description = "Ihr seid definitiv für den nächsten Schritt in der Falknerei bereit, {name}.\n\nNehmt Euren dressierten Falken und geht zum Vrykulfalkennest in der Nähe des Aufzugs am Steinwall östlich von hier. Von dort aus werdet Ihr Euren Falken aussenden, um die Eier des Habichts zu sammeln. Ihre Nistplätze liegen in den abgelegenen Bereichen der Klippen um das Nest herum. Findet diese Nester und ergattert mithilfe Eures Falkens die Eier!\n\nNehmt Euch jedoch vor den Fjordhabichtmatriarchinnen in Acht, {name}. Merkt Euch, dass Ihr mithilfe der Flucht- und Gleitfähigkeiten Eures Falkens Angriffen entgehen könnt.", sourceObjective = "Hidalgo im Außenposten der Forscherliga im Heulenden Fjord möchte, dass Ihr mithilfe Eures dressierten Steinfalkens 8 Eier eines Fjordhabichts sammelt.\n\nKehrt zu Hidalgo zurück, sobald Ihr Eure Aufgabe erfüllt habt, und nehmt den Käfig mit.", progress = "Ihr habt Euren Vogel jetzt unter Kontrolle, {name}. Zeigt Eurem Falken, wohin er fliegen soll, und bringt mir diese Eier.", completion = "Bravo, {name}! Bravo! Die Bande zwischen Euch und Eurem Falken sind stark! Vielleicht könnt Ihr in absehbarer Zukunft auch ein paar Aufklärungsmissionen in Vrykulgebiet unternehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11471] = { id = 11471, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jetzt geht's lo-os", description = "Ich weiß, weshalb du hier bist, {name}. Du sollst unseren Anführer Jonah Sterling töten.\n\nIch würde dir in dieser Angelegenheit gerne meine Hilfe anbieten, denn Jonahs Führungsstil bringt unsere Mission in Gefahr.\n\nGleichzeitig die Flotten der Horde und Allianz anzugreifen: purer Selbstmord. Die Tuskarr in die Sklaverei verkaufen zu wollen, obwohl sie schon nach ein paar Tagen außerhalb dieses Klimas sterben: katastrophal.\n\nJonahs Unterschlupf befindet sich in einer Höhle westlich von hier. Bringt mir sein Handfernrohr als Beweis und meine erste Handlung als neue Anführerin wird es sein, alle Feindseligkeiten gegen unsere Verbündeten einzustellen.", sourceObjective = "Annie Bonn im Halunkeneck möchte, dass Ihr Jonah Sterlings Handfernrohr zu ihr bringt.", progress = "Tja, {name}. Hast du Jonahs Handfernrohr bekommen können?\n\nDein Wort alleine genügt mir nicht, verstehst du? Schließlich bin ich eine Piratin.", completion = "Jonah Sterlings Tage sind endlich gezählt! Er hätte niemals gedacht, dass es diese \"Magd\" mal zu was bringen würde.\n\nIch werde die Zeit, in der sich die Neuigkeiten über Jonahs Tod unter den Piraten verbreiten, dazu nutzen, meine Führung zu festigen. Meine Crew wird deinen Verbündeten keine Probleme mehr bereiten, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[11472] = { id = 11472, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Weg zu seinem Herzen...", description = "Die Nordmeerpiraten haben den fetten Roy, den Alphabullen der Seelöwen dieser Insel, abgeschlachtet. Dann haben sie aus ihm Seife gemacht, um die Decks ihrer Schiffe sauber zu schrubben!\n\n<Anuniaq seufzt.>\n\nJetzt werden sich die Seelöwen nicht paaren. Helft mir, ihre Zahl aufrechtzuerhalten.\n\nDie Riffbullen halten sich südöstlich von hier an der Zwillingsküste auf. Sie mögen ganz besonders die schmackhaften Rifffische, die am östlichen und westlichen Ufer zu finden sind.\n\nNehmt dieses Netz hier und sammelt genug Fische, mindestens ein Dutzend - vielleicht mehr -, um einen Bullen durch die Meerenge zu einer Riffkuh zu locken.", sourceObjective = "Werft einem Riffbullen schmackhafte Rifffische zu, um ihn zu einer Riffkuh zu führen. Habt Ihr den Zweien verholfen, wahre Liebe zu finden, dann kehrt zu Anuniaq in Kamagua zurück.", completion = "Das sind gute Neuigkeiten! Jetzt werden mehr Bullen durch die Meerenge schwimmen, um sich mit den Kühen zu paaren. Schon bald werden wir viele Jungtiere auf den Inseln haben.\n\nDank Euch, {race}. Was auch immer Ihr in der Vergangenheit getan haben mögt, wisst, dass Ihr der Zukunft von Kamagua einen Dienst erwiesen habt!\n\nWir müssen so weitermachen, wenn wir dafür sorgen wollen, dass sich ihre Population erholt. Kommt morgen bitte wieder, damit wir ein weiteres Paar zusammenbringen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[11473] = { id = 11473, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Verräter unter uns", description = "Unser Kapitänleutnant, Annie Bonn, tut in letzter Zeit ziemlich paranoid. Sie scheint sich sicher, dass wir einen Spion unter uns haben, könnt'er das glauben?\n\nNa jedenfalls haben wir hier 'ne narrensichere Methode, Ratten zu jagen. Wisst Ihr, der gute Zeh'gehn dort drüben ist ein echter Hexendoktor. Hat einen Stammbaum bis nach Zul... Dingens oder so.\n\nGeht und sagt ihm, dass wir seine Wahrsagerkünste brauchen. Ich muss Euch warnen, {name}, nur ein oder zwei von uns können auch nur irgendetwas von dem verstehen, was Zeh'gehn sagt.", sourceObjective = "Sprecht mit Zeh'gehn im Halunkeneck.", completion = "Hia drüban, Maan. Du komman, um mich zu seh'n?", sourceObjectiveStatus = "unverified-source-field" }
quests[11474] = { id = 11474, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ärger am hohen Kliff", description = "Wie immer müssen meine Crew und ich die eigentliche Arbeit erledigen. Zum Glück ist McSorfs Team nicht umsonst gestorben. Die Glyphe, die sie geborgen haben, wird uns bei der Entschlüsselung der Funde, die wir hier gemacht haben, helfen - das heißt, wenn wir jemals wieder in ihre Nähe kommen! Diese verdammten Eisenzwerge sind überall wie Pilze aus dem Boden geschossen und versuchen nun die Ausgrabungsstätten zuzuschütten! Ist das zu fassen? Die Dreckskerle wollen unsere Funde unter einem Haufen Erde begraben!\n\nWie dem auch sei, sprecht mit Walt dort drüben. Er wird Euch einweisen.", sourceObjective = "Sprecht mit Walt.", completion = "Über die Hälfte unseres Teams ist tot oder wird vermisst, Kleiner. Das ist unsere letzte Stellung hier oben auf dem hohen Kliff. Diese verdammten Eisenzwerge haben uns aus Ivalds und Baelguns Ruine vertrieben. Ich hab' jedoch einen Plan auf Lager, mit dessen Hilfe wir dort wieder reinkommen, bevor sie all unsere tollen Sachen unter der Erde begraben und wir unsere gesamten Daten für immer verlieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[11475] = { id = 11475, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das nötige Werkzeug für den Job", description = "Ich hab' dieses deaktivierte Konstrukt schon seit Tagen untersucht, {name}. Denke, dass ich eine passable Kopie des Golems anfertigen kann, die genug Platz für einen Passagier haben wird. Dahinter steckt die Idee, dass sich damit die Eisenzwerge täuschen lassen und wir Zutritt zu Baelguns Ruine erhalten.\n\nNun, ohne Hammer und Schüreisen werde ich gar nichts machen können. Ich brauch' mein Werkzeug! Unglücklicherweise hab' ich es in Ivalds Ruine zurückgelassen, als die Eisenzwerge das erste Mal angriffen. Beschafft mir mein Werkzeug!\n\nIvalds Ruine befindet sich weit im Nordosten.", sourceObjective = "Walt im Außenposten der Forscherliga im Heulenden Fjord möchte, dass Ihr seine Bauwerkzeuge beschafft.", progress = "Schritt Nummer Eins: Walts Werkzeug besorgen.", completion = "Da ich mein Werkzeug nun wieder habe, kann die Arbeit beginnen. Das heißt, sobald ich ein paar Materialien habe. Die werdet Ihr mir nämlich als nächstes besorgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11476] = { id = 11476, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Frosch und ein Messer", description = "Einige der Piraten hier... wir haben unsere ganz eigener Art zu sprechen. Zeh'gehn hat... sehr viele spezielle Arten zu reden... alles zusammengemischt.\n\nSoweit ich es verstehe, will er einen Frosch und ein Messer.\n\n\"Silbermond\" Harry könnte ein Messer für lau haben. Frösche rennen hier überall durch den Ort, schnappt Euch einfach einen und bringt ihn zusammen mit dem Messer zu ihm.\n\nAlso, ich will nicht in den Schuhen von dem armen Viech stecken, wenn Ihr wisst, was ich mein'.", sourceObjective = "Besorgt Euch ein glänzendes Messer von \"Silbermond\" Harry und fangt einen Ganovenfrosch. Bringt dann beides zu Zeh'Gehn im Halunkeneck.", progress = "Dia hat da Frosch un' Schnitza bekom, Mann?", completion = "Gut Dank, Bruddah. Da Frosch is' echt krass!", sourceObjectiveStatus = "unverified-source-field" }
quests[11477] = { id = 11477, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht in meinem Element?", description = "Leiser, {race}, leiser. Die Finger der Eisenzwerge sind schnell am Abzug. Nun, lasst Euch nicht von den Geschehnissen dort unten in der Grube täuschen. Diese stählernen Monstrositäten sind nicht dabei, irgendwas auszugraben! Nein, <Herr Kamerad/Frau Kameradin> - ganz im Gegenteil: Sie schütten die Stätte zu! Aus irgendeinem verrückten Grund wollen sie verhindern, dass irgendjemand diesen Ort findet.\n\n\"Was muss das für ein Zwerg sein, der uralte Relikte und Ausgrabungsstätten unter der Erde begraben will\", frage ich Euch. Nun, das will ich Euch verraten: Es ist die Art von Zwerg, die man mit rücksichtsloser Hingabe um die Ecke bringt! Geht dorthin und schaltet sie aus!", sourceObjective = "Donny in Ivalds Ruine im Heulenden Fjord möchte, dass Ihr 10 Eisenrunenzerstörer, 5 Eisenrunenhilfsarbeiter und 2 Eisenrunenweise tötet.", progress = "Ihr werdet so viele töten müssen, bis Ihr Euren Teil erfüllt habt.", completion = "Gute Arbeit, {name}. Das wird ihre Vergrabungsaktion ein wenig verlangsamen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11478] = { id = 11478, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Außenposten dort drüben...", description = "Ich sehe, dass Ihr noch nicht im Außenposten der Forscherliga im Süden wart und meinen Bruder besucht habt. Wieso tut Ihr Donny nicht einen Gefallen und überbringt Stanwad diese Nachricht. Es wird ihn interessieren, darüber zu erfahren, was die Eisenzwerge hier oben treiben.\n\nWie ich bereits sagte: Setzt auf und begebt Euch in Richtung Süden. Kurz bevor Ihr Baelguns Ruine erreicht, werdet Ihr den Außenposten sehen.", sourceObjective = "Überbringt Donnys Brief an Stanwad im Außenposten der Forscherliga.", progress = "Nachrichten von Donny?", completion = "Tja, nichts, das wir nicht schon wüssten. Zumindest wissen wir jetzt, dass Donny noch immer am Leben ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[11479] = { id = 11479, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "\"Krähenbein\" Dan", description = "Kröide hat geplabbärt, Kamerad. \"Krähenbein\" Dan is' uff de Kuddä da druiben.\n\nAm bestän geis'du da rübbä un' souchst nach de Radde, Mann. Gei z'rück zum Terry, wenn de Kielhaulerai fäddich is'.", sourceObjective = "Konfrontiert \"Krähenbein\" Dan. Er befindet sich auf einem der Schiffe im Halunkeneck. Sprecht mit dem hübschen Terry, sobald diese Aufgabe erfüllt ist.", progress = "Ich kann's gar nicht fassen, dass es Dan war. Habt Ihr Euch schon drum gekümmert?", completion = "Das sind mal traurige Neuigkeiten. Dan war'n alter Freund von mir... UND hat mir Gold geschuldet. Egal, wenn er mit diesen Südmeerbastarden gemeinsame Sache gemacht hat, dann hat er bekommen, was er verdient.\n\nWas Euch betrifft, mein Freund... Würde mal sagen, dass Ihr auf dem Weg nach oben seid, und zwar buchstäblich.", sourceObjectiveStatus = "unverified-source-field" }
quests[11480] = { id = 11480, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nummer Zwei kennenlernen", description = "Es ist nicht unbeachtet geblieben, was für gute Arbeit Ihr bis jetzt für uns geleistet habt, {name}. Unsere Zweitkommandierende, die charmante Annie Bonn, ist überaus beeindruckt von dem, was Ihr bisher getan habt, und will Euch kennenlernen.", sourceObjective = "Sprecht mit Annie Bonn im Halunkeneck.", completion = "Aber, aber, aber... Wenn das nicht {name} ist. Ihr taucht hier im Halunkeneck auf, niemand hat von Euch gehört, außer irgend so ein Goblin, den dieser Schwachkopf Terry seinen Freund nennt.\n\nSagen wir einfach mal, dass ich ein wenig... skeptisch bin... was Eure Absichten hier angeht.", sourceObjectiveStatus = "unverified-source-field" }
quests[11481] = { id = 11481, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krise am Sonnenbrunnen", description = "Bei den Naaru, ich danke Euch, {race}, für Euer Bemühen.\n\nUnsere Arbeit hier ist jedoch noch lange nicht beendet, weswegen ich Euch darum bitten muss, eine entscheidende Mission auszuführen - eine Mission so wichtig wie alle, mit denen ich Euch jemals beauftragt habe.\n\nUnsere Streitkräfte sind weit verteilt. Und um das Ganze noch schlimmer zu machen, mussten wir ein Kontingent nach Azeroth abbestellen, das die Entwicklung der Dinge auf dem Sonnenbrunnenplateau untersuchen soll.\n\nIhr werdet dort gebraucht, {name}. Meldet Euch bei Larethor und richtet ihm aus, ich wünschte, wir könnten mehr Männer entbehren.", sourceObjective = "Adyen der Lichtwächter auf der Aldorhöhe in Shattrath hat Euch gebeten, zum Sonnenbrunnenplateau zu reisen und dort mit Larethor zu sprechen.", completion = "Noch ein Soldat aus Shattrath? Welch willkommener Anblick!\n\nWünschte es gäbe mehr wie Euch, aber wir müssen mit dem auskommen, was uns gegeben ist. Was auch immer dort draußen geschieht, es wird nicht darauf warten, dass wir vorbereitet sind.\n\nSeht Euch ein wenig um, {class}. Es gibt viel zu erledigen. Packt mit an und tut Euren Teil.\n\nOh, ich vergaß: Macht Euch nicht über die Anfänger... ähhm, Anhänger der Seher lustig. Sieht aus, als würden wir in dieser Sache am selben Strang ziehen...", sourceObjectiveStatus = "unverified-source-field" }
quests[11482] = { id = 11482, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pflicht ruft", description = "Hört mich an, {race}.\n\nDie Pflicht verlangt, dass Ihr Euch zurück nach Azeroth begebt. Ein jeder, der dazu im Stande ist zu kämpfen, soll sich umgehend auf dem Sonnenbrunnenplateau melden.\n\nIch fürchte, dass ich Euch keine weiteren Informationen geben kann als diese:\n\nFür diese Mission werdet Ihr Euch mit den Aldor zusammentun. Sprecht mit einem Draenei namens Larethor, sobald Ihr dort ankommt.\n\nAnscheinend fordert die Situation, dass wir unsere Differenzen beiseite legen und uns zusammenschließen.\n\nMacht Euch bereit. Das hier klingt ernst.", sourceObjective = "Dathris Sonnensturm auf der Sehertreppe in Shattrath besteht darauf, dass Ihr umgehend nach Azeroth reist und Euch bei Larethor am Sonnenbrunnen meldet.", completion = "Willkommen auf dem Sonnenbrunnenplateau, Anfänger der... Wie bitte? Oh - Anhänger der Seher, natürlich. Habe ich das nicht gesagt?\n\nNun, gut, kommen wir gleich zur Sache. Hinter diesen Mauern geht es ernsthaft zur Sache, und das ist für unsere beiden Völker von großem Interesse. Und da keiner von uns über genügend Streitkräfte verfügt, um die Sache alleine anzugehen, werden wir ZUSAMMENARBEITEN. Verstanden?\n\nNa dann fangen wir doch einmal an.", sourceObjectiveStatus = "unverified-source-field" }
quests[11483] = { id = 11483, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir können es nachbauen", description = "Werkzeug? - vorhanden. Materialien? - nicht vorhanden.\n\nWenn wir dieses Ding bauen wollen, dann werdet Ihr mir die Materialien besorgen müssen.\n\nEins nach dem anderen, {name}. Für das Skelett benötige ich ein großes Fass aus Niffelvar, ein paar Dunkeleisenblöcke aus Valgarde und ein Seil in Industriestärke aus Quälheim.\n\nDie Vrykulorte Niffelvar und Quälheim liegen nordwestlich von hier; Valgarde befindet sich in der Dolchbucht - was auch im Nordwesten liegt. Sprecht mit McGoyver, um die Blöcke zu bekommen. Er wird Euch hierher zurückfliegen, wenn Ihr alles besorgt habt.", sourceObjective = "Walt im Außenposten der Forscherliga im Heulenden Fjord möchte, dass Ihr ihm ein großes Fass, ein Seil in Industriestärke und Dunkeleisenblöcke bringt.", progress = "Habt Ihr die Materialien für das Skelett dabei?", completion = "Ausgezeichnet. In Kombination mit der Haut wird daraus ein makelloser Klon des Konstrukts, das von den Eisenzwergen verwendet wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[11484] = { id = 11484, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir haben die Technik", description = "Für eine Maschine wie diese ist der Unterbau zwar wichtig, doch wir dürfen die Wichtigkeit der Verkleidung des Konstrukts nicht unterbewerten. Wenn wir die Eisenzwerge zum Narren halten wollen, dann muss das Abbild perfekt sein!\n\nIch kann dafür sorgen.\n\nBringt mir einen makellosen Schaufelhauerbalg von den Schaufelhauern dieser Region und ein Stück Rippenstahl von den Vrykul in Niffelvar oder Quälheim gen Nordwesten.", sourceObjective = "Walt im Außenposten der Forscherliga im Heulenden Fjord möchte, dass Ihr ihm einen makellosen Schaufelhauerbalg und ein Stück Rippenstahl bringt.", progress = "Wir werden im Nu weiter nach unseren Relikten suchen können!", completion = "Ich werde dafür sorgen, dass das Konstrukt einsatzbereit ist, sobald der Unterbau steht.", sourceObjectiveStatus = "unverified-source-field" }
quests[11485] = { id = 11485, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eisenrunenkonstrukte und du: Raketensprünge", description = "Nun gut, {name} - die Zeit ist gekommen, dass Ihr in dieses Ding klettert und den Umgang mit seinen grundlegenden Fähigkeiten lernt. Steigt auf die Werkbank, wenn Ihr bereit seid, und ich werde Euch ins Innere des Konstrukts setzen.\n\nEure erste Lektion dreht sich um die Bedienung des Transportsystems des Konstrukts. Ihr werdet bemerken, dass sich überall in der Ausgrabungsstätte spezielle Gravuren der Eisenzwerge befinden. Diese Runen werden von ihren Konstrukten dazu verwendet, sich aufzuladen und von einem Punkt zum nächsten zu fliegen. Versucht es einmal mit meiner Runengravur hier.", sourceObjective = "Walt im Außenposten der Forscherliga im Heulenden Fjord möchte, dass Ihr Euch ins Eisenrunenkonstrukt setzt und dessen Fähigkeit 'Raketensprung' bei Walts Eisenrunengravur ausführt.\n\nÜber das Begleiterfenster, könnt Ihr das Konstrukt freigeben, sobald Ihr die Aufgabe abgeschlossen habt.", progress = "Lasst Euch von diesen Schwarzmalern nichts gefallen!", completion = "Ihr seid schon fast bereit, mit diesem Kunstwerk ins Feld zu ziehen, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[11488] = { id = 11488, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Terrasse der Magister", description = "Willkommen am Sonnenbrunnen, {class}. Macht Euch mit der Umgebung vertraut und legt dort Hand an, wo Ihr nur könnt. Es gibt viel zu tun!\n\nIch? Ja, ich hätte da eine Kleinigkeit, die erledigt werden müsste, aber ich bin mir nicht sicher, ob Ihr der Aufgabe gewachsen wäret.\n\nWir hatten einen Kontaktmann auf der Terrasse der Magister im Einsatz, der uns diverse Informationen zukommen ließ. Er hat jedoch vor Kurzem versäumt, uns Bericht zu erstatten, weswegen ich mir zunehmend Sorgen mache.\n\nDie Terrasse befindet sich gleich im Osten, die Anhöhe hoch. Die Informationen, die er gesammelt hat, sind entscheidend für unsere Mission.\n\nDenkt Ihr, dass Ihr damit zurecht kommt, {race}?", sourceObjective = "Exarch Larethor beim Sammelpunkt der Zerschmetterten Sonne möchte, dass Ihr die Terrasse der Magister absucht und einen Blutelfenspion namens Tyrith findet.", completion = "...Kommt näher, {race}... Hört genau auf meine Worte...", sourceObjectiveStatus = "unverified-source-field" }
quests[11489] = { id = 11489, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eisenrunenkonstrukte und du: Daten sammeln", description = "Während Ihr das Konstrukt bedient, wird Eure wichtigste Aufgabe das Sammeln von Daten sein. Ich habe ein Eisenzwergrelikt in den Karren dort drüben gelegt - es geht um den schwebenden blitzerfüllten Kristall.\n\nSteigt auf die Werkbank und ich werde Euch wieder in das Konstrukt setzen. Führt die Datensammlungsfähigkeit des Konstrukts aus, sobald Ihr wieder hinterm Steuer sitzt, und sammelt die Testdaten auf.", sourceObjective = "Walt im Außenposten der Forscherliga im Heulenden Fjord möchte, dass Ihr Euch ins Eisenrunenkonstrukt setzt und die Fähigkeit 'Daten sammeln' in der Nähe des Eisenzwergrelikts ausführt.\n\nÜber das Begleiterfenster, könnt Ihr das Konstrukt freigeben, sobald Ihr die Aufgabe abgeschlossen habt.", progress = "Passt wie angegossen, oder?", completion = "Perfekt! Funktioniert einwandfrei!", sourceObjectiveStatus = "unverified-source-field" }
quests[11490] = { id = 11490, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Seher der Seher", description = "Geht zur Terrasse... benutzt die Kugel.\n\n<Tyrith ringt nach Luft.>\n\nBeeilt Euch... Ihr müsst sie aufhalten... bevor sie...\n\n<Tyrith stirbt.>", sourceObjective = "Tyrith möchte, dass Ihr die Kugel auf dem Balkon in der Terrasse der Magister benutzt.", completion = "Ich denke, dass es kein Zufall ist, dass sich unsere Wege heute kreuzen.\n\nIch meine zu erkennen, dass dies eine Fügung des Schicksals ist...", sourceObjectiveStatus = "unverified-source-field" }
quests[11491] = { id = 11491, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eisenrunenkonstrukte und du: Täuschung", description = "Man muss immer einen Notfallplan auf Lager haben, für den Fall, dass der Hauptplan fehlschlagen sollte! Das ist auch der Grund, weshalb ich das Konstrukt mit ein paar Antispionagesystemen ausgestattet habe.\n\nEs könnte sein, dass, sobald Ihr Euch in Baelguns Ausgrabungsstätte befindet, Euer toller, neuer Schlitten Verdacht erregt. Und genau dafür ist die Täuschungsfähigkeit da! Macht einfach bei jeder Konfrontation davon Gebrauch und Euch wird kein Leid zugefügt.\n\nVersucht es einmal an Lebronski und steigt auf seinen Teppich. Führt die Fähigkeit aus, sobald er Euch anschnauzt!\n\nSteigt auf die Werkbank, wenn Ihr bereit seid anzufangen.", sourceObjective = "Walt im Außenposten der Forscherliga im Heulenden Fjord möchte, dass Ihr Euch ins Eisenrunenkonstrukt setzt und die Fähigkeit 'Bluffen' auf Lebronski ausführt, nachdem Ihr über seinen Teppich gestiegen seid.\n\nÜber das Begleiterfenster, könnt Ihr das Konstrukt freigeben, sobald Ihr die Aufgabe abgeschlossen habt.", completion = "Ihr habt's ihm gezeigt! Nun ist es an der Zeit, Euch ins Feld ziehen zu lassen!\n\nHoffe, Ihr seid Euch der Sache sicher...", sourceObjectiveStatus = "unverified-source-field" }
quests[11492] = { id = 11492, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht totzukriegen", description = "Der Sonnenbrunnen heißt Euch willkommen, Sterbliche. Ihr trefft in der Tat zur rechten Zeit ein.\n\nWie Ihr mittlerweile wisst, arbeiten die Streitkräfte der Legion unermüdlich daran, die Kräfte des Sonnenbrunnens zu manipulieren, um so ihre eigenen unholden Machenschaften zu verwirklichen.\n\nKael'thas ist aus der Asche der Niederlage auferstanden und ist einmal mehr zu ihrem Anführer geworden. Findet ihn, Sterbliche. Noch einmal muss er aufgehalten werden.\n\nAndere Angelegenheiten von gleicher Dringlichkeit erfordern meine sofortige Aufmerksamkeit. Ich lege Kaels Schicksal in Eure Hände. Ihr dürft nicht versagen.\n\nMit etwas Glück werden wir uns wieder sprechen.", sourceObjective = "Kalecgos hat Euch damit beauftragt, Kael'thas in der Terrasse der Magister zu bezwingen. Ihr sollt Euch mit Kaels Kopf bei Larethor am Sammelpunkt der Zerschmetterten Sonne treffen.", progress = "Nun ja, {class}, ich muss gestehen, dass ich mir nicht sicher war, ob ich Euch jemals wiedersehen würde.\n\nWelch Kunde bringt Ihr mir?", completion = "<Larethor hört aufmerksam zu, als Ihr von Euren Heldentaten auf der Terrasse der Magister berichtet.>\n\nMan wird Tyrith vermissen. Er war ein guter Mann. Dank Euch war sein Tod nicht umsonst.\n\nIch habe Euch unterschätzt, {race}. Bitte, nehmt dies im Namen der Sonnenbrunnenoffensive - eine Gabe, die eines Helden, wie Ihr einer seid, würdig ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[11494] = { id = 11494, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blitzerfüllte Relikte", description = "Euer Konstrukt ist nun einsatzbereit. Alle Fähigkeiten wurden einer kurzen Prüfung unterzogen und ich habe die Maschine so programmiert, dass sie die Sprache der Titanen verstehen und sprechen kann.\n\nBegebt Euch mit dem Konstrukt zu Baelguns Ausgrabungsstätte genau südlich von hier, findet die dort überall verstreut liegenden blitzerfüllten Relikte und sammelt deren Daten. Erinnert Euch daran, jeglichen Eisenzwerg zu täuschen, der Verdacht an der Echtheit Eures Konstrukts hegt. Und vergesst nicht, per Raketensprung von Rune zu Rune zu springen und auf diese Weise mobiler zu sein!\n\nSteigt auf den Tisch, wenn Ihr bereit seid!", sourceObjective = "Walt im Außenposten der Forscherliga im Heulenden Fjord möchte, dass Ihr Euch ins Eisenrunenkonstrukt setzt und mit der Fähigkeit 'Daten sammeln' 15 Lesungen von Eisenrunendaten durchführt.\n\nÜber das Begleiterfenster, könnt Ihr das Konstrukt freigeben, sobald Ihr die Aufgabe abgeschlossen habt.", completion = "Und wieder einmal beweist Walt, dass er in der Tat der beste Zwerg ist! Was hältst du jetzt von meinem Konstrukt, Lebronski!\n\nIch danke Euch, {name}. Diese Daten werden sich zweifellos als unbezahlbar erweisen - wenn ich erst einmal herausbekommen habe, wie man sie aus dem Konstrukt herausbekommt.", sourceObjectiveStatus = "unverified-source-field" }
quests[11495] = { id = 11495, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der zarte Knall des Donners", description = "Die Höhle, die wir in Baelguns Ausgrabungsstätte freigelegt haben, war DER Ort, vor dem sich die meisten fernhielten... Kann nicht sagen, dass ich ihnen das vorwerfe. Der Schlund der Höhle spuckte krachenden Donner, {name}! Ohrenbetäubender Donnerknall war es!\n\nIch denke, dass gegen Ende ein jeder die Höhle aufgegeben hatte. Denjenigen, die sich hineinwagten, um den Ort zu erkunden, widerfuhr Schlimmstes - und meistens kamen sie nicht zurück.\n\nIch möchte, dass Ihr Euch diese Höhle einmal anseht, wenn Ihr in Baelguns Ausgrabungsstätte seid. Begebt Euch ins Innere, erkundet die Gegend um die Titanenstatue und meldet Euch dann mit den Funden wieder bei mir zurück.", sourceObjective = "Walt im Außenposten der Forscherliga im Heulenden Fjord möchte, dass Ihr Euch ins Eisenrunenkonstrukt setzt und die donnernde Höhle in Baelguns Ausgrabungsstätte erkundet.\n\nÜber das Begleiterfenster, könnt Ihr das Konstrukt freigeben, sobald Ihr die Aufgabe abgeschlossen habt.", completion = "Unglaublich! Was könnten diese Eisennervensägen im Schilde führen? Was machen sie auf den Sturmgipfeln? Und wer ist dieser Loken?! Ich werde die Informationen an unsere zentrale Operationsbasis in der Drachenöde weiterleiten, {name}. Auch werde ich sie wissen lassen, dass Ihr bei der Beschaffung besagter Infos außerordentlich wertvoll gewesen seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[11496] = { id = 11496, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Barrieren des Sanktums", description = "Zuerst müssen wir das Sanktum der Sonnenweiten einnehmen. Sobald wir es gesichert haben, werden wir in der Lage sein, seine Energien für die Öffnung eines Portals nach Shattrath zu nutzen.\n\nDas Sanktum quillt über von Getriebenen - frühere Blutelfen, die zu hirnlosen Schatten ihrer selbst verkümmert sind. Die Verteidigungsanlangen hätten dieses Eindringen normalerweise verhindert, aber die Getriebenen haben die Energiequellen der Schutzbarrieren gestohlen.\n\nStellt den Getriebenen nach und holt Euch die Manaüberreste, die sie bei sich tragen. Benutzt sie, um die Barrieren des Sanktums aufzuladen.", sourceObjective = "Hauptmann Theris Morgenheim beim Sammelpunkt der Zerschmetterten Sonne will, dass Ihr 4 Manaüberreste von getriebenen Unholden und getriebenen Verschlingern verschafft und sie benutzt, um eine der Kristallbarrieren aufzuladen, welche den Osten des Sanktums der Sonnenweiten umgeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[11497] = { id = 11497, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fliegen lernen", description = "Tja, mein Geschäft wird zwar auf die Dauer wohl eher darunter leiden, aber ich muss sagen, dass Ihr wie jemand ausseht, der sein eigenes Reittier fliegen möchte, anstatt von Ort zu Ort geflogen zu werden.\n\nIch kann das gut verstehen.\n\nIhr, mein Freund, müsst Euch zur Wildhammerfeste im Südwesten des Schattenmondtals begeben, und dort Ilsa Trubelbräu nach Flugstunden fragen. Die Ausbildung ist zwar nicht gerade billig, aber ich denke, dass es sich lohnen würde.", sourceObjective = "Sprecht mit Ilsa Trubelbräu in der Wildhammerfeste im Schattenmondtal.", completion = "Ach, Nutral hat Euch also hierher geschickt? Sehr gut... Erinnert mich daran, dass ich ihm einen Krug Bier zum Dank für all die Fluglehrlinge, die er zu mir schickt, zukommen lasse.\n\nWenn Ihr wissen wollt, wie man richtig fliegt, dann seid Ihr am richtigen Ort. Niemand fliegt besser als die Wildhammer und diejenigen, die von uns ausgebildet wurden. Für ein Entgelt, ein nicht zu kleines wohlgemerkt, lehre ich Euch die Kunst des Fliegens!\n\nUnd wenn Ihr fertig seid, dann vergesst nicht mit Brunn zu sprechen - er hat ein paar schöne Greifen zur Auswahl!", sourceObjectiveStatus = "unverified-source-field" }
quests[11498] = { id = 11498, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fliegen lernen", description = "Tja, mein Geschäft wird zwar auf die Dauer wohl eher darunter leiden, aber ich muss sagen, dass Ihr wie jemand ausseht, <der sein/die ihr> eigenes Reittier fliegen möchte, anstatt von Ort zu Ort geflogen zu werden.\n\nIch kann das gut verstehen.\n\nIhr, mein Freund, müsst Euch nach Schattenmond im Nordwesten des Schattenmondtals begeben, und dort Olrokk nach Flugstunden fragen. Die Ausbildung ist zwar nicht gerade billig, aber ich denke, dass es sich lohnen würde.", sourceObjective = "Sprecht mit Olrokk in Schattenmond im Schattenmondtal.", completion = "Blut und Donner, Nutral hat mir schon wieder einen Boden-Grunzer geschickt! Sehr gut... für einen Draenei.\n\n<Olrokk spuckt auf den Boden neben Euch.>\n\nWenn Ihr wissen wollt, wie man richtig fliegt, dann seid Ihr am richtigen Ort. Für einen großen Sack Gold bringe ich Euch genug bei, um nicht unehrenhaft in den Tod zu stürzen.\n\nUnd wenn Ihr fertig seid, dann vergesst nicht, Dama Wildmähne einen unserer Windreiter abzukaufen!", sourceObjectiveStatus = "unverified-source-field" }
quests[11499] = { id = 11499, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Der Siegelring von Prinz Kael'thas", description = "Heute werde ich das Unmögliche von Euch verlangen, {class}. Denn heute müsst Ihr mir den Siegelring von Kael'thas Sonnenwanderer, Lord der Blutelfen, beschaffen!\n\nEs ist wahr, die Gerüchte von seinem Tod waren aus der Luft gegriffen. Er ist nun einmal mehr erschienen - und diesmal auf der Terrasse der Magister auf der Insel von Quel'Danas. Was er dort macht, soll Euch jemand anderes berichten. Was ich weiß ist, dass es unzählig viele Sammler gibt, die an diesem Prinzenring interessiert sind. Und ich will ihnen diesen Ring beschaffen.\n\nOder, um genau zu sein will ich, dass Ihr ihn für mich beschafft.", sourceObjective = "Windhändler Zhareem hat Euch darum gebeten, ihm den Siegelring von Prinz Kael'thas zu beschaffen. Bringt diesen zu ihm ins Untere Viertel in Shattrath, um Eure Belohnung zu erhalten.\n\nDiese Aufgabe kann nur auf der Terrasse der Magister und nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "Die Terrasse der Magister muss in der Tat ein gefährlicher Ort sein - so nahe am Sonnenbrunnen, wie sie ist.\n\nIhr habt doch keine Bedenken, oder?", completion = "Der Blutelfenprinz ist also diesmal wirklich tot? Wie schade, ich dachte immer, dass er Klasse besäße. Wenn man sich denkt, dass jemand so erhaben für solch einen lumpigen Betrag zur Strecke gebracht werden konnte.\n\nAber es ist nun einmal so, wie man sagt: Geschäft ist Geschäft. Eure Belohnung ist verdient, Abenteuerer.\n\nKommt morgen wieder und ich werde einen anderen Auftrag für Euch haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[11500] = { id = 11500, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Schwestern der Qual", description = "Mah'duun vernahm eine Stimme, die ihm zuflüsterte, dass die Schwestern der Qual in die Hölle zurückgeschickt werden müssen, aus der sie kommen.\n\nMah'duun weiß, dass sich die Dämonen auf der Terrasse der Magister auf der Insel Quel'Danas befinden.\n\nIhr werdet Euch des Kopfgeldes wegen auf dieses Unterfangen einlassen oder auch nicht.", sourceObjective = "Netherpirscher Mah'duun möchte, dass Ihr 4 Schwestern der Qual erschlagt. Kehrt zu ihm in das Untere Viertel in Shattrath zurück, sobald Ihr sie getötet habt, um das Kopfgeld einzufordern.", completion = "Wer weiß, weshalb die dämonischen Schwestern den Tod finden müssen? Sorgt Ihr Euch darum?\n\nMah'duun denkt, dass Ihr Euch jedoch genug darum sorgt, um das Kopfgeld einzustreichen.\n\nKommt morgen wieder und die Winde werden wieder zu Mah'duun gesprochen haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[11501] = { id = 11501, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neues aus dem Osten", description = "Die Leute in Westwacht müssen erfahren, was hier vor sich geht, {name}. Ich möchte, dass Ihr persönlich Hauptmann Adams die Nachricht überbringt.\n\nSagt mir Bescheid, sobald Ihr bereit seid, und ich werde Euch die Maschine für einen letzten Flug bereitstellen. Sie wird Euch zwar nach Westwacht tragen, jedoch höchstwahrscheinlich dabei in die Luft fliegen.\n\nEs war mir ein Vergnügen...", sourceObjective = "Sprecht mit Hauptmann Adams in Westwacht.", completion = "Herrlich... Als ob es nicht schon genug wäre, dass uns die Geißel am - na Ihr wisst schon - klebt, nun müssen wir uns auch noch mit einem wütenden uralten Titanenkonstrukt herumschlagen!\n\nIch werde etwas Zeit brauchen, um das zu verarbeiten, {race}. In der Zwischenzeit werdet Ihr hier genug Arbeit finden, die getan werden muss.", sourceObjectiveStatus = "unverified-source-field" }
quests[11502] = { id = 11502, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zur Verteidigung von Halaa", description = "Wir sind kein kriegerisches Volk, {race}. Wenn der Krieg jedoch über unser Land kommt, rennen wir nicht vor ihm davon.\n\nDie Allianz und die Horde bekämpfen sich in der Stadt Halaa im Nordwesten. Wir wissen nicht, was die Blutelfen vorhaben, aber jeder Sieg, den die Horde erringt, wäre katastrophal. Die gemeinsame Geschichte unseres Volks mit den Orcs ist eine des Blutvergießens und des Verrats.\n\nGeht nun, streckt den Feind in Halaa nieder und Ihr werdet mit Münze, Ehre und Ruhm belohnt.", sourceObjective = "Besiegt 10 feindliche Spieler in Halaa und kehrt zu Lakoor in Telaar zurück.", completion = "Ich danke Euch, {name}. Eure Mühen werden nicht unbeachtet bleiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[11503] = { id = 11503, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feinde - alte und neue", description = "Unser uralter Feind, die Draenei, sind mit mächtigen Verbündeten wiedergekehrt. Sie führen Krieg in Halaa, südwestlich von hier.\n\nSie dürfen nicht siegreich sein, denn Garadar wäre gewiss als Nächstes dran.\n\nGeht und erschlagt diejenigen, die es wagen, unserem uralten Feind beizustehen.", sourceObjective = "Besiegt 10 feindliche Spieler in Halaa und kehrt zu Karrtog in Garadar zurück.", completion = "Ihr macht unserem Volk große Ehre. Ihr habt unseren Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[11504] = { id = 11504, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Toten stehen auf!", description = "Der Pfad östlich von uns gehört zu den wichtigsten Jagdgebieten der Tuskarr. Zumindest war das einmal so...\n\nWenn in jüngerer Zeit unsere Jäger nach Kamagua zurückkehren, behaupten sie, dass die Toten wiederauferstanden seien und nach Blut trachten! Aus diesem Grund sind mein Sohn und ich hierhergekommen. Urahn Atuik hat uns dazu aufgefordert, an der Steilküste nach einer Lösung des Problems zu suchen.\n\nWerdet Ihr uns in diesen Zeiten der Not zur Seite stehen? Ich suche nach Helden, die gewillt sind, den Gefahren des im Südosten gelegenen Schildhügels ins Auge zu blicken. Sucht in den entweihten Gräbern nach Hinweisen und kehrt mit den Funden zu mir zurück.", sourceObjective = "Orfus von Kamagua am Uralten Aufzug im Heulenden Fjord möchte, dass Ihr nach Fengirs Hinweis, Rodins Hinweis, Isuldofs Hinweis und Windans Hinweis sucht.", progress = "Die Tuskarr brauchen Eure Hilfe!", completion = "<Orfus' Barthaare sträuben sich.>\n\nPiraten... kennt ihre Verworfenheit keine Grenzen?\n\nWir müssen die gestohlenen Artefakte wiederbeschaffen und sie an diesen verwunschenen Ort zurückbringen, damit mein Volk einmal mehr erleben kann, was das Wort 'Frieden' bedeutet.", sourceObjectiveStatus = "unverified-source-field" }
quests[11505] = { id = 11505, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geister von Auchindoun", description = "Auchindouns Geister sind zwar nicht am Konflikt zwischen Allianz und Horde beteiligt, sollten wir sie jedoch auf unsere Seite ziehen können, hätten wir unseren Feinden gegenüber einen Vorteil in dieser Region.\n\nEin uralter Brauch führt die Lebenden auf den Pfad zu den Geistertürmen in der Knochenwüste, um den Geistern dort ihre Ehre zu erweisen - jedoch nur zu speziellen Tageszeiten. Wenn Ihr zu diesen Zeiten bei der Sicherung eines Turms helfen könnt, werdet Ihr dadurch die Geister auf unsere Seite ziehen.\n\nSollten wir Erfolg damit haben, die Gunst der Geister zu erlangen, werden sie uns eine Wohltat erweisen, die unsere Bestrebungen unterstützen wird.", sourceObjective = "Helft der Allianz, einen Turm in der Knochenwüste zu sichern.", progress = "Die Geister sind ruhelos, {name}. Habt Ihr Eure Aufgabe vollbracht?", completion = "Die Geister sind ihrer Ruhe einen Schritt näher. Es ist gut, ihre Gunst zu erlangen - besonders dann, wenn so nahe an ihrer Ruhestätte Krieg geführt wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[11506] = { id = 11506, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geister von Auchindoun", description = "Die Draenei mögen unsere Feinde sein, aber die Geister ihrer Urahnen in Auchindoun sind rastlos und niemandem untertan.\n\nEin uralter Brauch der Draenei verlangt von ihnen, dass sie zu verschiedenen Tageszeiten bei den Geistertürmen in der Knochenwüste ihren Urahnen Respekt zollen. Wenn Ihr zu diesen Zeiten bei der Sicherung eines Turms helfen könnt, werden dadurch die Geister in Auchindoun zur Ruhe kommen.\n\nDie Allianz wird versuchen, die Türme einzunehmen, um die Gunst der Geister zu erlangen. Wir müssen sicherstellen, dass die Horde hier erfolgreich ist.", sourceObjective = "Helft der Horde, einen Turm in der Knochenwüste zu sichern.", progress = "Die Geister von Auchindoun sind um uns. Werden sie uns eine Wohltat zuteilwerden lassen?", completion = "Die Geister sind einen Schritt näher daran, ihre Ruhe zu finden, und haben uns deswegen ihre Gunst verliehen.\n\nEs muss eine Demütigung für unseren Feind sein, dass sich seine eigenen Urahnen gegen ihn wenden - auch, wenn es nur vorübergehend ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[11507] = { id = 11507, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urahn Atuik und Kamagua", description = "<Orfus packt die Hinweise, die Ihr ihm mitgebracht habt, zu einem Bündel zusammen.>\n\nMein Volk befindet sich in einer verbitterten Auseinandersetzung mit den Freibeutern des Nordmeeres, von der es keinen Ausweg zu geben scheint. Wenn irgendein Tuskarr uns helfen und die Schandtaten der Piraten ungeschehen machen kann, dann ist das Urahn Atuik von Kamagua. Ihr müsst diese Hinweise schleunigst zu ihm bringen.\n\nUm nach Kamagua zu gelangen, müsst Ihr den Uralten Aufzug hinter mir nehmen. Lasst Euch von ihm direkt nach Kamagua befördern und sucht Urahn Atuik auf.", sourceObjective = "Orfus von Kamagua im Heulenden Fjord möchte, dass Ihr Orfus' Bündel nach Kamagua zu Urahn Atuik bringt.", progress = "Neuigkeiten von Orfus?", completion = "Orfus ist ein guter Tuskarr - einer unserer stärksten Krieger. Ich wusste, dass er uns nicht im Stich lassen würde.\n\nErlaubt mir, einen Blick auf das zu werfen, was Ihr mir mitgebracht habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[11508] = { id = 11508, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grezzix Achsenbruch", description = "Das Halunkeneck weit im Süden dient den Piraten als Hafen. Unglücklicherweise haben sie in ihrem Lager viele tödliche Verteidigungsanlagen aufgestellt.\n\nEs gibt jedoch jemanden, der uns vielleicht dabei helfen könnte, den Ort zu infiltrieren.\n\nVor Kurzem kam ein Piratensöldner namens Grezzix Achsenbruch in unser Dorf. Er ist auf der Suche nach Verpflegung und Unterkunft. Als Gegenleistung würde er uns Informationen über unsere Feinde geben und unseren Feinden Fehlinformationen über unsere Angriffspläne zukommen lassen. Sucht ihn auf, {name}. Er befindet sich auf seinem Schiff südwestlich von hier.", sourceObjective = "Sprecht mit Grezzix Achsenbruch.", completion = "Harr, Kamerad. Grezzix hat's nie gemocht, sich die Hände schmutzig zu machen! Grezzix findet das Piratenleben toll, solange er keine von den Arbeiten machen muss.\n\nIch hab' diese Artefakte gesehen. Sie sind der Grund dafür, wieso ich hier bin und nicht im Halunkeneck! Schlimme, schlimme Dinger sind das...\n\nHe, ist doch dein Leben, oder? Du willst ins Lager rein und Grezzix kann dir dabei helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11509] = { id = 11509, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sich einen Ruf machen", description = "Alle Freibeuter des Nordmeeres fürchten und respektieren Grezzix. Ich denke mal, dass sie meine besonderen Talente achten und mein tolles Schiff beneiden. Alles, was du machen musst, ist, hinter meinem Kabinenjungen Lou hinterher zu latschen, und du bist in... in wie Zinn, sozusagen. Piraten lieben Zinn.\n\nRed' einfach mit Lou, wenn du fertig bist, und er wird dich zum Halunkeneck bringen.\n\nOh ja, als Erstes wirst du wohl mit \"Silbermond\" Harry sprechen müssen. Er wird mehr über das Zeugs Bescheid wissen, das sie mitgehen haben lassen. Pass bloß auf, was du vor ihm sagst. Das is'n Verrückter... verrückt nach Blutelfen ist er.", sourceObjective = "Sprecht mit \"Silbermond\" Harry im Halunkeneck über die verschwundenen Vrykulartefakte.", completion = "<Harry blickt Euch an und zieht eine Augenbraue hoch.>\n\nSo, du bist also wie ich, hm? Ein wenig exzentrisch.\n\n<Harry flüstert Euch zu.>\n\nNiemand zieht sich hier so an.\n\nWas diese Artefakte angeht... Jeder, der mit den Dingern in Berührung kam, ist am Ende entweder tot gewesen, verschwunden oder gleich beides.\n\nWenn du noch immer mehr erfahren willst, kann ich dir weiterhelfen - wird dich aber was kosten.\n\n<Harry zwinkert Euch zu.>\n\nDu tust mir 'nen Gefallen und ich lass dich am Leben.", sourceObjectiveStatus = "unverified-source-field" }
quests[11510] = { id = 11510, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "\"Bodo von der Hermannsklause\"", description = "Das Erste, was Jonah Sterling gemacht hat, nachdem er durchgedreht ist, war, meinen hoch geschätzten Wahrsagerkristall der Sin'dorei zu nehmen und ihn an \"Bodo von der Hermannsklause\", den Orca und Fluch meines Lebens, zu verfüttern.\n\nNein, ich hab' dem verdammten Ding nicht den Namen gegeben. Ich weiß nur, dass er an den Schiffen im Halunkeneck vorbei in Richtung Südosten geschwommen ist. Bring diesen übergroßen Goldfisch um und reiß ihm meinen schönen Sin'doreikristall aus dem Bauch.\n\nMach das und wir kommen ins Geschäft.", sourceObjective = "\"Silbermond\" Harry im Halunkeneck möchte, dass Ihr den Orca \"Bodo von der Hermannsklause\" tötet und den Wahrsagerkristall der Sin'dorei wiederbeschafft.", progress = "Hast du dich verirrt?", completion = "<Harry nimmt Euch den Kristall ab und fängt an, ihn zu liebkosen.>\n\nOh, mein Schatz! Hat dir der große, böse Wal wehgetan? Alles wird gut. Ich werde dich nie wieder aus den Augen lassen!\n\n<Harry blickt zu Euch auf.>\n\nSo, wo waren wir stehen geblieben?", sourceObjectiveStatus = "unverified-source-field" }
quests[11511] = { id = 11511, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Stab des Sturmfurors", description = "Diese Artefakte sind verflucht und es wäre purer Wahnsinn, auf die Suche nach ihnen zu gehen, {race}. Ich weiß mit Sicherheit, dass ein jeder, der mit einem der Gegenstände in Berührung gekommen ist, entweder verrückt geworden ist oder getötet wurde.\n\nDieser Stab hier zum Beispiel: Das Letzte, was ich gehört habe, war, dass das Schiff, auf dem er sich befand, aufgegeben wurde und man es irgendwo im Osten der Insel der Speere, die sich nördlich von hier befindet, sich selbst überließ.\n\nÜberprüf mal den Frachtraum des Schiffs, wenn du das Ding wirklich willst.\n\nAber was auch immer du machst, bring den Stab bloß nicht wieder hierher! Und mach um Abdul einen großen Bogen! Er wird dir das Herz herausreißen.", sourceObjective = "Beschafft den Stab des Sturmfurors und bringt ihn zu Orfus von Kamagua im Heulenden Fjord.", progress = "Habt Ihr den Stab?", completion = "Wir müssen alle Artefakte zurückbringen, {name}. Wenn wir alle vier an uns gebracht haben, werdet Ihr sie in die Gräber zurücklegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11512] = { id = 11512, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das gefrorene Herz Isuldofs", description = "Einige sagen, dass Jonah nie ganz richtig im Kopf war, doch ich weiß, was wirklich passiert ist. Es war das Herz. Dieses verdammte gefrorene Herz! In dem Moment, als er es aus dem Grab nahm, sah ich, wie es ihn veränderte - konnte sehen, wie das Blut in seinen Adern gefror... Es war damals, als ihn wirklich der Wahnsinn packte.\n\nEr verließ uns, um sich in seiner Höhle auf der Nordseite der Insel zu verkriechen. Das Letzte, was ich gehört habe, war, dass er das Herz in den hinteren Teil seiner Bärenhöhle verbannt hat. Doch das ist nicht genug und es kommt viel zu spät...\n\nIch werde dich eigenhändig umbringen, wenn du das Herz mit hierher nimmst!", sourceObjective = "Beschafft das gefrorene Herz Isuldofs und bringt es zu Orfus von Kamagua im Heulenden Fjord.", progress = "Das... das gefrorene Herz Isuldofs?", completion = "Wir müssen alle Artefakte zurückbringen, {name}. Wenn wir alle vier an uns gebracht haben, werdet Ihr sie in die Gräber zurücklegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11513] = { id = 11513, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Manazellen abfangen", description = "Ich habe mir einen Plan ausgedacht, wie wir an eine Energiequelle kommen können, die stark genug ist, um unser Portal zu erschaffen.\n\nDie Streitmächte der Astralen auf dem Landeplatz von Bash'ir im Nordwesten des Schergrats schmuggeln Manazellen aus der Festung der Stürme heraus und schaffen sie in Kael'thas' Namen zum Sonnenbrunnen.\n\nSie haben die Zellen zwar versteckt, aber es gibt einen Weg, wie Ihr sie finden könnt. Die Astralen tragen Phasenvorrichtung bei sich, mit deren Hilfe Ihr die eingeschmuggelten Waren entdecken könnt.\n\nHütet Euch jedoch vor den Phasenwyrm, den Wächtern der Manazellen.", sourceObjective = "Beschafft 10 eingeschmuggelte Manazellen und kehrt anschließend zu Exarch Nasuun auf der Terrasse des Lichts in Shattrath zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[11514] = { id = 11514, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Sonnenbrunnenportal aufrechterhalten", description = "Wir müssen den Energiefluss zu unserem Portal aufrechterhalten oder es wird kollabieren. Die versteckten Manazellen der Astralen auf dem Landeplatz von Bash'ir werden den Zweck erfüllen. Der Landeplatz befindet sich weit im Norden auf dem Hochplateau in der nordwestlichen Ecke des Schergrats.\n\nBeschafft Euch eine Phasenvorrichtung von einem der Astralen und benutzt sie, um die Schmuggelwaren zu finden.\n\nNehmt Euch nur vor den Phasenwyrms in Acht, von denen sie die Manazellen bewachen lassen.", sourceObjective = "Beschafft 10 eingeschmuggelte Manazellen und kehrt anschließend zu Exarch Nasuun auf der Terrasse des Lichts in Shattrath zurück.", progress = "{name}, wie steht es um die Manazellen, die Ihr heute für uns beschaffen wollt?", completion = "Diese Manazellen werden unser Portal weiterhin mit Energie speisen.\n\nKehrt morgen wieder zurück und ich werde Euch wieder auf Manazellensuche schicken.", sourceObjectiveStatus = "unverified-source-field" }
quests[11515] = { id = 11515, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blut für Blut", description = "Als Kaels Streitmacht durch das Portal schritt, wurden seine loyalsten Lakaien auf eine entsetzliche Weise belohnt: Sie blieben zurück und soffen tagelang Dämonenblut.\n\nDas Blut hat sie verändert und ihnen neue Kräfte verliehen - es wird jedoch auch ihr Verderben sein.\n\nNehmt Blutproben von anderen Dämonen und benutzt sie, um den Teufelstrinker zu speisen und diese arroganten Narren ihrer Macht zu berauben. Tötet sie, sobald sie geschwächt sind. Kehrt dann zu mir zurück.", sourceObjective = "Magistrix Seyla auf Kil'jaedens Thron möchte, dass Ihr mit Hilfe des Teufelstrinkers 4 ausgemergelte Getriebene des Teufelsbluts tötet. Um den Teufelstrinker zu speisen, benötigt Ihr das Dämonenblut von Racheherolden, die sich in der Nähe befinden.", progress = "Diese Monster sind eine Schande für unser Volk. Wir müssen sie vernichten, {name}.", completion = "Narren. Sie haben gelernt, wie man Teufelsenergie entzieht, aber nicht, wie man sie behält.\n\nWir haben Glück, {name}. Ein erfahrener Streiter des Teufelsbluts hätte gewiss einen beeindruckenden Gegner abgegeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[11516] = { id = 11516, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vernichtet den Durchgang", description = "Wir müssen diesen Durchgang schließen, damit die Legion keine Verstärkung mehr zur Insel von Quel'Danas schicken kann.\n\nNehmt diese Glutstücke, in ihnen befindet sich eine meiner Kreationen: ein lebendiges Leuchtfeuer. Es besitzt so lange eine mächtige zerstörerische Kraft, wie es mit genug Energie versorgt wird.\n\nFindet die Höllenfunken, die in dieser Gegend umherwandern, und erschlagt sie in der Nähe des lebendigen Leuchtfeuers. Mit jedem Male wird das Leuchtfeuer mächtiger - bis es instabil wird.\n\nSobald Ihr das geschafft habt, bringt Ihr das Leuchtfeuer zum Durchgang. Es wird dann wissen, was zu tun ist.", sourceObjective = "Magistrix Seyla auf Kil'jaedens Thron möchte, dass Ihr mit Hilfe der zischenden Glut ein lebendiges Leuchtfeuer beschwört und damit so lange glühende Höllenfunken in seiner Nähe tötet, bis es zu einem instabilen lebendigen Leuchtfeuer wird. Kehrt anschließend mit letzterem zum Durchgang der Legion zurück und zerstört ihn.", progress = "Ist es vollbracht, {name}? Kael'thas darf keine weitere Verstärkung durch die Legion erhalten.", completion = "Ausgezeichnete Arbeit, {name}. Die Dämonen werden den Durchgang womöglich rechtzeitig reparieren. Na dann werden wir ihn wohl noch einmal in die Luft jagen müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11517] = { id = 11517, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meldung an Nasuun", description = "Ich bin so froh, dass Ihr hier seid, {class}! Nun, da wir das Sanktum eingenommen haben, müssen wir uns schleunigst daran machen, ein magisches Portal zu öffnen, das von Shattrath in der Scherbenwelt aus hier her führt.\n\nMein Lehnsherr Exarch Nasuun will mithilfe der Offensive genau das tun. Er hat mich gebeten, ihm die vielversprechendsten Kandidaten zu schicken, die das Zeug dazu haben, bei der Öffnung des Portals zu helfen.\n\nReist nach Shattrath und sprecht mit ihm. Ihr findet ihn in A'dals Halle auf der Terrasse des Lichts.", sourceObjective = "Händler Portanuus hat Euch gebeten, mit Exarch Nasuun auf der Terrasse des Lichts in Shattrath zu sprechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11519] = { id = 11519, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der verlorene Schild der Aesiriten", description = "Wenn du genau hinhörst, kannst du im Nordosten das Feuer von Kanonen vernehmen. Das ist Kapitän Ellis' Schiff, die \"Gnädige Schwester\". Die Sache ist nur, dass Ellis und seine gesamte Crew vor 'nem Monat getötet wurden.\n\n<Harry nickt bestätigend.>\n\nGeisterschiff...\n\nWenn du mehr über den Schild wissen willst, dann ist Ellis genau der richtige Mann dafür.\n\nZwischen dem Halunkeneck und Sorlofs Strand liegt eine Insel, vor der die \"Gnädige Schwester\" ungefähr alle 5 Minuten vor Anker geht, um ihre Crew neu aufzustocken. Denke mal, dass es in der Gegend genug Möglichkeiten dazu geben wird...", sourceObjective = "Sprecht mit Kapitän Ellis an Bord der Gnädigen Schwester.", completion = "Harr, moi Crew un' ich haben den Schild mitgehen lass'n! Wir woll'n versuchen, ihn dieser nichtsnutzigen, diebischen Landratte namens Sorlof wieder wegzunehmen! Magst du uns dabei helfen, harr?\n\nNu, wie du sehen kannst, werden wir 'ne Skelettcrew haben!\n\n<Kapitän Ellis lacht.>\n\nDas Gnädige Schwesterlein wird 'nen neuen Pulverjungen brauchen, der sich an die großen Wummen drüb'n auf'm Poopdeck setzt. Denkst du, du schaffst das, mein Junge?\n\nHilf moi Crew, Sorlof um die Ecke zu bringen, und wir teilen gemeinsam die Beute! Du kannst den Schild haben und meine Crew und ich kriegen den Rest!", sourceObjectiveStatus = "unverified-source-field" }
quests[11520] = { id = 11520, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die eigenen Wurzeln entdecken", description = "Grüße, {race}.\n\nLeider kann ich Euch nichts anbieten, solange ich keine Reagenzien auf Lager habe.\n\nEines der benötigten Reagenzien ist eine Besonderheit. Es trägt den Namen Messerdornwurzel und ist besonders schwierig zu sammeln.\n\nZum Glück kenne ich da ein Geheimnis...\n\nMan benutzt einfach die Drüsen eines Messerdornschinders, um auf diese Weise einen Hetzer zu kontrollieren, der dann eine Wurzel freilegt.\n\nWenn Ihr die Wurzeln finden wollt, dann müsst Ihr in die Scherbenwelt reisen und von Shattrath aus gen Nordosten fliegen, bis Ihr die Messerdornhöhen erreicht.", sourceObjective = "Mar'nah im Hafen der Sonnenweiten möchte, dass Ihr zur Messerdornhöhe in der Scherbenwelt reist, 5 Messerdornwurzeln sammelt und wieder zu ihr zurückkehrt.", sourceObjectiveStatus = "unverified-source-field" }
quests[11521] = { id = 11521, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eure Wurzeln wiederentdecken", description = "Ich verfüge im Moment über genug Vorräte. Ich werde jedoch eine Menge Messerdornwurzeln benötigen, um der Nachfrage nachzukommen.\n\nMan benutzt einfach die Drüsen eines Messerdornschinders, um auf diese Weise einen Hetzer zu kontrollieren, der dann eine Wurzel freilegt.\n\nWenn Ihr die Wurzeln finden wollt, dann müsst Ihr in die Scherbenwelt reisen und von Shattrath aus gen Nordosten fliegen, bis Ihr die Messerdornhöhen erreicht.\n\nKehrt zu mir zurück, {name}, sobald Ihr fünf dieser Wurzeln gesammelt habt.", sourceObjective = "Mar'nah im Hafen der Sonnenweiten möchte, dass Ihr zur Messerdornhöhe in der Scherbenwelt reist, 5 Messerdornwurzeln sammelt und wieder zu ihr zurückkehrt.", progress = "Ich bitte Euch, {name}. Ich bin viel zu beschäftigt, als dass ich mich auf unnützes Geschwätz einlassen würde.\n\nSagt mir Bescheid, sobald Ihr die besagten Wurzeln eingesammelt habt.", completion = "Ausgezeichnete Arbeit, {name}.\n\nDanke noch mal für Eure Hilfe!", sourceObjectiveStatus = "unverified-source-field" }
quests[11523] = { id = 11523, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fahrt die Barrieren hoch!", description = "Wir haben die Kristallbarrieren um das Sanktum erfolgreich reaktiviert, aber warum hier aufhören?\n\nWir werden Verteidigungen um die anderen Gebäude herum aufbauen, aber die Getriebenen sind dickköpfig und stehlen weiterhin Energie von den Kristallbarrieren.\n\nStellt ihnen nach und holt Euch die Manaüberreste, die sie bei sich tragen. Benutzt die Überreste, um die Barrieren des Sanktums zu energetisieren, die Sicherheit unseres Vorhabens hängt davon ab.", sourceObjective = "Hauptmann Theris Morgenheim beim Sammelpunkt der Zerschmetterten Sonne will, dass Ihr 4 Manaüberreste von getriebenen Unholden und Verschlingern beschafft und sie benutzt, um eine der Kristallbarrieren aufzuladen, welche die Gebäude der Sonnenweiten umgeben.", completion = "Gute Arbeit, {name}. Die Barrieren erhalten allmählich ihre Kraft zurück. Die Sonnenweiten werden im Handumdrehen uns gehören!", sourceObjectiveStatus = "unverified-source-field" }
quests[11524] = { id = 11524, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unberechenbares Verhalten", description = "Wir sind zwar nicht genug, um das Sanktum der Sonnenweiten einzunehmen, aber ich habe einen Plan, mit dem wir den Kampf zu unseren Gunsten wenden können.\n\nDie unkontrollierten Energien des Sonnenbrunnens verursachten Fehlfunktionen bei den Wachposten, die auf dieser Insel patrouillieren. Die Kristallkerne, die ihr Verhalten steuern, sind irreparabel beschädigt.\n\nIch habe neue Kristalle angefertigt, mit denen wir sie unter unsere Kontrolle bringen werden. Steckt die Kristalle ins Innere der besiegten Wachposten. Wir benötigen jede Hilfe, die wir bekommen können.", sourceObjective = "Verteidigerin Xayann beim Sammelpunkt der Zerschmetterten Sonne möchte, dass Ihr die abgestimmten Kristallkerne ins Innere 5 besiegter herumirrender Wachposten steckt und sie so zu freundlichen Einheiten macht.", sourceObjectiveStatus = "unverified-source-field" }
quests[11525] = { id = 11525, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weitere Konvertierungen", description = "Mein Plan, die beschädigten Kristalle der unberechenbaren Wachposten auszutauschen, hat funktioniert. Wir konnten mit ihrer Hilfe das Sanktum der Sonnenweiten einnehmen.\n\nIch habe neue Kristalle angefertigt, die noch mehr von ihnen unter unsere Kontrolle bringen werden. Platziert diese im Inneren besiegter Wachposten. Wir werden sie dann an verschiedene Orte entsenden, um sie dort einzusetzen, sobald sie konvertiert sind.", sourceObjective = "Verteidigerin Xayann beim Sammelpunkt der Zerschmetterten Sonne möchte, dass Ihr die abgestimmten Kristallkerne ins Innere 5 besiegter herumirrender Wachposten steckt und sie so zu freundlichen Einheiten macht.", progress = "Habt Ihr die Wachposten konvertiert, {name}?", completion = "Ausgezeichnet. Die konvertierten Wachposten werden uns bei der Sicherung unseres Gebiets helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11526] = { id = 11526, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Magistrix wird vermisst", description = "Wir haben eine unserer Agentinnen ausgesandt, um das Teufelsportal in der Mitte des im Süden gelegenen Platzes der Morgenröte zu untersuchen. Sie ist noch nicht zurückgekehrt.\n\nNehmt diese Schriftrolle - eine der Leichen des Feindes trug sie bei sich. Wir nehmen an, dass sie Euch den Zugang durch das Portal gewährt. Schreitet durch das Portal, spürt Magistrix Seyla auf und helft, so gut Ihr nur könnt.", sourceObjective = "Benutzt die erbeutete Schriftrolle der Legion in der Nähe des Portals auf dem Platz der Morgenröte. Findet Magistrix Seyla, sobald Ihr auf der anderen Seite des Portals seid.", progress = "Seid still, {class}. Die Truppen der Legion bewachen die Gegend südlich des Tors.", completion = "Es ist lieb von Theris, dass er sich um mich Sorgen macht, aber wir haben hier größere Probleme - viel größere.", sourceObjectiveStatus = "unverified-source-field" }
quests[11527] = { id = 11527, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meuterei auf der Gnädigen", description = "Aye, wir haben Schwierigkeiten, <Kamerad/Herzchen>. Moine Kanoniere sind am Meutern! Moi Crew un' ich an Deck werden wohl versuchen müssen, Sorlof in den Hintern zu treten und gleichzeitig mit den meuternden Kanonieren unter Deck fertigzuwerden.\n\nDu wirst ma' nach unten gehen und dich um die meuternden Seehunde kümmern müssen. Nimm auch ihr Schießpulver mit – wirst es für die Wumme drüben auf'm Poopdeck brauch'n.\n\nMit dir an der fetten Wumme wird Sorlof sicher abnibbeln und die Beute freigeben!", sourceObjective = "Kapitän Ellis an Bord der Gnädigen Schwester im Heulenden Fjord möchte, dass Ihr 5 Schießpulverfässer aus dem Frachtraum des Schiffs besorgt.", progress = "Es wimmelt nur so von meuternden Seehunden und Meeresriesen!", completion = "Hoffen wir mal, dass diese abtrünnigen, schmierigen Ratten ihre Lektion gelernt haben! Nun ist's Zeit, dass du dich an die fette Wumme setzt, Kamerad!", sourceObjectiveStatus = "unverified-source-field" }
quests[11528] = { id = 11528, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Winterhauchgeschenk" }
quests[11529] = { id = 11529, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sorlofs Beute", description = "Meine Mannschäft macht die digge Berda für dich feddich, Matrouse. Dat Fräulein hat sich's entweder auf dem Bug oudär auf die andere Saide von die Kuddä gämüdlich gemacht. Na lous, rann an die Kiste und mach dich feuäbereit, wenn Sorlof in Sicht is'!\n\nWenn wiä dann ers' mal die Landradde erwischt haben, wirst du für uns an die Beude rankommen müss'n - wiä können ja nich von dem verdammten Boud runnä! Bring mir die Beude, dann gibt's auch ne kleine Pütz Gold für dich - der Schild...", sourceObjective = "Vernichtet Sorlof mithilfe der Dicken Berta, holt Euch Sorlofs Beute und kehrt mit ihr zu Kapitän Ellis auf der Gnädigen Schwester zurück.", progress = "Mach hinne, me Jung!", completion = "Geschäft is' Geschäft, me Jung!", sourceObjectiveStatus = "unverified-source-field" }
quests[11530] = { id = 11530, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schild der Aesiriten", description = "Hiä is' der Schild. Ik hoff' mal dat Euch dat Dingens näch' genauso verfluchen wiäd wie es dat mit meiner Mannschäft un' mich gemacht hät. Ihr müssd nou mal nich nach Hause gehn, aber hiä bleiben, dat könnt Ihr nu auch nich'... Ik bin miä sischr, dat es da ein paar Leude geben wiäd, die dat Dingens zurück haben wolln.\n\nNou schaff miä die Schüssl vom Kahn!", sourceObjective = "Bringt den Schild der Aesiriten zu Orfus von Kamagua. Er befindet sich am Uralten Aufzug im Heulenden Fjord.", progress = "Ihr seid zurückgekehrt!", completion = "Wir müssen alle Artefakte zurückbringen, {name}. Wenn wir alle vier an uns gebracht haben, werdet Ihr sie in die Gräber zurücklegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11531] = { id = 11531, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seltsames Motorteil", description = "Dieses seltsame Motorteil sieht zwar nicht so aus, als würde es in eine Dampfpumpe passen, jedoch scheint alles andere, was Ihr so herumliegen seht, noch weniger dafür geeignet zu sein. Vielleicht weiß K. Lee Kleinkram mehr darüber.", sourceObjective = "Bringt K. Lee Kleinkram in Telredor das seltsame Motorteil.", progress = "Du meine Güte! Was habt Ihr denn da, {name}?", completion = "<K. Lee sieht sich das Motorteil an und wirkt für einen Moment abwesend.>\n\nDas ist mal was echt Besonderes. Hm, schwer zu sagen, woher das Ding kommt. Ich behalte es erst einmal für mich und werde Euch für die Unannehmlichkeiten entschädigen.\n\nAber unter uns gesagt, denke ich, dass es am besten wäre, wenn wir niemandem davon erzählen.\n\n<K. Lee zeigt Euch ihr bestes Lächeln.>", sourceObjectiveStatus = "unverified-source-field" }
quests[11532] = { id = 11532, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ablenkungsmanöver an der Todesschneise", description = "Die Legion wird uns angreifen, sobald ihre Truppen im Süden nicht mehr gebunden sind. Im Moment hält die Geißel in der Todesschneise ihre Streitkräfte beschäftigt. Jedoch nicht mehr lange.\n\nIch möchte, dass Ihr mit einem Drachenfalken über die Schneise hinwegfliegt und die Dämonen mithilfe dieser arkanen Ladungen dezimiert.\n\nWenn alles gut geht, werden Kaels Lakaien es nicht einmal bemerken, wenn wir die Waffenkammer einnehmen. Sprecht mit Ayren, dem Drachenfalkenmeister im westlichen Teil des Hafens, sobald Ihr bereit seid loszufliegen.", sourceObjective = "Kampfmagierin Arynna möchte, dass Ihr mit Ayren Wolkenbrecher sprecht, sobald Ihr bereit seid, zur Todesschneise zu fliegen. Tötet dort mithilfe der arkanen Ladungen 2 Oberanführer der Grube, 3 Zauberer der Eredar und 12 Rachevollstrecker.", sourceObjectiveStatus = "unverified-source-field" }
quests[11533] = { id = 11533, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Luftangriffe müssen weitergehen", description = "Dank unserer Luftangriffe gegen die Truppen der Legion in der Todesschneise konnten wir dem Feind die Waffenkammer abjagen.\n\nTatsächlich lief die Sache so gut, dass wir unsere Luftangriffe gegen sie weiterführen werden. Nehmt diese arkanen Ladungen und verwendet sie gegen ihre Truppen.\n\nSprecht mit Ayren Wolkenbrecher im Hafen der Sonnenweiten, sobald Ihr abflugbereit seid.", sourceObjective = "Kampfmagierin Arynna möchte, dass Ihr mit Ayren Wolkenbrecher sprecht, sobald Ihr bereit seid, zur Todesschneise zu fliegen. Tötet dort mithilfe der arkanen Ladungen 2 Oberanführer der Grube, 3 Zauberer der Eredar und 12 Rachevollstrecker.", progress = "Habt Ihr Eure Mission erfüllt, {name}?", completion = "Dämonen, die wir heute töten, sind Dämonen, die wir morgen nicht mehr bekämpfen müssen. Weiter so.", sourceObjectiveStatus = "unverified-source-field" }
quests[11534] = { id = 11534, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meldung an Nasuun", description = "Ich bin so froh, dass Ihr hier seid, {class}! Nachdem wir dieses Sanktum den Getriebenen weggenommen hatten, beeilten wir uns, ein Portal zu erschaffen, das von Shattrath in der Scherbenwelt aus hierher führt.\n\nMein Lehnsherr Exarch Nasuun leitet die Bemühungen der Offensive, dieses Portal aufrechtzuerhalten. Er hat mich gebeten, ihm die vielversprechendsten Kandidaten zu schicken, die das Zeug dazu haben, bei der Energieversorgung des Portals behilflich zu sein.\n\nReist nach Shattrath und sprecht mit Nasuun. Ihr findet ihn in A'dals Halle auf der Terrasse des Lichts.", sourceObjective = "Händler Portanuus hat Euch gebeten, mit Exarch Nasuun auf der Terrasse des Lichts in Shattrath zu sprechen.", completion = "Portanuus hat Euch geschickt? Gut, wir haben keine Zeit zu verlieren!", sourceObjectiveStatus = "unverified-source-field" }
quests[11535] = { id = 11535, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorbereitungen", description = "Versorgungsgüter sind auf dem Weg hierher - wird mir zumindest gesagt.\n\nTrotzdem können wir es uns nicht leisten, hier zu warten und zu hoffen, dass Hilfe kommen wird, bevor die Offensive zum Stillstand kommt. Wir müssen das Beste aus dem machen, was uns gegeben ist.\n\nFür meinen Teil benötige ich Erz, um daraus einen Amboss zu fertigen und anzufangen, unsere Rüstungen und Waffen aufzubessern.\n\nAn der Küste im Osten gibt es eine Gruppe Naga, die Erz abbaut und es dann in Truhen an die Legion schickt.\n\nWenn wir ihnen ihr Erz abnehmen, wird das unserem Vorhaben in vielerlei Hinsicht zugutekommen...", sourceObjective = "Schmiedin Hauthaa in der Waffenkammer der Sonnenweiten möchte, dass Ihr Myrmidonen der Dunkelflossen, die sich im Osten befinden, tötet und ihre Schlüssel dazu verwendet, 3 Stück Erz aus ihren Truhen zu stehlen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11536] = { id = 11536, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hört jetzt nicht auf!", description = "Da wir jetzt einen Amboss haben, kann ich so richtig anfangen zu arbeiten.\n\nIch werde das Eisenerz der Dunkelflossen immer gut gebrauchen können, egal wie viele Versorgungsgüter wir bekommen. Wenn wir hier gewinnen wollen, dann benötigen wir regelmäßige Waffen- und Rüstungslieferungen.\n\nAn der Küste im Osten gibt es eine Gruppe Naga, die Erz abbaut und es dann in Truhen an die Legion schickt. Wenn wir ihnen ihr Erz abnehmen, wird das unserem Vorhaben in vielerlei Hinsicht zugutekommen...", sourceObjective = "Schmiedin Hauthaa in der Waffenkammer der Sonnenweiten möchte, dass Ihr Myrmidonen der Dunkelflossen, die sich im Osten befinden, tötet und ihre Schlüssel dazu verwendet, um 3 Stück Erz aus ihren Truhen zu stehlen.", progress = "Habt Ihr das Erz, nach dem ich Euch gefragt habe, eingesammelt?", completion = "Ausgezeichnet! Damit werde ich Rüstungen und Waffen für unsere Soldaten herstellen können.\n\nEure Hilfe ist Gold wert!", sourceObjectiveStatus = "unverified-source-field" }
quests[11537] = { id = 11537, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlacht muss weitergehen", description = "Wir müssen zusehen, dass wir die Armeen der Legion weiterhin besiegen und entmutigen.\n\nDie Abgesandten des Hasses sind Stoßtruppen der Legion, die immer dann eingesetzt werden, wenn ihre Streitkräfte erhebliche Verluste zu verzeichnen haben. Wenn sie auf der Bildfläche erscheinen, schart sich der Feind um sie, denn er fürchtet sie mehr als uns.\n\nHeute werden wir das ändern. Nehmt dieses Banner und erschlagt die Dämonen auf dem Platz der Morgenröte. Tötet den Abgesandten, sobald Ihr ihm begegnet, und spießt anschließend seinen Körper auf.", sourceObjective = "Herold Inuuro möchte, dass Ihr 6 Dämonen der brennenden Legion und den Abgesandten des Hasses auf dem Platz der Morgenröte niederstreckt. Benutzt das Banner der Zerschmetterten Sonne, um den Körper des Abgesandten des Hasses aufzuspießen.", progress = "Wart Ihr erfolgreich, {name}?", completion = "Euer Engagement ist beispielhaft, {name}. Wir werden den Streitkräften der Brennenden Legion zeigen, wozu wir im Stande sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[11538] = { id = 11538, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlacht um die Waffenkammer der Sonnenweiten", description = "Die Brennende Legion hält die Waffenkammer der Sonnenweiten - sie ist von taktischer Wichtigkeit für unseren Einsatz. Solange ihre Moral hoch bleibt, werden wir das Gebäude ihrem Griff nicht entziehen können.\n\nDie Abgesandten des Hasses sind Elitestoßtruppen der Legion, die als Verstärkung für taktisch wichtige Stellungen eingesetzt werden. Wenn sie auf der Bildfläche erscheinen, schart sich der Feind um sie, denn er fürchtet sie mehr als uns.\n\nHeute werden wir das ändern. Nehmt dieses Banner und erschlagt die Dämonen der Legion. Tötet den Abgesandten, sobald Ihr ihm begegnet, und durchspießt seinen Körper.", sourceObjective = "Herold Inuuro möchte, dass Ihr 6 Dämonen der brennenden Legion und den Abgesandten des Hasses auf dem Platz der Morgenröte oder der Waffenkammer der Sonnenweiten niederstreckt. Benutzt das Banner der Zerschmetterten Sonne, um den Körper des Abgesandten des Hasses aufzuspießen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11539] = { id = 11539, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Hafen einnehmen", description = "Die Armee der Dämmerklingen - sie gehört zu Kaels Elitestreitkräften - wurde im Hafen der Sonnenweiten und in Morgenstern stationiert.\n\nDer Hafen ist von höchster strategischer Bedeutung für unsere Pläne. Je mehr Dämmerklingen Ihr also beseitigt, umso mehr helft Ihr uns damit. Kael'thas wird den Tag bereuen, als er sich von seinem Volk abwandte und sich mit der Brennenden Legion einließ.", sourceObjective = "Magister Ilastar in der Waffenkammer der Sonnenweiten möchte, dass Ihr 6 Beschwörer der Dämmerklingen, 6 Blutritter der Dämmerklingen und 3 Schützen der Dämmerklingen niederstreckt.", sourceObjectiveStatus = "unverified-source-field" }
quests[11540] = { id = 11540, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vernichtet die Dämmerklingen", description = "Wir haben die Armee der Dämmerklingen aus dem Hafen der Sonnenweiten vertrieben. Die Sonnenweiten gehören nun uns. Doch... bin ich nicht vollends zufrieden.\n\nIch möchte, dass Ihr Euch ins westlich gelegene Morgenstern begebt und jeden überlebenden Anhänger der Dämmerklingen erschlagt, der Euch über den Weg läuft. Sie besiegelten ihr Schicksal, als sie Kael an diesen Ort folgten.", sourceObjective = "Magister Ilastar in der Waffenkammer der Sonnenweiten möchte, dass Ihr 6 Beschwörer der Dämmerklingen, 6 Blutritter der Dämmerklingen und 3 Bogenschützen der Dämmerklingen niederstreckt.", completion = "Was geht nur durch Prinz Kael'thas Sonnenwanderers Kopf, wenn er von den Niederlagen seiner Armeen erfährt?\n\nIst es Verzweiflung? Hilflosigkeit? Furcht?\n\nIch hoffe doch, dass dem so ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[11541] = { id = 11541, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Belästigung an der Küste der Grünkiemen", description = "Die Naga haben die Küste der Grünkiemen im Südosten erobert. Ihre Frauen, die Sirenen der Dunkelflossen, haben die Murlocs bezaubert und zu ihren Sklaven gemacht.\n\nEs ist meine Pflicht, dafür zu sorgen, dass das, was auch immer die Naga dort treiben, gestört wird. Hier kommt Ihr ins Spiel.\n\n{class}, ich möchte, dass Ihr den weiblichen Naga die Kontrollkugeln abnehmt und sie auf den Boden in der Nähe der Grünkiemensklaven werft, damit die Kugel zerspringt und die Murlocs befreit werden.\n\nIch nehme an, dass die Murlocs erbost sein werden und sich gegen ihre Meister wenden werden.", sourceObjective = "Kapitänin Valindria möchte, dass Ihr 10 Grünkiemensklaven befreit und zu ihr zurückkehrt, sobald Ihr damit fertig seid. Sie befindet sich auf der 'Silbermonds Stolz' im Hafen der Sonnenweiten.", completion = "Das reicht für heute. Zeit und Regelmäßigkeit ist hier der Schlüssel zum Erfolg. Wenn wir sie zu sehr belästigten, würden sie ihre Aufmerksamkeit direkt auf uns richten - und das wollen wir nicht.\n\nKommt morgen wieder zurück, damit wir für ein wenig mehr Belästigung sorgen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[11542] = { id = 11542, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haltet die Verstärkung auf", description = "Wir stoßen vor und nehmen den Hafen als Nächstes ein, um unsere Kontrolle über die Sonnenweiten zu festigen. Leider ist eine Flotte Schiffe mit Reservisten der Dämmerklingen auf dem Weg dorthin, um Kaels Truppen zu verstärken.\n\nNehmt dieses Öl, geht zu Ayren Wolkenbrecher und besorgt Euch einen Drachenfalken von ihm. Ihr solltet bis in Reichweite der Schiffssegel fliegen und sie dann in Brand setzen können.\n\nLandet auf einem der Schiffe und greift die Reservisten an. Mit brennenden Segeln werden sie sich nicht großartig verteidigen können.", sourceObjective = "Verteidiger Kaalan in der Waffenkammer der Sonnenweiten möchte, dass Ihr mit Ayren Wolkenbrecher redet. Fliegt dann über die Unterstützungsflotte der Dämmerklingen hinweg und benutzt das flammende Öl, um die Segel in Brand zu setzen. Erschlagt 6 Reservisten der Dämmerklingen, nachdem Ihr gelandet seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[11543] = { id = 11543, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Feind vom Leibe halten", description = "Wir konnten die Sonnenweiten vollständig einnehmen. Leider hat sich eine Flotte Schiffe mit Reservisten der Dämmerklingen auf den Weg gemacht, um den Hafen einzunehmen.\n\nNehmt dieses Öl, geht zu Ayren Wolkenbrecher und besorgt Euch einen Drachenfalken von ihm. Ihr solltet bis in Reichweite der Schiffssegel fliegen und sie dann in Brand setzen können.\n\nLandet auf einem der Schiffe und greift die Reservisten an. Mit brennenden Segeln werden sie keine wirkliche Gegenwehr starten können.", sourceObjective = "Verteidiger Kaalan in der Waffenkammer der Sonnenweiten möchte, dass Ihr mit Ayren Wolkenbrecher redet und über die Flotte mit Verstärkungstruppen der Dämmerklingen hinwegfliegt. Benutzt solange Ihr fliegt das flammende Öl, um die Segel in Brand zu setzen. Erschlagt 6 Reservisten der Dämmerklingen, nachdem Ihr gelandet seid.", progress = "Konntet Ihr Eure Aufgabe erfüllen, {name}?", completion = "Gut gemacht, {name}. Es sollte eine Weile dauern, bis irgendwelche Verstärkungstruppen im Hafen ankommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11544] = { id = 11544, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waffen von Ata'mal", description = "Die Terrasse von Ata'mal im Osten des Schattenmondtals ist den Draenei heilig. Derzeit ist sie jedoch von Höllenorcs besetzt, die das spezielle Erz, das dort vorkommt, geschürft und daraus Waffen und Rüstungen der Verderbnis hergestellt haben.\n\nIch brauche die Waffen, um eine Legierung mit Nagaerz herzustellen. Unsere Anachoreten haben meinen Amboss mit der Fähigkeit gesegnet, sie zu reinigen.\n\nIhr könnt die Waffen an den Auserwählten, Tötern und Dunkelwirkern des Schattenmondklans finden. Bringt sie hierher, zerlegt und reinigt sie auf meinem Amboss und übergebt mir das gereinigte Resultat.", sourceObjective = "Schmiedin Hauthaa möchte, dass Ihr 5 Stück gereinigtes Metall von Ata'mal herstellt. Um dies zu tun, müsst Ihr Waffen von Ata'mal auf ihrem Amboss in der Waffenkammer der Sonnenweiten auf der Insel von Quel'Danas zerlegen.", progress = "{class}, ich brauche so viel gereinigtes Metall von Ata'mal, wie nur möglich.", completion = "Ich danke Euch, Freund. Nun werde ich mehr von der speziellen Legierung herstellen können, die zur Herstellung der Waffen und Rüstungen unserer Streitkräfte verwendet wird.\n\nAußerdem habe ich hier ein wenig von dem Extrakt, das bei der Herstellung übrig geblieben ist. Ihr werdet es wahrscheinlich sehr nützlich für Eure Waffen finden. Wählt bitte das aus, was Euren Zwecken am besten dient.\n\nKehrt zu mir am morgigen Tage zurück. Ich werde mit Sicherheit mehr Waffen benötigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11545] = { id = 11545, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine milde Gabe", description = "Wir haben die Sonnenweiten dem Feind entrissen - der endgültige Sieg steht kurz bevor. Der Preis war hoch und viele tapfere Kämpfer gaben dafür ihr Leben.\n\nMein Ziel ist es, sicherzustellen, dass die Gefallenen nicht vergessen werden. Also bitte ich Euch, dass Ihr einen Moment innehaltet, um über eine Spende für eine Gedenkstätte nachzudenken. Alles übrig gebliebene Gold wird an die Witwen und Waisen der Gefallenen gehen.", sourceObjective = "Anachoretin Ayuri in den Sonnenweiten auf der Insel des Sonnenbrunnens möchte, dass Ihr 10 Gold spendet.", sourceObjectiveStatus = "unverified-source-field" }
quests[11546] = { id = 11546, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geschäft geöffnet", description = "Willkommen, {name}.\n\nEs gibt mehrere Möglichkeiten, wie ich Euch bei Eurem Unterfangen behilflich sein kann.\n\nIch habe zum Beispiel vor Kurzem ein Rezept für ein einzigartiges Elixier entdeckt.\n\nDie Blutbeere ist in vielen Regionen Azeroths ein wildes Gewächs und wurde sehr lange als lästig empfunden. Ich habe jedoch herausgefunden, dass die Pflanze, wenn sie den Kräften des Sonnenbrunnens ausgesetzt wird, besondere Eigenschaften annimmt, die destilliert und anschließend getrunken werden können, um die eigenen Fähigkeiten zu verstärken.\n\nGeht zu den Büschen in der Nähe und bringt mir eine Probe - dann werdet Ihr sehen, was ich meine.", sourceObjective = "Mar'nah im Hafen der Sonnenweiten möchte, dass Ihr 5 Blutbeeren von den Büschen auf Quel'Danas sammelt.", progress = "Habt Ihr diese Beeren schon gesammelt?", completion = "Ausgezeichnet, {name}.\n\nIch hoffe, dass Euch dies bei Eurem Unterfangen helfen wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[11547] = { id = 11547, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kenne deine Leylinien", description = "Trittbrettfahrer!\n\nAlle wollen sie ihre Wünsche sofort erfüllt haben, ohne auch nur einen Gedanken daran zu verschwenden, wie viel Anstrengung selbst im einfachsten Portal steckt.\n\nVielleicht wird Euch etwas Aufklärung ein wenig mehr Dankbarkeit für meine unermüdlichen Anstrengungen beibringen.\n\nNehmt diesen Kristall und stimmt ihn auf den Blutkristall im Westen ab. Dieselbe Prozedur müsst Ihr dann am Portal auf dem Platz der Morgenröte im Süden und in der Nähe des Nagaschreins an der Küste der Grünkiemen im Südosten wiederholen.\n\nVielleicht werdet Ihr dann Eure heiß geliebten Translokationen mehr schätzen...", sourceObjective = "Astromant Darnarian im Sanktum der Sonnenweiten möchte, dass Ihr den Kristall des Astromanten am Blutkristall, am Portal auf dem Platz der Morgenröte und in der Nähe des Nagaschreins an der Küste der Grünkiemen benutzt.", progress = "Habt Ihr den Kristall schon ausgerichtet, {class}?", completion = "Ja, ja. Sehen wir uns das doch einmal an.\n\nAlles scheint in Ordnung zu sein. Also gut. Hier ist Euer Translokator.\n\nWenn auch nur ein Teil Eurer Messungen fehlerhaft ist, dann ist es unvorhersehbar, wo genau Ihr landen werdet. Aber dann wäret Ihr wohlgemerkt selber schuld.", sourceObjectiveStatus = "unverified-source-field" }
quests[11548] = { id = 11548, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eure weitere Unterstützung", description = "Wir haben den Gefallenen zu Ehren ein Denkmal errichtet - ein kleiner Trost für die Familien, die ihre Angehörigen verloren haben.\n\nIch werde damit beginnen, Spenden zu sammeln, um die Waisen und Ehepartner unserer Kriegshelden zu unterstützen. Falls Ihr eine kleine Spende machen könntet, würdet Ihr viel dazu beitragen.", sourceObjective = "Anachoretin Ayuri in den Sonnenweiten auf der Insel des Sonnenbrunnens möchte, dass Ihr 10 Gold spendet.", progress = "Wollt Ihr eine Spende machen?", completion = "Ihr seid eine tugendhafte Seele, {name}. In Zeiten des Krieges und Triumphs werden die Gefallenen nur zu leicht vergessen. Die Freunde und Familien der Toten danken Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[11549] = { id = 11549, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein großmütiger Spender", description = "Ihr habt viel für uns getan, {name}. Wir sind Euch für Eure Unterstützung sehr dankbar.\n\nIhr habt vielleicht bemerkt, wie sich die Anachoretin Ayuri dort draußen bemüht. Sie hat ein großes Herz und ist sehr überzeugend, aber die Spenden kommen nicht gerade an das heran, was sie sich erhofft hatte.\n\nFalls Ihr eine große Spende machen würdet, um ihre Sache zu unterstützen, werde ich mich persönlich dafür stark machen, dass Eure Taten in diesem Krieg weit und breit bekannt sein werden. Was sagt Ihr dazu?", sourceObjective = "Anachoret Kairthos möchte, dass Ihr 1000 Gold spendet, um Anachoretin Ayuri in ihrem Vorhaben zu unterstützen. Wenn Ihr die Aufgabe abschließen solltet, werdet Ihr den Namen \"{name} der Zerschmetterten Sonne\" tragen.", progress = "Seid Ihr bereit dazu, den Beitrag zu leisten?", completion = "Ihr seid wahrhaftig eine großzügige Person und ein würdiger Verbündeter. Von nun an sollt Ihr als \"{name} der Zerschmetterten Sonne\" bekannt sein. All diejenigen, die hier kämpften, werden von Euren Taten wissen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11550] = { id = 11550, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Betrüger betritt die Bühne...", description = "Kael'thas' finstere Pläne konnten unseren größten Anstrengungen zum Trotz ausgeführt werden. Der Sonnenbrunnen wurde wieder entfacht, um die Ankunft des Betrügers vorzubereiten.\n\nDer Gegenstand, der vor mir steht und über dem A'dal schwebt, repräsentiert den derzeitigen Status der Verteidigungsanlagen des Sonnenbrunnens. Es wurden riesige Barrieren errichtet, um unsere Angriffe auf die inneren Hallen zu behindern. Wenn unsere Welt jemals Hilfe benötigen sollte, dann wäre es jetzt.\n\nMeldet Euch bei Erzmagier Ne'thul auf der Insel von Quel'Danas nördlich von Quel'Thalas.", sourceObjective = "Meldet Euch bei Erzmagier Ne'thul auf der Insel von Quel'Danas, nördlich von Quel'Thalas.\n\nSprecht mit Flugmeistern in Eisenschmiede und Silbermond, sie werden Euch dorthin bringen.", completion = "Kil'jaeden stürzt sich mit der geballten Kraft der Brennenden Legion auf diese Welt. Sollte er beschworen werden, wird unsere Welt abermals im Chaos versinken. Eure Unterstützung auf der Insel von Quel'Danas ist entscheidend für unseren Sieg über die Legion.\n\nUnsere Magier arbeiten daran, die Barrieren zu durchbrechen, die uns den Zugang zum Sonnenbrunnen versperren. Leistet Euren Beitrag im Kampf gegen die Streitkräfte der Legion, indem Ihr der Offensive der Zerschmetterten Sonne helft.", sourceObjectiveStatus = "unverified-source-field" }
quests[11554] = { id = 11554, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Freund an der Front", sourceObjective = "Euer Beitrag zur Offensive wurde nicht übersehen, {name}. Die vereinten Kräfte der Aldor und Seher bedanken sich bei Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[11555] = { id = 11555, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eure Verbündeten wollen Euer Wohl", sourceObjective = "Ihr beweist Euch weiterhin als würdig in dieser überaus wichtigen Schlacht, {name}. Bitte nehmt dies als Zeichen unserer fortwährenden Dankbarkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[11556] = { id = 11556, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf dem Schlachtfeld zollt man Euch Respekt", sourceObjective = "Ohne Euch hätten wir nie so weit kommen können, {name}. Die vereinten Kräfte der Aldor und Seher sind nicht genug, um die Legion und Kael zu vernichten. Wir sind froh darüber, Verbündete von Eurem Kaliber unter uns zu haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[11557] = { id = 11557, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alle Kämpfer begegnen Euch mit Ehrfurcht", sourceObjective = "Ihr seid einer unserer allerbesten Kämpfer, {name}. In unserer Armee wird man Euren Namen nicht so schnell vergessen.\n\nIm Namen unserer Streitkräfte bitte ich Euch, dieses kleine Geschenk entgegenzunehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11558] = { id = 11558, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefährliche Liebschaft", description = "Diese Liebesepidemie hat etwas Unnatürliches an sich. Sie ist abscheulich und hat sie erst einmal unsere Verteidigung geschwächt, könnte dies zu einer ernsten Bedrohung für uns alle werden.\n\nSchlimm genug, dass bereits so viele unserer Leute von diesem lächerlichen Verhalten befallen sind. Ich denke, selbst unsere Wächter hat es bereits erwischt, dabei sollten sie gegen derartige Einflüsse immun sein.\n\nGeht zu einem der Wächter und seht, ob er von dieser Dummheit befallen wurde.", sourceObjective = "Besorgt eine modrige Karte des Wächters und bringt sie zu Fenstad Argyle in Unterstadt.", progress = "Waren meine Sorgen berechtigt? Wurden unsere idiotischen Wachen überwältigt?", completion = "Es ist also wahr! Das ist unglaublich, wie konnte das nur passieren? Lasst mich einen Moment nachdenken. Es muss doch eine Ursache für all das geben.", sourceObjectiveStatus = "unverified-source-field" }
quests[11559] = { id = 11559, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Winterflossenhandel", description = "Da Ihr Euch nun mit den Winterflossen verständigen könnt, ist es an der Zeit, Euch einmal vorzustellen. Handel mit ihnen zu treiben, ist mit die beste Art und Weise, dies zu tun.\n\nMurlocs schätzen Muscheln höher als alles andere und Ihr einziger überlebender Händler nennt sich Ahlurglgr. An Eurer Stelle würde ich also eine Handvoll Winterflossenmuscheln sammeln und sie ihm zum Geschenk machen.\n\nDie Muscheln liegen überall im Graben verstreut, können jedoch auch jenseits des Grabens, im Dorf und den Höhlen der Winterflossen, gefunden werden.", sourceObjective = "Sammelt 5 Winterflossenmuscheln und liefert sie bei Ahlurglgr ab. Dieser befindet sich in der Zuflucht der Winterflossen.", progress = "Was ist das denn? Wer seid Ihr?\n\nIhr seid ein - ein {race}! Wie kommt es, dass Ihr unsere Sprache sprechen könnt?", completion = "Die sind für mich? Ist das einer Eurer Tricks, {race}? Nein?\n\nNa dann danke ich Euch! Seid stets willkommen, wenn Ihr noch mehr Muscheln habt und mit mir handeln wollt!", sourceObjectiveStatus = "unverified-source-field" }
quests[11560] = { id = 11560, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oh neeiin, die Kaulquappen!", description = "Wie gut, dass Ihr wieder da seid!\n\nAls der Erdrutsch in der Nähe des Dorfes auf der anderen Seite des Wassers die Höhlen freilegte, kam ein gehässiger Hummerstrok namens Claximus aus ihnen herausgekrochen und stahl sich mit den Kaulquappen der Winterflossen davon.\n\nIrgendetwas geschah mit den Murlocs, die ihm in die Höhlen nachfolgten, denn als sie wieder herauskamen, waren sie unter seiner Kontrolle.\n\n{class}, Ihr müsst auf die andere Seite schwimmen, im Dorf und in den Höhlen nach den Kaulquappen der Winterflossen suchen und sie in Sicherheit bringen.\n\nDie Zukunft des Winterflossenstammes liegt in Euren Händen!", sourceObjective = "König Mrgl-Mrgl möchte, dass Ihr 20 Kaulquappen der Winterflossen befreit und anschließend zu ihm zurückkehrt. Er befindet sich in der Zuflucht der Winterflossen.", completion = "Egal was passiert, die Murlocs der Winterflossen haben eine sichere Zukunft vor sich.\n\nFür Eure Selbstlosigkeit habt Ihr Lob und eine Belohnung verdient, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[11561] = { id = 11561, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die da!", description = "Unsere Brüder und Schwestern auf der anderen Seite des Wassers sind zu unseren Todfeinden geworden. Sie haben unsere Kaulquappen entführt, uns aus unserem Dorf vertrieben und mehr von meinem Volk ermordet, als ich zählen kann.\n\nErweist Euch als nützlich, {race}! Schwimmt auf die andere Seite des Grabens und metzelt sie nieder!\n\nErst dann wird es in Frage kommen, Euch hier zu akzeptieren - trotz des Wohlwollens, das Euch der neue König gezeigt hat. Und solltet Ihr es versäumen, dann könnt Ihr genauso gut jetzt gehen und nie mehr wiederkehren!", sourceObjective = "Brglmurgl in der Zuflucht der Winterflossen möchte, dass Ihr insgesamt 15 Murlocs der Winterflossen tötet, egal ob Krieger, Orakel oder Küstenschläger.", completion = "Das freut mich. Ich kann den kupfernen Geruch ihres Blutes an Euren Händen riechen.\n\nDas ist ein guter Anfang, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[11562] = { id = 11562, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mein Putzmurloc erpresst mich", description = "Ich muss Euch etwas Peinliches gestehen: Ich werde erpresst!\n\nMrmrglmr hatte sich damit einverstanden erklärt, ein paar Dinge von mir zu putzen, und dabei mein Ersatzmurlockostüm in die Finger bekommen. Er hat mir damit gedroht, den anderen Murlocs zu zeigen, wer ich wirklich bin.\n\nIch muss Euch nicht erklären, wie katastrophal das für mich wäre! Abgesehen davon habe ich mir einen Plan ausgedacht, zu dessen Umsetzung wir das Kostüm zurückbekommen müssen.\n\nIch bitte Euch, {name}, geht zu Mrmrglmr und erledigt, was auch immer er von Euch verlangt. Er befindet sich nördlich von hier, auf der anderen Seite der Zuflucht.", sourceObjective = "König Mrgl-Mrgl möchte, dass Ihr mit Mrmrglmr sprecht. Er befindet sich im nordwestlichen Teil der Zuflucht der Winterflossen.", completion = "Ah, Ihr müsst also König Mrgl-Mrgls Speichellecker sein. Ich nehme mal an, dass der Nachtelf Euch hierher geschickt hat, um mich zu beschwichtigen?\n\nGut, ich hab' genau die richtige Arbeit für jemanden, der so mächtig ist wie Ihr!", sourceObjectiveStatus = "unverified-source-field" }
quests[11563] = { id = 11563, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grmmurggll Mrllggrl Glrggl!!!", description = "Wenn Eure erbärmlichen kleinen Augen für etwas nützlich wären, könntet Ihr sehen, dass wir von den Orcas in der nördlich gelegenen Bucht abgeschlachtet werden!\n\nWenn Euer geschätzter Nachtelfenkönig sein Ersatzkostüm wirklich zurückhaben will, werdet Ihr mir bestimmt einen Gefallen tun und mir den Kopf des Königs der Orcas bringen - Glrggl: Er trotzt den Gezeiten, dem Schicksal und schwimmt... Vernichter der Hoffnung, Hoffnung auf Leben... Welle um Welle: Todesgesänge...!\n\nMacht schnell, {race}, Murlocs der Winterflossen verlieren ihr Leben, während wir hier reden und Zeit vergeuden!", sourceObjective = "Mrmrglmr will, dass Ihr mit Glrggls Kopf zu ihm zurückkehrt. Er befindet sich in der Zuflucht der Winterflossen.", progress = "Wenn Ihr Glrggls Kopf nicht dabei habt, dann verschwendet bloß nicht meine Zeit!", completion = "Nicht übel!\n\nDa der König der Orcas nun tot ist, werden die Wale untereinander um die Herrschaft kämpfen und uns weniger angreifen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11564] = { id = 11564, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deftiger Orcaeintopf", description = "Man sagt mir, {race}, dass Ihr womöglich hinter Glrggl, dem König der Orcas, her seid.\n\nDas ist ja alles schön und gut, aber wenn Ihr jemals den Eintopf schmecken wollt, für den es sich zu leben lohnt, dann werdet Ihr mir den saftigen Tran der Orcas aus der Glimmerbucht bringen müssen.\n\nBeeilt Euch... Ich hab' noch eine Menge an dem Wal hier herumzuschneiden, wenn Ihr für Eure Mühen belohnt werden wollt.", sourceObjective = "Hackebeil Bmurglbrm hat Euch damit beauftragt, 7 Einheiten saftigen Orcatran zu beschaffen. Bringt sie anschließend zu ihm in die Zuflucht der Winterflossen.", progress = "Habt Ihr genug des benötigten Orcatrans mitgebracht?", completion = "Ah, ja, das dürfte reichen.\n\nStellt die Dinger einfach irgendwo hin. Letzte Nacht ist ein wenig Eintopf übrig geblieben - könnt ein wenig davon haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[11565] = { id = 11565, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Ersatzkostüm", description = "Ausgezeichnet. Das Geheimnis Eures Königs wird von mir sicher verwahrt, solange er uns im Kampf gegen unsere Feinde unterstützt.\n\nHier, bringt dies zu ihm. Ich hab es sauber gemacht, obwohl ich keine Ahnung hab, wieso er eine zweite Verkleidung braucht.\n\nVielleicht hat er etwas mit Euch vor?", sourceObjective = "Bringt König Mrgl-Mrgls Ersatzkostüm zu ihm zurück. Er befindet sich in der Zuflucht der Winterflossen.", progress = "Habt Ihr das Ersatzkostüm dabei, {name}?", completion = "<Als er das Ersatzkostüm sieht, reibt er seine kostümierten Gliedmaßen aneinander.>\n\nSehr gut gemacht. Nun, zurück zu den wirklich dringlichen Angelegenheiten. Ich habe eine Aufgabe von äußerster Wichtigkeit für Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[11566] = { id = 11566, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ergebt Euch... nicht!", description = "Die Zeit ist gekommen, um dieser schrecklichen Situation ein Ende zu bereiten, {name}. Claximus muss sterben, wenn die Murlocs der Winterflossen eine Chance auf eine bessere Zukunft haben sollen!\n\nIch möchte, dass Ihr diesen Murlocanzug nehmt - meinen Ersatz - und in die Höhlen der Winterflossen geht. Tut so, als würdet Ihr Euch ergeben wollen, schwingt die weiße Fahne und die Murlocs werden Euch nicht angreifen.\n\nIhr findet Claximus in der südwestlichsten Ecke der Höhlen. Kümmert Euch um ihn, sobald Ihr nahe genug herangekommen seid, und bringt mir eine seiner Klauen als Beweis dafür, dass die gräuliche Tat vollbracht ist.", sourceObjective = "König Mrgl-Mrgl in der Zuflucht der Winterflossen möchte, dass Ihr ihm die Klaue von Claximus bringt.", progress = "Ist es vollbracht, {class}? Ist Claximus tot?", completion = "Bedauerlich, aber notwendig. Ich werde dann mal die Klaue an mich nehmen, wenn Ihr sie noch habt, {name}.\n\nDanke für all Eure Hilfe. Da Claximus nun besiegt ist, können wir vielleicht die verbliebenen Murlocs wieder vereinigen und diese Höhlen verschließen.\n\nIch bitte Euch, mein Freund, nehmt dies... Es ist das Mindeste, was ich für Euch angesichts Eurer Hilfe tun kann!", sourceObjectiveStatus = "unverified-source-field" }
quests[11567] = { id = 11567, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die uralte Rüstung der Kvaldir", description = "Ich war auf dem Schiff, das die Rüstung hierher bringen sollte. Wir hatten das Schiff gerade erst bestiegen und uns auf den Weg gemacht, als wir von einem Zerstörer der Verlassenen angegriffen wurden.\n\nWir wurden geentert. Sie nahmen das ganze Beutegut an sich und übergaben unser Schiff den Fluten...\n\nDas war das Letzte, was ich je von der Rüstung gesehen habe. Wenn du willst, kannst du mit meinem Bomber vom Halunkeneck zur gefürchteten Insel fliegen, wo der Zerstörer vor Anker liegt. Red' mal draußen mit meiner Frau Alanya - sie ist dein Ticket zur Insel.\n\nUnd falls du das Ding finden solltest, dann wage bloß nicht, es hierher zu bringen!", sourceObjective = "Bergt die uralte Rüstung der Kvaldir und bringt sie zu Orfus von Kamagua im Heulenden Fjord.", progress = "Habt Ihr die Rüstung gefunden?", completion = "Wir müssen alle Artefakte zurückbringen, {name}. Wenn wir alle vier an uns gebracht haben, werdet Ihr sie in die Gräber zurücklegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11568] = { id = 11568, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wieder zur Ruhe kommen lassen", description = "<Orfus reicht Euch einen Ranzen.>\n\nIn diesem Ranzen befinden sich die Artefakte, die Ihr zurückgebracht habt. Findet die Gräber des Schildhügels, die sich weit gen Südosten befinden und aus denen die Gegenstände ursprünglich gestohlen wurden, und legt die Artefakte wieder hinein. Ich hoffe, dass diese Geste den Geistern, die derzeit unsere Jagdgebiete heimsuchen, ein Zeichen sein und sie beschwichtigen wird.\n\nSeid stark, {name}...", sourceObjective = "Verwendet das Bündel mit Vrykulartefakten bei den geplünderten Grabhügeln des Schildhügels und legt das gefrorene Herz Isuldofs, den Schild der Aesiriten, den Stab des Sturmfurors und die uralte Rüstung der Kvaldir wieder zurück.\n\nKehrt zu Orfus von Kamagua am Uralten Aufzug zurück, falls Ihr erfolgreich sein solltet.", completion = "Schlimme Neuigkeiten, {name}. Mein Volk ist in Gefahr und muss gewarnt werden. Diese entarteten Seefahrer werden keine Gnade für die Kalu'ak übrig haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[11569] = { id = 11569, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlüsselmeister Urmgrgl", description = "Ich muss aus diesen Höhlen raus! Magisches Zeugs sickert durch die Wände und wirkt sich irgendwie auf unsere Gedanken aus. Es scheint von Kaltarra über uns zu kommen.\n\nIch will nicht kontrolliert werden, will nicht das Schicksal der anderen teilen!\n\nSchlüsselmeister Urmgrgl hält sich weiter unten in der Höhle gen Süden auf. Er trägt den Schlüssel für meinen Käfig bei sich. Bringt den Schlüssel hierher, damit wir meinen Käfig aufsperren und von hier verschwinden können.\n\nBeeilt Euch!", sourceObjective = "Glrglrglr in den Höhlen der Winterflossen möchte, dass Ihr Urmgrgls Schlüssel beschafft.", progress = "Habt Ihr den Schlüssel?\n\nNein, mir sind die anderen egal. Ich will hier nur raus!", completion = "Schnell, gebt her!", sourceObjectiveStatus = "unverified-source-field" }
quests[11570] = { id = 11570, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flucht aus den Höhlen der Winterflossen", description = "Das Schloss an meinem Käfig sieht zwar nicht gerade fest aus, doch fliehen würde ich ohne Unterstützung nicht - so dumm bin ich nicht.\n\nWerdet Ihr mir helfen, heil aus diesen Höhlen herauszukommen? Wir haben keine Zeit zu verlieren, {race}.\n\nLasst den König bitte wissen, dass es mir gut geht, wenn Ihr zurück zur Zuflucht gelangt. Er wird Euch sicherlich belohnen.", sourceObjective = "Eskortiert Lurgglbr, bis er in Sicherheit ist, und überbringt anschließend König Mrgl-Mrgl in der Zuflucht der Winterflossen die guten Neuigkeiten.", completion = "Das sind wundervolle Neuigkeiten! Und Ihr meint, Lurgglbr hätte entdeckt, dass die Ausströmungen aus den Höhlen diesen Wahnsinn verursachen?\n\nDas kann nur bedeuten, dass die Magie aus Kaltarra stärker wird. Der Nexuskrieg... die Schlacht zwischen dem blauen Drachenschwarm und den restlichen Drachen weitet sich aus.\n\nBald werden wir uns dem nicht mehr entziehen können!", sourceObjectiveStatus = "unverified-source-field" }
quests[11571] = { id = 11571, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lernen, wie man kommuniziert", description = "Um zu helfen, müsst Ihr Euch zuerst mit dem Dialekt der Winterflossen vertraut machen. Dazu werden wir uns die Kräfte von Natur und Magie zu Nutze machen.\n\nNehmt diese leere Muschel. Am Grunde des Wassergrabens lebt Verbrüher, Elementar des Zorns von Wasser und Luft.\n\nBenutzt die Muschel bei seinen Überresten, um seinen magischen Dampf einzufangen, sobald er besiegt ist. Kehrt mit der vollen Muschel zu mir zurück und ich werde Euch mit dem Wissen der Winterflossenzunge erfüllen.\n\nGlücklicherweise hat mir ein Freund einen Wasseratmungszauber beigebracht, den ich auf Euch wirken werde.", sourceObjective = "König Mrgl-Mrgl hat Euch eine Muschel gegeben, die Ihr bei Verbrühers Überresten benutzen sollt. Kehrt mit der gefüllten Muschel des Königs zu ihm zurück. Er befindet sich in der Zuflucht der Winterflossen.", progress = "Konntet Ihr die Muschel mit Verbrühers Dampf füllen?", completion = "Nun werde ich Verbrühers Essenz dazu benutzen können, Euch meine Sprachkenntnisse der Winterflossen zu vermitteln.", sourceObjectiveStatus = "unverified-source-field" }
quests[11572] = { id = 11572, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Atuik", description = "Kehrt zu Urahn Atuik nach Kamagua zurück. Er und der Rest meiner Leute müssen vor dem drohenden Unheil aus dem Meer gewarnt werden.\n\n<Orfus zittert vor Angst.>\n\nMit dem Uralten Aufzug könnt Ihr zu ihm gelangen. Bitte beeilt Euch!", sourceObjective = "Überbringt Urahn Atuik in Kamagua die schlechten Nachrichten.", completion = "Die Kalu'ak danken Euch für alles, was Ihr getan habt, {name}. Wir müssen uns jetzt auf den Kampf vorbereiten und unsere Brüder und Schwestern auf der anderen Seite des Meeres vorwarnen.\n\nIch hoffe, dass es noch nicht zu spät ist...", sourceObjectiveStatus = "unverified-source-field" }
quests[11573] = { id = 11573, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orfus der Kamagua", description = "Seid gegrüßt, <Reisender/Reisende>. Ich bin Lunkhauer von den Kalu'ak - oder Tuskarr, wie es in Eurer Sprache heißt. Mein Gefährte und ich wurden erst kürzlich ausgeschickt, um die seltsamen Vorgänge entlang einem unserer Jagdpfade zu untersuchen. Doch als wir auf den Friedhof namens Schildhügel zugingen, wurden wir von den Untoten angegriffen. Ich hatte Glück, es bis zu diesem Lager zu schaffen, jedoch weiß ich nicht, was mit Orfus geschehen ist.\n\nVom Uralten Aufzug aus, südöstlich von hier entlang der Klippen, gingen wir getrennte Wege. Werdet Ihr einmal nachsehen, ob alles mit ihm in Ordnung ist?", sourceObjective = "Sucht am Uralten Aufzug im Heulenden Fjord nach Orfus von Kamagua.", completion = "Lunkhauer ist am Leben? Immerhin gibt es heute ein paar gute Nachrichten zu hören...", sourceObjectiveStatus = "unverified-source-field" }
quests[11574] = { id = 11574, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zu knapp für meinen Geschmack", description = "Ich habe ihnen alles erzählt, woran ich mich erinnern kann. Wieso glauben sie mir nicht? Ich habe in der Nähe des Abgrundes nach Kräutern gesucht, als sie wie aus dem Nichts auftauchten - dunkle Magier mit magischen Biestern. Ich war umzingelt!\n\nÜber mir erschien ein riesiger magischer Würfel. Er öffnete sich und sog mich einfach auf. Ich schwöre, es ist die Wahrheit!\n\nGenau als er im Begriff war, sich zu schließen, schossen meine Retter auf den Rücken roter Drachen im Sturzflug vom Himmel. Es war atemberaubend! Meine Entführer wurden verstreut und ich konnte fliehen.\n\nIch habe ihnen niemals für meine Rettung danken können. Ich bitte Euch, {class}, findet sie und sagt ihnen meinen Dank.", sourceObjective = "Endorah möchte, dass Ihr Euch auf das Bernsteinflöz nördlich der Kriegshymnenfeste begebt und ihren Rettern ihren Dank aussprecht.", completion = "Ihr könnt Eurer Freundin erzählen, dass es eine Freude und unsere Pflicht war, sie zu retten.\n\nIhre Begegnung war in meinen Augen nichts als ein kleiner Teil eines großen Gesamtbildes.\n\nDalaran scheut keine Mühe, um dieses Geheimnis zu lüften, aber um ganz ehrlich zu sein, könnten wir etwas Hilfe gebrauchen...", sourceObjectiveStatus = "unverified-source-field" }
quests[11575] = { id = 11575, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gerade noch rechtzeitig", description = "Ich habe ihnen alles erzählt, woran ich mich erinnern kann. Wieso glauben sie mir nicht? Ich habe in der Nähe des Abgrundes nach Kräutern gesucht, als sie wie aus dem Nichts auftauchten - dunkle Magier mit magischen Biestern. Ich war umzingelt!\n\nÜber mir erschien ein riesiger magischer Würfel. Er öffnete sich und sog mich einfach auf. Ich schwöre, es ist die Wahrheit!\n\nGenau als er im Begriff war, sich zu schließen, schossen meine Retter auf den Rücken roter Drachen im Sturzflug vom Himmel. Es war atemberaubend! Meine Geiselnehmer wurden verstreut und ich konnte fliehen.\n\nIch habe ihnen niemals für meine Rettung danken können. Ich bitte Euch, {class}, findet sie und sagt ihnen meinen Dank.", sourceObjective = "Mücke in der Valianzfeste möchte, dass Ihr Euch auf das Bernsteinflöz im Norden begebt und ihren Rettern ihren Dank aussprecht.", completion = "Ihr könnt Eurer Freundin erzählen, dass es eine Freude und unsere Pflicht war, sie zu retten.\n\nIhre Begegnung war in meinen Augen nichts als ein kleines Teil eines großen Gesamtbildes.\n\nDalaran scheut keine Mühe, um dieses Geheimnis zu lüften, aber um ganz ehrlich zu sein, könnten wir etwas Hilfe gebrauchen...", sourceObjectiveStatus = "unverified-source-field" }
quests[11576] = { id = 11576, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Klamm beobachten: Spaltkliffanomalie", description = "Grüße, {race}. Ich bin Garren von Dalaran.\n\nVor nicht allzu langer Zeit war die Klamm ein friedlicher Ort - zumindest in geothermischer Hinsicht. \n\nDoch erst vor Kurzem traten mit alarmierender Regelmäßigkeit Erdbeben und Risse im Boden auf, die ein einzigartiges Energiefeld mit gigantischen Kräften freigesetzt haben.\n\nMeine Aufgabe ist es, diese Anomalien zu beobachten und aufzuzeichnen. Meine Instrumente zeigen an, dass eine weitere an der nach Südwesten ausgerichteten Klippenwand aufgetreten ist.\n\nNehmt dieses Gerät und benutzt es, wenn ihr den neuen Riss feststellt.", sourceObjective = "Garren vom Bernsteinflöz möchte, dass Ihr das Arkanometer bei der Spaltkliffanomalie benutzt.", completion = "Faszinierend!\n\nDies ist bisher der größte Riss.\n\nIch fürchte allerdings, dass uns das Schlimmste noch bevorsteht.", sourceObjectiveStatus = "unverified-source-field" }
quests[11578] = { id = 11578, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die \"Fress\"-Quest (123)aa", sourceObjective = "Tötet Koboldgezücht - und zwar 2 davon.", sourceObjectiveStatus = "unverified-source-field" }
quests[11579] = { id = 11579, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die \"Fress\"-Quest (123)aa", sourceObjective = "Tötet Koboldgezücht, und zwar 2 davon.", sourceObjectiveStatus = "unverified-source-field" }
quests[11580] = { id = 11580, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entweiht dieses Feuer!", sourceObjective = "Entweiht das Freudenfeuer der Horde im Silberwald!", sourceObjectiveStatus = "unverified-source-field" }
quests[11581] = { id = 11581, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entweiht dieses Feuer!", sourceObjective = "Entweiht das Freudenfeuer der Allianz in Westfall!", sourceObjectiveStatus = "unverified-source-field" }
quests[11582] = { id = 11582, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Klamm beobachten: Die Kluft", description = "Habt Ihr das gespürt?! Und das war nur das Nachbeben... Ihr hättet vor ein paar Minuten hier sein sollen!\n\nIch fürchte, ich muss Eure Dienste erneut in Anspruch nehmen. Meine Instrumente sagen mir, dass es westlich von hier zu einem gewaltigen Riss gekommen ist, tief unterhalb der Wasseroberfläche.\n\nWie zuvor möchte ich, dass Ihr den Arkanmeter nehmt und die Anomalie ausmesst.\n\nIch werde einen Zauber wirken, der es Euch ermöglicht, unter Wasser zu atmen. Sollte er abklingen, bevor Ihr etwas gefunden habt, so kommt zu mir zurück und ich werde ihn erneuern.", sourceObjective = "Garren vom Bernsteinflöz möchte, dass Ihr den Arkanometer bei der Kluftanomalie benutzt und mit den Messungen zu ihm zurückkehrt.", completion = "Wie groß war es?\n\nDas ist unmöglich! Ich muss das sofort nach Dalaran melden!", sourceObjectiveStatus = "unverified-source-field" }
quests[11583] = { id = 11583, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehrt die Flamme", sourceObjective = "Ehrt die Flamme von Westfall.", sourceObjectiveStatus = "unverified-source-field" }
quests[11584] = { id = 11584, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehrt die Flamme", sourceObjective = "Ehrt die Flamme des Silberwaldes.", sourceObjectiveStatus = "unverified-source-field" }
quests[11585] = { id = 11585, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Höllschreis Wacht", description = "Throm-Ka, {race}! Willkommen in der Kriegshymnenfeste. Zu sehen, dass ein solch dekorierter Held der Horde dem Ruf der Pflicht Folge leistet, erfüllt mein Herz mit Stolz!\n\nDiese uneinnehmbare Feste ist ein Beweis für die Hartnäckigkeit der Horde. Wir haben viele Schlachten schlagen müssen, um hier in Nordend Fuß zu fassen. Von hier aus wird unsere Reise zur Eiskrone beginnen und die Führungskraft von Höllschreis Sohn soll uns zum Erfolg verhelfen!\n\nGarrosh wartet unten auf Eure Ankunft.\n\nLok'tar ogar!", sourceObjective = "Sprecht mit Garrosh Höllschrei in der Kriegshymnenfeste.", completion = "Ein Held der Horde, wie?\n\n<Garrosh beschnüffelt die Luft um Euch herum.>\n\nAngst...\n\n<Garrosh spuckt auf den Boden.>\n\nIhr werdet nicht lange durchhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[11586] = { id = 11586, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Höllschreis Wacht", description = "Throm-Ka, {race}! Willkommen in der Kriegshymnenfeste. Zu sehen, dass ein solch dekorierter Held der Horde dem Ruf der Pflicht Folge leistet, erfüllt mein Herz mit Stolz!\n\nDiese uneinnehmbare Feste ist ein Beweis für die Hartnäckigkeit der Horde. Wir haben viele Schlachten schlagen müssen, um hier in Nordend Fuß zu fassen. Von hier aus wird unsere Reise zur Eiskrone beginnen und die Führungskraft von Höllschreis Sohn soll uns zum Erfolg verhelfen!\n\nGarrosh wartet unten auf Eure Ankunft.\n\nLok'tar ogar!", sourceObjective = "Sprecht mit Garrosh Höllschrei in der Kriegshymnenfeste.", completion = "Denkt bloß nicht, dass ich vergessen habe, was Ihr für mein Volk in Nagrand getan habt, {name}. Höllschrei vergisst niemals.\n\nDafür stehe ich in Eurer Schuld und aus diesem Grund gebe ich Euch jetzt diese Chance: Lauft! Verlasst diesen Ort und blickt niemals zurück.\n\nKehrt nach Hause zurück und sprecht ein Gebet für die Sterbenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[11587] = { id = 11587, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefängnisausbruch", description = "Grüße, {class}. Ich bin Donathan, ein loyaler Repräsentant Dalarans.\n\nVergebt mir mein abruptes Auftreten, aber wir befinden uns mitten in einer Krise. In ganz Azeroth werden Magier entführt und ich wurde dazu ermächtigt, jeden einzuberufen, der uns dabei helfen kann, hinter dieses Rätsel zu kommen.\n\nDas Lager gleich südlich von uns ist der Ort, an dem die Untersuchung beginnen wird. Ich fordere Euch auf, einen der dort gefangen gehaltenen Magier zu befreien. Dazu müsst Ihr den Magierjägern in der Nähe einen Schlüssel abnehmen und damit das arkane Gefängnis aufsperren.", sourceObjective = "Bibliothekar Donathan vom Bernsteinflöz möchte, dass Ihr den Beryllmagierjägern auf der Beryllspitze den Beryllkerkerschlüssel abnehmt und ihn dazu verwendet, die eingesperrten Magier aus ihren arkanen Gefängnissen zu befreien.", progress = "Ich vertraue darauf, dass Ihr unablässig daran arbeitet, einen gefangenen Magier zu befreien...", completion = "Gut gemacht, {name}.\n\nDie Kirin Tor nehmen die Hilfe, die Ihr geleistet habt, dankend entgegen. Wisset, dass kein Dienst, den Ihr uns erweist, unbelohnt bleiben wird.\n\nBitte, nehmt diese milde Gabe als Zeichen der Wertschätzung Dalarans.", sourceObjectiveStatus = "unverified-source-field" }
quests[11590] = { id = 11590, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entführung", description = "{name}, wir haben ein Problem.\n\nIch habe soeben erfahren, dass einer unserer Erzmagier, der sich auf dem Weg von Dalaran hierher befand, vermisst wird. Natürlich vermuten wir, dass die Magierjäger dahinter stecken.\n\nDie Zeit drängt. Wir müssen umgehend herausfinden, was Lady Evanor zugestoßen ist, wenn wir darauf hoffen wollen, sie zu befreien.\n\nNehmt dieses Gerät. Kehrt zur Beryllspitze zurück und wendet es auf einen Beryllzauberer an, wenn er sich kurz vor dem Tod befindet. Es sollte ihn lange genug binden, damit Ihr ihn zur weiteren Befragung hierher bringen könnt.", sourceObjective = "Donathan möchte, dass Ihr den arkanen Binder auf einen verwundeten Beryllzauberer auf der Beryllspitze anwendet und ihn anschließend auf das Bernsteinflöz bringt.", progress = "Habt Ihr einen Beryllzauberer gefangen genommen, {name}?", completion = "Ausgezeichnete Arbeit, {name}.\n\nEr wird umgehend für das Verhör bereit sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[11591] = { id = 11591, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meldet Euch bei Stahlkiefers Karawane", description = "Stahlkiefer, diese minderbemittelte Kanaille, hat versucht unsere Karawane mit Vorräten auf einer Abkürzung durch einen Friedhof der Taunka zu führen!\n\nWir haben gerade Verbindung mit ihnen aufgenommen!\n\nNun ist die Karawane dezimiert - überrannt von den Geistern der Taunka, die aus ihren Gräbern auferstanden, als er über sie trampelte.\n\nBegebt Euch nach Süden und seht, ob Ihr die Situation in den Griff bekommt, {class}. Ich habe Grunzer Zornfaust mit ein paar Anderen losgeschickt, um dort auszuhelfen.\n\nSeht doch einfach mal nach, ob Ihr ihnen zur Hand gehen könnt.", sourceObjective = "Findet Grunzer Zornfaust. Er befindet sich bei Stahlkiefers Karawane.", completion = "Das ist nicht gut, {class}.\n\nFernläufer Stolzhuf meint, dass es sich hier um die Begräbnisstätte seiner geehrten Urahnen handelt.", sourceObjectiveStatus = "unverified-source-field" }
quests[11592] = { id = 11592, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir schlagen zu!", description = "Einer unserer Orcs namens Stahlkiefer hat versucht, etwas Zeit einzusparen, indem er eine Abkürzung durch unsere Begräbnisstätte nahm. Hoffentlich ist dies nicht ein Verhalten, das die Horde üblicherweise an den Tag legt, {race}, oder die Taunka werden Euer Ende sein!\n\nDoch Ihr seht aus, als wolltet Ihr dabei helfen, die Sache wieder geradezubiegen. Gut!\n\nStahlkiefers verfluchter Geist sucht nun diesen Ort heim und stört die Überreste meiner Ahnen. Wir müssen ihm ein Ende bereiten!\n\nErstattet Eurem Oberanführer Bor'gorok beim Außenposten gen Norden Bericht, falls wir dies überstehen sollten.\n\nSteht Ihr mir bei?", sourceObjective = "Helft Fernläufer Stolzhuf und seinen Räubern des Kriegshymnenklans dabei, den Angriff auf Stahlkiefers Karawane zu überleben, und besiegt den Geist des Truppenkommandanten Stahlkiefer.\n\nMeldet Euch wieder bei Oberanführer Bor'gorok, falls Ihr erfolgreich sein solltet. Er befindet sich im Außenposten Bor'gorok.", completion = "Blut und Donner! Ihr habt unsere frisch geknüpfte Bande mit den Taunka gerettet.\n\nIch danke Euch dafür, dass Ihr die Dinge ins Lot gebracht habt. Aka'Magosh, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[11593] = { id = 11593, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die geehrten Toten", description = "Unsere Gefallenen haben das Begräbnis eines Helden verdient, doch wir können sie nicht hier auf geheiligtem Taunkaboden begraben.\n\nIch werde zwar nicht von Euch verlangen ihre Leichen hierher zurückzuschleifen, doch nehmt dies und begebt Euch weiter in den Friedhof hinein. Steckt unsere toten Karawanenwachen und -arbeiter in Brand, wenn Ihr sie findet.\n\nEhrt unsere Toten, {class}!", sourceObjective = "Grunzer Zornfaust bei Stahlkiefers Karawane möchte, dass Ihr mit Zornfausts Fackel insgesamt 10 tote Karawanenwachen oder -arbeiter in beliebiger Kombination einäschert.", completion = "Ich danke Euch, {class}. Wir sind die Horde - die Horde lässt ihre Toten nicht im Stich!\n\nEs hätte von vornherein niemals passieren dürfen. Stahlkiefer ist ein Dummkopf!", sourceObjectiveStatus = "unverified-source-field" }
quests[11594] = { id = 11594, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lasst sie zur Ruhe kommen", description = "Truppenkommandant Stahlkiefers Dummheit hat dieses Chaos verursacht. Was hat er sich dabei gedacht, als er eine Karawane durch eine Begräbnisstätte der Taunka führte?\n\nDoch was geschehen ist, ist geschehen. Und es liegt nun an uns, mit den Konsequenzen fertigzuwerden.\n\nOberanführer Bor'gorok hat mich darum gebeten, Fernläufer Stolzhuf in jeder erdenklichen Hinsicht zu unterstützen. Der Fernläufer möchte, dass wir die Geister seiner Ahnen zur Ruhe kommen lassen.\n\nWas sagt Ihr, {class}? Seid Ihr <Manns/stark> genug, mit solch einer einfachen Aufgabe fertigzuwerden?", sourceObjective = "Zerstört 20 Taunkageister, also entweder geisterhafte Weise oder wiederauferstandene Fernläufer, und geht anschließend zu Stahlkiefers Karawane und meldet Euch dort bei Grunzer Zornfaust.", completion = "Gut gemacht, {class}! Ihr müsst ja über enorme Kampferfahrung verfügen, wenn ihr es mit den Untoten aufnehmt. Und falls nicht, trifft es spätestens jetzt zu.\n\nIhr werdet sie gebrauchen können, wenn Ihr in Nordend überleben wollt.", sourceObjectiveStatus = "unverified-source-field" }
quests[11595] = { id = 11595, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verteidigung der Kriegshymnenfeste", description = "Höllschrei trägt die Last der Horde auf seinen Schultern. Lasst Euch von seinem Temperament nicht von Euren Pflichten abbringen, {name}.\n\n<Saurfang nickt Euch zu.>\n\nHabt Ihr gedacht, dass ich den Namen eines Helden von Orgrimmar vergessen würde? Es kommt nicht jeden Tag vor, dass ich das Vergnügen habe, den Kopf Nefarians aufzuspießen!\n\nDie Geißel hat mit ihrem Angriff auf diese Festung begonnen. Unsere Soldaten halten zwar stand, benötigen jedoch dringend Verstärkung. Meldet Euch bei Razgor. Er ist direkt außerhalb der Kriegshymnenfeste stationiert.", sourceObjective = "Meldet Euch bei Oberanführer Razgor in der Hütte auf der Südseite der Kriegshymnenfeste.", completion = "<Oberanführer Razgor salutiert.>\n\nEuer Ruf eilt Euch voraus, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[11596] = { id = 11596, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verteidigung der Kriegshymnenfeste", description = "Lasst Euch von Höllschrei nicht von Euren Pflichten als Soldat der Horde abbringen, {race}. Er trägt eine schreckliche Last in dieser gefrorenen Einöde, da der Ausgang seines Angriffs den Sieg über die Geißel oder die Auslöschung allen Lebens auf Azeroth bedeutet. Aus diesem Grund benötigen wir Eure Stärke und Weisheit.\n\nDie Geißel hat mit ihrem Angriff auf diese Festung begonnen. Unsere Soldaten halten zwar stand, benötigen jedoch dringend Verstärkung. Meldet Euch bei Razgor. Er ist direkt außerhalb der Kriegshymnenfeste stationiert.", sourceObjective = "Meldet Euch bei Oberanführer Razgor in der Hütte auf der Südseite der Kriegshymnenfeste.", completion = "Gerade rechtzeitig... Die Zahl der Neruber scheint sich vor gerade einer Woche verdoppelt zu haben. Wir könnten jede Hilfe gebrauchen, die wir hier draußen kriegen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[11597] = { id = 11597, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verteidigung der Kriegshymnenfeste", description = "Es scheint, als würden wir uns immer in den aussichtslosesten Situationen treffen, Skarabäusfürst. Wart Ihr bei unserem letzten Treffen nicht dabei, die Welt vor dem sicheren Untergang zu retten?\n\n<Saurfang fängt an zu kichern.>\n\nEure Unterstützung ist sehr willkommen hier in Nordend, trotz allem, was der junge Häuptling sagen mag.\n\nWenn wir nur ein Dutzend mehr Soldaten mit Eurer Stärke hätten, würden wir jetzt in Orgrimmar zusammen um ein Feuer herum sitzen.\n\nMeldet Euch bei Oberanführer Razgor. Er befindet sich gleich draußen am Haupteingang der im Süden gelegenen Kriegshymnenfeste.", sourceObjective = "Meldet Euch bei Oberanführer Razgor in der Hütte auf der Südseite der Kriegshymnenfeste.", sourceObjectiveStatus = "unverified-source-field" }
quests[11598] = { id = 11598, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Großfelsbruch zurückerobern", description = "Während die Kriegshymnenfeste zu allen Seiten hin durch zehn Fuß hohe Wälle aus Stein und Stahl geschützt ist, ist dieser Steinbruch ein leichtes Ziel und Angriffen der Neruber ausgeliefert.\n\n<Razgor deutet in Richtung Westen.>\n\nJenseits dieses Steinbruchs stehen tausende Diener der Geißel und warten auf den Angriffsbefehl. Sollten die Neruber unsere inneren Verteidigungsanlagen überwinden, werden wir von Arthas' untoten Legionen überrannt.\n\nWir dürfen das nicht zulassen - weshalb Ihr zum Angriff übergehen und die Neruber im Steinbruch abschlachten müsst.\n\nBlut und Donner, <Soldat/Soldatin>! Nehmt beides mit auf den Weg.", sourceObjective = "Oberanführer Razgor in der Kriegshymnenfeste möchte, dass Ihr 15 Neruber der Nerub'ar tötet.", completion = "Ihr habt ihren Vormarsch gebremst, doch bestimmt werden sich ihnen noch viele im Kampf anschließen. Konntet Ihr irgendwelche von den Eiersäcken finden, als Ihr im Steinbruch wart?", sourceObjectiveStatus = "unverified-source-field" }
quests[11599] = { id = 11599, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mein Bruder Thassarian", description = "Ich habe kürzlich von William Allerton, einem Familienfreund, Nachricht erhalten, dass mein Bruder am selben Tag wie er den Dienst an der Waffe hier in der Valianzfeste angetreten hat. Die Sache ist nur... mein Bruder ist bereits seit Jahren tot.\n\nAlles, was ich besaß, habe ich verkauft, um nach Thassarian zu suchen, nur um dann von den örtlichen Behörden Steine in den Weg gelegt zu bekommen. Mir wurde sogar mit einer Festnahme gedroht, falls ich weiterhin herumschnüffeln sollte.\n\nIch brauche jemanden, dem die Obrigkeiten wohlgesinnt sind... jemanden wie Euch. Wenn Ihr mir dabei helfen könntet - ich habe gehört, dass Williams in der Mine von Fernhain stationiert ist.", sourceObjective = "Sucht nach William Allerton im Inneren der Mine von Fernhain.", completion = "Die Leiche passt zu Leryssas Beschreibung von William Allerton. Seltsamerweise finden sich keine Biss- oder Kratzspuren an ihm.", sourceObjectiveStatus = "unverified-source-field" }
quests[11600] = { id = 11600, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der verstorbene William Allerton", description = "Williams Hals wurde von einem scharfen Gegenstand durchschnitten.\n\nWeitere Nachforschung gibt einen einzelnen Hinweis preis, der Leryssa nützlich sein könnte - ein Einberufungsbescheid mit dem Namen William Allerton.", sourceObjective = "Bringt den Einberufungsbescheid zu Leryssa in die Valianzfeste in der Boreanischen Tundra.", progress = "Ihr habt mit William gesprochen, {name}?", completion = "Ihr denkt also, dass Williams Tod, den er durch die Geißel gefunden hat, purer Zufall war? Da ist was faul dran, so viel ist sicher.\n\nIrgendetwas geht vor sich. Wir müssen Thassarian finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[11601] = { id = 11601, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verloren und wiedergefunden", description = "Der arme Herr Allerton könnte uns dabei helfen, meinen Bruder zu finden.\n\n<Leryssa enthüllt ein großes Buch, einem Rekrutierungsregister nicht unähnlich.>\n\nHab's mir ausgeliehen, ok? Wollen doch mal sehen, ob dieser Einberufungsbescheid ein Datum hat.\n\nWilliam sah Thassarian in der Schlange, als sie eingezogen wurden. Ihre Einträge müssen dicht nebeneinander stehen... hier ist er!\n\nEr wurde... Einheit S zugewiesen? Alle anderen Einheiten wurden nach Städten der Allianz benannt.\n\nWas für eine Einheit ist das? Wohin wurden sie geschickt? Wir sollten uns umhören. Findet heraus, ob die Gastwirte irgendetwas gehört haben.", sourceObjective = "Sprecht mit James Diakon im Gasthaus der Valianzfeste.", completion = "Kann Euch leider nicht weiterhelfen, mein Freund. Aber vielleicht kenne ich jemanden, der es kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[11602] = { id = 11602, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von der Quelle abschneiden", description = "Die Luftaufklärung des Steinbruchs berichtet, dass die Neruber ihre Eier auf den Gerüsten, welche die Basis umgeben, verstauen. Kluge Biester sind das... Sie bewahren ihre Eier an trockenen, hoch gelegenen Plätzen auf, abseits vom Brennpunkt des Konflikts.\n\nIhr werdet wieder dorthin gehen und ihre Eier ausfindig machen müssen. Findet sie, zerschmettert und zerschlagt sie.\n\nJeder Eiersack, den Ihr zerstört, bedeutet, dass sich zwanzig Neruber weniger an unseren Leichen gütlich tun.", sourceObjective = "Oberanführer Razgor in der Kriegshymnenfeste möchte, dass Ihr 10 Eiersäcke der Nerub'ar zerstört.", completion = "Trotz unserer Bemühungen kommen immer mehr. So kann es nicht weitergehen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[11603] = { id = 11603, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In vino veritas", description = "Das Militär war alles, was dem alten Paßbrand blieb. Selbst nachdem er in den Ruhestand gegangen war, klammerte er sich daran wie an sein eigenes Leben.\n\nEr kennt den Namen jedes Generals, jeder Einheit, Brigade und Abteilung... einfach alles. Er ist der Mann, nach dem Ihr sucht.\n\nDas Problem ist nur, dass er vom Schicksal gezeichnet ist. Er spricht mit niemandem, außer er bekommt seinen Wein der Kul Tiras. Erinnert ihn an die Zeiten, als er bei der Marine war.\n\nIch habe schon seit Monaten keine Lieferung mehr bekommen. Das letzte Schiff aus Kul Tiras ist nordöstlich von hier gesunken. Versucht doch eine Flasche von dort zu bergen und sie Paßbrand zu bringen.", sourceObjective = "Bergt eine Flasche Wein der Kul Tiras aus dem gesunkenen Schiffswrack nordöstlich der Valianzfeste und bringt sie zum alten Paßbrand im Gasthaus der Valianzfeste.", progress = "<Der alte Mann sieht mit ausdruckslosem Blick zu Euch auf.>", completion = "Mmmmm... nicht zu bitter... nicht zu trocken... das ist wie in alten Tagen, als ich gemeinsam mit den Jungs beim Militär war.", sourceObjectiveStatus = "unverified-source-field" }
quests[11604] = { id = 11604, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Deserteur", description = "Einheit S... Einheit S... hmmm... ergibt keinen Sinn... sollte nach einer Stadt benannt sein...\n\nDunkelhain wurde in die Drachenöde geschickt. Die Goldhainjungs in den Fjord. Wo hab ich das nochmal gehört...\n\nAch ja... der Deserteur! Da ist ein Fahnenflüchtiger im Gefängnis der Kaserne. Wurde erst vor Kurzem hineingeworfen. Sagte immer wieder, dass \"S\" für Selbstmord stünde.\n\nSucht nach dem Deserteur. Er hat vielleicht ein paar Informationen für Euch.", sourceObjective = "Findet das Gefängnis in der inneren Festung der Valianzfeste und sprecht mit dem Deserteur.", completion = "Was'n los? Probleme hab' ich genug!", sourceObjectiveStatus = "unverified-source-field" }
quests[11605] = { id = 11605, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die geehrten Ahnen", description = "<Eine fern klingende Stimme hallt in Eurem Kopf wider, als Ihr Euch die Steinstatue anseht.>\n\nLasst Euch nicht erschrecken, <Fremder/Fremde>. Ich bin Ältester Atkanok, ein uralter Ahne des Tuskarrvolkes, ein geübter Handwerker zu meiner Zeit und seit Jahrhunderten der Wächter dieses Steinbruchs.\n\nDer Steinbruch wurde überrannt, wodurch meine Statuen nicht fertig gebaut werden konnten, während die Geister der Ahnen auf der Welt umherwandeln. Werdet Ihr mir helfen, dies wieder zurecht zu biegen?\n\nAls Erstes muss ich die Namen der wandelnden Ahnen wissen. Sucht nach den Markierungen in der Nähe der Statuen.", sourceObjective = "Ältester Atkanok außerhalb des Froststeinbruchs möchte, dass Ihr die Statuen des Ältesten Kesuk, Ältesten Sagani und Ältesten Takret identifiziert.", progress = "<Die ferne Stimme erklingt wieder.>\n\nHabt Ihr die Namen der umherwandelnden Ältesten herausfinden können?", completion = "<Die Stimme des Ältesten Atkanok grüßt Euch, als Ihr seiner Statue nähertretet.>\n\nGut gemacht, {name}. Da wir nun die Namen der umherwandelnden Ältesten haben, können wir mit den durch die Angriffe gestörten Zeremonien weitermachen. Bevor die Geister der Ältesten jedoch zu ihren Steinen geführt werden können, müssen wir die Geister der ermordeten Handwerker und Schamanen besänftigen. Sonst erhören die Geister der Ahnen den Ruf der Zeremonie womöglich nie.", sourceObjectiveStatus = "unverified-source-field" }
quests[11606] = { id = 11606, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geduld ist eine Tugend, die wir nicht brauchen", description = "Wir können so viele Neruber töten und so viele Eier zerstören, wie wir wollen - immer werden neue nachkommen, solange wir ihre Tunnel und Versorgungsschächte nicht sprengen. Natürlich können wir das nicht machen, wenn wir keine schwere Munition haben. Unglücklicherweise wird der Großteil unseres Vorrats von den Goblins und Schmieden für unsere Belagerungspanzer und Waffen verwendet.\n\nDoch zufälligerweise haben wir einen beträchtlichen Vorrat von dem Zeug drüben im Großfelsbruch, unter all dem nerubischen Mist. Ihr müsst nur dorthin gehen und es mir bringen.", sourceObjective = "Rüstmeister Holgoth in der Kriegshymnenfeste möchte, dass Ihr 15 Kisten mit Munition des Kriegshymnenklans besorgt.", progress = "Uns rennt die Zeit davon, {class}.", completion = "Wenn meine Berechnungen stimmen - was sie oft nicht tun -, dann werdet Ihr ungefähr 10 bis 20 Zephyriumtiefenladungen benötigen.\n\nAch, und Ihr werdet die Süßen in ihren Schlundlöchern platzieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[11607] = { id = 11607, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verlorene Geister", description = "Bei dem Angriff auf den Steinbruch wurden die Handwerker und Schamanen, die dort arbeiteten, getötet. Die Gewalt riss die Geisterwelt in absolutes Chaos und wir werden den Ahnen nicht den Weg nach Hause weisen können, wenn wir keinen Weg finden, die Geister der Ermordeten zu besänftigen.\n\nDie Angreifer selbst schenken den Geistern keine Beachtung, doch ihre Begleiter, die Beryllhunde, können die Geister spüren und lassen kein Auge von ihnen ab.\n\nRäumt die Beryllhunde aus dem Weg und befreit mithilfe der rohen Energie, die übrig bleibt, die Geister der Unschuldigen aus ihrem Gefängnis.", sourceObjective = "Ältester Atkanok am äußeren Rand des Froststeinbruchs möchte, dass ihr die Geister von 3 Handwerkern von Kaskala und 3 Schamanen von Kaskala befreit.", progress = "Wie ergeht es den Geistern der Unschuldigen?", completion = "Ich kann spüren, dass der Aufruhr in der Geisterwelt sich zu legen beginnt. Ihr habt gute Arbeit geleistet, {name}. Die Geister der Ahnen können sich glücklich schätzen, Eure Hilfe in diesen Zeiten der Not zu haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[11608] = { id = 11608, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Begrabt diese Kakerlaken!", description = "Norden, Süden, Osten und Westen: Dort liegen die Orte, um die Ihr Euch Sorgen machen solltet. Diese Festung, die sich mitten im Großfelsbruch befindet, ist von vier ideal gelegenen Schlundlöchern der Nerub'ar umringt.\n\n<Holgoth reicht Euch ein Bündel.>\n\nGeht sehr vorsichtig mit diesem Paket um, {name}. Ein falscher Handgriff und Ihr seid Hundefutter.\n\nIn dem Bündel befinden sich Zephyriumsprengsätze. Begebt Euch zu jedem der Schlundlöcher der Nerub'ar und platziert eine Ladung in der Mitte. Wenn alles gut geht, werden die Tunnel einstürzen.\n\nNun bewegt Euch!", sourceObjective = "Rüstmeister Holgoth in der Kriegshymnenfeste möchte, dass Ihr mithilfe des Bündels mit Zephyriumsprengsätzen die Schlundlöcher der Nerub'ar zerstört. Diese befinden sich südlich, östlich, westlich und nördlich der Kriegshymnenfeste.", completion = "Das wird sie aufhalten - zumindest denke ich, dass es das wird. Wie dem auch sei, Ihr habt Euren Teil erledigt. Und das ist alles, was sich ein Orc wünschen kann, oder nicht?", sourceObjectiveStatus = "unverified-source-field" }
quests[11609] = { id = 11609, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Reste beseitigen", description = "Nun, da die Geister der ermordeten Handwerker und Schamanen zur Ruhe gekommen sind, gibt es nichts, was uns davon abhalten könnte, die durch den Angriff unterbrochenen Zeremonien abzuschließen. Ihr müsst die Rolle übernehmen, die traditionell einem Schamanen der Tuskarr vorbehalten ist, und Ihr müsst über alle notwendigen Ritualgegenstände verfügen.\n\nWir haben keine Zeit, neue zu fertigen, also werdet Ihr den Steinbruch nach den Gegenständen absuchen, die von den Opfern des Angriffs zurückgelassen wurden. Geht mit den Objekten vorsichtig um, {name}, denn einige sind Hunderte von Jahren alt. Womöglich werdet Ihr sie den Händen der Eindringlinge entreißen müssen.", sourceObjective = "Bringt Ältester Atkanok 6 Ritualobjekte der Tuskarr. Er befindet sich außerhalb des Froststeinbruchs.", progress = "Habt Ihr alle benötigten Ritualgegenstände besorgen können?", completion = "<Ihr haltet die Objekte vor der Statue des Ältesten Atkanok hoch.>\n\nDas wird genügen, obwohl sie sich in einem traurigen Zustand befinden. Einige von ihnen wurden Jahrhunderte lang benutzt, um am Ende von Barbaren gestohlen und ramponiert zu werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[11610] = { id = 11610, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ahnen nach Hause führen", description = "Dank Eurer Hilfe können die Geister der Ahnen nun zu ihren rechtmäßigen Stätten geführt werden, den Statuen, die von den Handwerkern der Kaskala und Schamanen liebevoll hergestellt wurden.\n\nDie Zeremonien für diese Ahnen wurden während des Angriffs auf den Steinbruch unterbrochen und Ihr werdet sie zu Ende bringen müssen. Nehmt die Objekte, die Ihr aus dem Steinbruch beschafft habt, stellt Euch vor die Statuen mit den Namensschildern und tragt diesen Sprechgesang vor.\n\n<Worte in einer fremden Sprache durchströmen Euren Kopf, doch Ihr habt keine Schwierigkeiten, Euch an sie zu erinnern.>", sourceObjective = "Ältester Atkanok möchte, dass Ihr die Geister des Ältesten Kesuk, Ältesten Sagani und Ältesten Takret zu ihren Steinmonumenten geleitet.", completion = "Die Ahnen haben ihre Statuen gefunden und Euch gebührt ihr Dank, {name}. Die Handwerker von Kaskala werden in den Steinbruch zurückkehren und sicherstellen, dass die Blutlinie der Ahnen ungebrochen weitergeht. Für unseren Teil werden wir, die Ahnen, Euch weiterhin mit Interesse beobachten, da Euer Weg anscheinend gerade erst begonnen hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[11611] = { id = 11611, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von der Geißel eingenommen", description = "<Mortuus seufzt.>\n\nPeons... Wir könnten genauso gut ein Schild aufstellen, das den Nerub'ar eine freie Mahlzeit verspricht.\n\nSeht, das Problem mit Peons ist, dass sie: (1.) dumm wie Brot sind und sie (2.) schwächer sind als ein aussätziger Gnom. Kein Wunder, dass die Geißel sich sie als Erstes vorknöpft.\n\nDas versetzt mich in eine relativ prekäre Lage: Ohne Peons kommt die Arbeit zum Erliegen. Keine Peons, kein Bau.\n\nFindet und befreit meine Peons, {race}. Falls sie am Leben sind, solltet Ihr sie im Großfelsbruch in Netze eingesponnen vorfinden.", sourceObjective = "Großknecht Mortuus in der Kriegshymnenfeste möchte, dass Ihr 5 Peons des Kriegshymnenklans befreit.", progress = "Keine Peons, keine Bauten. Und nein, wir werden sie nicht durch Goblins ersetzen. Viel zu teuer...", completion = "Die meisten von ihnen haben es zurückgeschafft. Zumindest diejenigen, die klug genug waren, um zu wissen, dass wir uns in dem gigantischen Stein- und Stahlgebäude befinden...\n\nAbgesehen davon habt Ihr gute Arbeit geleistet. Habe gehört, dass Ihr mehr als ein Dutzend von ihnen da rausgeholt habt.\n\nOh ja, wie soll ich sagen... Ihr seid hier in der Feste in aller Munde...", sourceObjectiveStatus = "unverified-source-field" }
quests[11612] = { id = 11612, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Steinbruch zurückerobern", description = "Ihr seid hier gerne gesehen, {class}. Mein Name ist Etaruk und ich war einmal ein Handwerker hier im Froststeinbruch.\n\nMeine Gefährten und ich waren gerade dabei, mehrere neue Statuen für die aller neuesten Riten vorzubereiten, als wir sahen, wie diese geheimnisvollen blauen Plattformen über unser Plateau geflogen kamen.\n\nAls sie landeten, strömte ein Schwarm von Magiern, die sich auf ihnen befanden, in den Steinbruch, plünderten und ermordeten meine Freunde. Wenn wir sie nicht aufhalten, werden sie unsere Statuen zerstören und sich mit unseren Artefakten davonmachen. Werdet Ihr mir dabei helfen, die Eindringlinge zu besiegen?", sourceObjective = "Etaruk möchte, dass Ihr 12 Beryllschatzjäger tötet. Er befindet sich in der Nähe des Eingangs zum Froststeinbruch.", progress = "Habt Ihr damit begonnen, den Steinbruch von unseren Feinden zu befreien?", completion = "Da nun diese seltsamen Magier wissen, dass die Leute von Kaskala und ihre Alliierten den Steinbruch nicht so leicht aufgeben werden, müssen wir uns erst recht bemühen und sie endgültig besiegen.\n\nMeine Brüder in Kaskala wurden auch angegriffen und werden uns nicht unterstützen können. Doch mit Eurer Hilfe, {name}, können wir die Plünderer überwältigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11613] = { id = 11613, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Karuks Schwur", description = "Sie nennen sich selbst die Kvaldir. Mein Volk erzählt sich Legenden über sie. Wir nennen sie die Tuk-Hariq - die Läufer des Nebels.\n\nMein Dorf wurde von diesen riesigen Dunstkerlen zerstört. Jeder, den ich kannte, wurde von ihnen erschlagen, auch mein Vater Ariut.\n\nDas Gesetz der Tuskarr fordert von mir Vergeltung an jenen zu üben, die das Blut meiner Verwandten vergossen.\n\nIch bin nichts weiter als ein Fischer und habe noch nicht die Reifeprüfung zum Mann hinter mir... Ich kann den niederträchtigen Kvaldir noch nicht auf Augenhöhe begegnen.\n\nIch stünde tief in Eurer Schuld, wenn Ihr in meinem Namen Blutrache übtet.", sourceObjective = "Karuk möchte, dass Ihr 6 Räuber der Skadir und 5 Langbootsmänner der Skadir tötet.", progress = "Wart Ihr erfolgreich, {race}? Die Kvaldir sind grausame {class}. Erwartet kein Pardon von ihnen.", completion = "Ihr habt meinem Volk einen großen Gefallen erwiesen, {name}. Ich muss Euch jedoch noch um eine Sache bitten.", sourceObjectiveStatus = "unverified-source-field" }
quests[11614] = { id = 11614, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schweigen ist Gold", description = "Wir sind auf Befehl von Varimathras hier! Die Mission der Schattenpirscher ist einfach: spionieren. Nun, spionieren und ein kleiner Meuchelmord am Rande.\n\nEiner meiner besten Agenten wird vermisst. Ich habe schon seit Tagen nichts mehr von ihm gehört, weshalb ich das Schlimmste befürchte. Und ich meine nicht den Tod - sein Tod wäre ideal! Ich befürchte, dass er uns hintergeht... vielleicht sogar zum Verräter wurde.\n\nSein letzter bekannter Aufenthaltsort ist der nördlich gelegene Großfelsbruch. Er war im Begriff, sensible Informationen über die Neruber zu sammeln. Findet ihn...\n\nam besten tot...", sourceObjective = "Findet Schattenpirscher Luther im Großfelsbruch.", completion = "Viel toter geht's wohl kaum... Seltsamerweise haben die Neruber die Leiche nicht verschlungen.\n\nNach genauer Untersuchung sehr Ihr, dass Luther seinen Tod selbst herbeigeführt hat - mit tödlichem Gift. Klug. Neruber werden sich nicht in die Nähe dieser vergifteten Leiche wagen.\n\nIhr bemerkt, dass Luther ein Tagebuch in Händen hält.", sourceObjectiveStatus = "unverified-source-field" }
quests[11615] = { id = 11615, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnisse der Nerub'ar", description = "Ihr blättert durch die Seiten des Buchs und sucht nach Allem, das von Interesse sein könnte. Auf der letzten Seite stolpert Ihr über mehrere Einträge hektischen Gekritzels.\n\nNekrolords. Habe mindestens ein Dutzend gezählt.\n\nHöfe im Westen sind eine Art Brutstätte der Geißel.\n\nUnzählige Opfer.\n\nDenke, die haben es auf mich abgesehen. Habe mich auf zur Feste gemacht. Lebend bekommen die mich nicht.\n\nSchreckensgift - Haemotoxin. Die werden eine Überraschung erleben, wenn sie mich beißen.\n\nBringt dieses Schreiben zu Barthus.", sourceObjective = "Bringt Luthers Tagebuch zu Schattenpirscher Barthus in der Kriegshymnenfeste.", progress = "Ist er tot?", completion = "<Barthus schlägt die letzte Seite des Tagebuchs auf und fängt an zu lesen.>\n\nDas sind sehr schlechte Neuigkeiten. Höllschrei muss umgehend davon erfahren.", sourceObjectiveStatus = "unverified-source-field" }
quests[11616] = { id = 11616, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachricht an Höllschrei", description = "<Barthus reißt die letzte Seite heraus und rollt sie zusammen.>\n\nBringt dies sofort zu Höllschrei! In der Zwischenzeit werde ich eine Gruppe ausschicken, die die Höfe auskundschaften soll.\n\nIhr müsst Höllschrei auf jeden Fall davon unterrichten, dass wir Verstärkung benötigen werden.", sourceObjective = "Bringt Barthus' Notiz zu Höllschrei in der Kriegshymnenfeste.", progress = "Was hat diese Störung zu bedeuten? Bürdet mir keinen Unsinn auf!", completion = "<Höllschrei liest den Tagebucheintrag.>\n\nIst das alles?", sourceObjectiveStatus = "unverified-source-field" }
